-- Owner-approved release: only TCF Reading Tests 07-14 v4, from reviewed PR #75 commit ef152df7d4a977532c24ff5261db3c710f69b4db.
-- Preserve Tests 01-06 (v6), Tests 15-20 (v3), all historical banks, and student attempts.
begin;
select pg_advisory_xact_lock(hashtext('hzad-tcf-reading-07-14-v4-publication'));
create temp table release_reading_07_14_before on commit drop as
select
(select count(*) from academy_tcf_reading.papers) as old_bank_count,
(select count(*) from academy_tcf_reading.attempts) as attempt_count,
(select md5(coalesce(string_agg(to_jsonb(a)::text, '' order by id),'')) from academy_tcf_reading.attempts a) as attempts_digest,
(select md5(coalesce(string_agg(to_jsonb(p)::text, '' order by id,version),'')) from academy_tcf_reading.papers p) as original_banks_digest;
create temp table release_reading_07_14_other_pointers on commit drop as
select test_id,version from academy_tcf_reading.published_papers
where test_id not in ('tcf-reading-07','tcf-reading-08','tcf-reading-09','tcf-reading-10','tcf-reading-11','tcf-reading-12','tcf-reading-13','tcf-reading-14');
do $preflight$ begin
 if (select count(*) from academy_tcf_reading.published_papers)<>20 then raise exception 'Expected exactly 20 reading catalog entries'; end if;
 if (select count(*) from academy_tcf_reading.published_papers where test_id in ('tcf-reading-07','tcf-reading-08','tcf-reading-09','tcf-reading-10','tcf-reading-11','tcf-reading-12','tcf-reading-13','tcf-reading-14') and version='tcf-reading-2026-11-reference-v3')<>8 then raise exception 'Expected eight old v3 pointers; release aborted'; end if;
 if (select count(*) from academy_tcf_reading.papers where id in ('tcf-reading-07','tcf-reading-08','tcf-reading-09','tcf-reading-10','tcf-reading-11','tcf-reading-12','tcf-reading-13','tcf-reading-14') and version='tcf-reading-2026-11-close-reading-v4')<>0 then raise exception 'Immutable v4 bank already exists; release aborted'; end if;
 if (select count(*) from academy_tcf_reading.published_papers where test_id between 'tcf-reading-01' and 'tcf-reading-06' and version='tcf-reading-2026-11-close-reading-v6')<>6 then raise exception 'First six publication pointers changed; release aborted'; end if;
 if (select count(*) from academy_tcf_reading.published_papers where test_id between 'tcf-reading-15' and 'tcf-reading-20' and version='tcf-reading-2026-11-reference-v3')<>6 then raise exception 'Last six publication pointers changed; release aborted'; end if;
end $preflight$;
insert into academy_tcf_reading.papers(id,version,content) values
('tcf-reading-07','tcf-reading-2026-11-close-reading-v4',$bank_7${"id":"tcf-reading-07","title":"TCF Reading · Test 07","seconds":3600,"version":"tcf-reading-2026-11-close-reading-v4","maxPoints":699,"questions":[{"number":1,"points":3,"correct":"B","options":["L'ouverture de la poissonnerie","Le retrait de commandes payées","La livraison sans commande","L'achat libre sur tous les stands"],"passage":"Le marché couvert ferme à quatorze heures aujourd'hui. Les commandes déjà payées pourront être retirées jusqu'à quinze heures à l'entrée nord.\n\nPrésentez votre reçu au personnel chargé des retraits. Les stands alimentaires ne reprendront pas de vente après la fermeture annoncée.","question":"Quel service reste disponible après la fermeture ?","explanation":"Le passage indique : « Le marché couvert ferme à quatorze heures aujourd'hui. Les commandes déjà payées pourront être retirées jusqu'à quinze heures à l'entrée nord. » Cela justifie la réponse : Le retrait de commandes payées."},{"number":2,"points":3,"correct":"C","options":["De la levure","De la farine","Un saladier","Un four"],"passage":"Pour l'atelier pain, apportez un saladier. La farine et la levure sont fournies.\n\nLes participants travailleront par petits groupes. Un rangement collectif est prévu à la fin de la séance.","question":"Que doit apporter le participant ?","explanation":"Le passage indique : « Pour l'atelier pain, apportez un saladier. La farine et la levure sont fournies. » Cela justifie la réponse : Un saladier."},{"number":3,"points":3,"correct":"A","options":["Utiliser un contenant propre","Apporter un sac en papier","Acheter uniquement en espèces","Réserver une semaine avant"],"passage":"Le distributeur de lait ne fonctionne qu'avec des bouteilles propres. Des bouteilles neuves sont vendues à côté.\n\nUn membre de l'équipe peut montrer comment remplir le récipient. Merci de laisser l'espace propre après votre passage.","question":"Quelle condition faut-il respecter ?","explanation":"Le passage indique : « Le distributeur de lait ne fonctionne qu'avec des bouteilles propres. Des bouteilles neuves sont vendues à côté. » Cela justifie la réponse : Utiliser un contenant propre."},{"number":4,"points":3,"correct":"D","options":["À l'entrée de la salle","Le lendemain du repas","Après le dessert","Au moment de l'inscription"],"passage":"Le menu végétarien doit être demandé lors de l'inscription au repas associatif, pas à l'arrivée.\n\nL'équipe préparera les quantités selon les demandes reçues. Elle ne pourra pas garantir un remplacement de plat au dernier moment.","question":"Quand faut-il signaler ce choix ?","explanation":"Le passage indique : « Le menu végétarien doit être demandé lors de l'inscription au repas associatif, pas à l'arrivée. » Cela justifie la réponse : Au moment de l'inscription."},{"number":5,"points":9,"correct":"D","options":["La personne préparant la salade","Le nombre d'invités","Le jour du rendez-vous","Le lieu du repas"],"passage":"J'ai remplacé le pique-nique par un déjeuner chez moi : la pluie est annoncée. Apporte toujours la salade, je préparerai le plat chaud.\n\nLes autres invités ont déjà été prévenus et garderont le même horaire. Nous mangerons autour de la grande table, puis pourrons sortir si le temps s'améliore.","question":"Qu'est-ce qui change dans le programme ?","explanation":"Le passage indique : « J'ai remplacé le pique-nique par un déjeuner chez moi : la pluie est annoncée. Apporte toujours la salade, je préparerai le plat chaud. » Cela justifie la réponse : Le lieu du repas."},{"number":6,"points":9,"correct":"C","options":["Un restaurant réservé aux adhérents","Un cours obligatoire de jardinage","Des conseils pour préparer les légumes","Un remboursement de tous les achats"],"passage":"Votre panier contient des légumes moins habituels. Une fiche de préparation est jointe ; vous pouvez aussi échanger un produit au point de retrait.\n\nLes bénévoles indiquent également les quantités habituelles pour éviter de préparer trop de nourriture.","question":"Quelle aide accompagne le panier ?","explanation":"Le passage indique : « Votre panier contient des légumes moins habituels. Une fiche de préparation est jointe ; vous pouvez aussi échanger un produit au point de retrait. » Cela justifie la réponse : Des conseils pour préparer les légumes."},{"number":7,"points":9,"correct":"C","options":["Une place en terrasse","Un repas gratuit","Une table en salle","Une heure de départ libre"],"passage":"Le restaurant ne réserve plus sa terrasse. Les tables sont attribuées sur place ; la réservation reste possible à l'intérieur.\n\nSi le temps reste agréable, vous pourrez demander une table extérieure à votre arrivée. Le personnel expliquera les disponibilités sans pouvoir les promettre à l'avance.","question":"Que garantit une réservation ?","explanation":"Le passage indique : « Le restaurant ne réserve plus sa terrasse. Les tables sont attribuées sur place ; la réservation reste possible à l'intérieur. » Cela justifie la réponse : Une table en salle."},{"number":8,"points":9,"correct":"B","options":["Prévoir deux desserts par personne","Adapter la quantité aux personnes qui en mangeront","Conserver tout le gâteau pour le lendemain","Réduire le nombre d'invités"],"passage":"Je préfère commander le petit gâteau pour six personnes. Nous serons huit, mais deux invités ne prennent jamais de dessert.\n\nNous partagerons les autres plats sans changer le reste du repas ni demander un format plus grand.","question":"Pourquoi choisir ce format ?","explanation":"Le passage indique : « Je préfère commander le petit gâteau pour six personnes. Nous serons huit, mais deux invités ne prennent jamais de dessert. » Cela justifie la réponse : Adapter la quantité aux personnes qui en mangeront."},{"number":9,"points":9,"correct":"A","options":["Acheter une huile","Respecter l'heure du rendez-vous","S'inscrire à la dégustation","Goûter dans le lieu prévu"],"passage":"La dégustation permet de goûter trois huiles avant achat. Aucun achat n'est imposé aux participants.\n\nLes organisateurs présenteront l'origine des produits et quelques usages possibles. Le rendez-vous est destiné aux curieux comme aux clients habituels du magasin.","question":"Quelle obligation est absente ?","explanation":"Le passage indique : « La dégustation permet de goûter trois huiles avant achat. Aucun achat n'est imposé aux participants. » Cela justifie la réponse : Acheter une huile."},{"number":10,"points":9,"correct":"D","options":["Pour réserver les aliments aux commerçants","Pour interdire les dons gratuits","Pour privilégier les emballages décoratifs","Pour disposer d'informations vérifiables sur les produits"],"passage":"Merci de ne pas déposer de plats faits maison dans le réfrigérateur solidaire. Seuls les produits dont la composition et la date sont identifiables sont acceptés.\n\nUne affiche rappelle les conditions d'accueil pour éviter que des aliments inutilisables soient déposés à côté du réfrigérateur.","question":"Pourquoi certains dépôts sont-ils exclus ?","explanation":"Le passage indique : « Merci de ne pas déposer de plats faits maison dans le réfrigérateur solidaire. Seuls les produits dont la composition et la date sont identifiables sont acceptés. » Cela justifie la réponse : Pour disposer d'informations vérifiables sur les produits."},{"number":11,"points":15,"correct":"B","options":["Un choix toujours identique","La variation saisonnière du panier","Une livraison quotidienne obligatoire","L'absence de légumes locaux"],"passage":"Une ferme vend ses légumes selon les récoltes disponibles. Le contenu des paniers change chaque semaine ; un assortiment identique toute l'année n'est pas promis.\n\nLes adhérents choisissent un point de retrait et reçoivent les informations quelques jours avant la livraison. Une récolte abondante peut permettre un produit supplémentaire, tandis qu'un épisode de grêle oblige à revoir l'assortiment. Le producteur explique ces changements au lieu de remplacer systématiquement les légumes par des achats lointains. Le groupe souhaite conserver une relation claire entre ce qui pousse sur les terres et ce qui arrive dans les paniers.","question":"Quelle caractéristique faut-il accepter ?","explanation":"Le passage indique : « Une ferme vend ses légumes selon les récoltes disponibles. Le contenu des paniers change chaque semaine ; un assortiment identique toute l'année n'est pas promis. » Cela justifie la réponse : La variation saisonnière du panier."},{"number":12,"points":15,"correct":"A","options":["Une découverte progressive","Un changement de menu quotidien imposé","Une consommation forcée","La suppression de tout choix"],"passage":"Une cantine présente un nouvel aliment en petite quantité avant de l'ajouter au menu. Les élèves peuvent le goûter sans devoir finir une grande portion.\n\nLe personnel de cuisine observe les retours et recueille les remarques sans distribuer de note. Les enseignants peuvent préparer la découverte en parlant de l'origine du produit. L'équipe souhaite distinguer le refus d'un goût inconnu et celui d'une préparation particulière.","question":"Quelle approche est choisie ?","explanation":"Le passage indique : « Une cantine présente un nouvel aliment en petite quantité avant de l'ajouter au menu. Les élèves peuvent le goûter sans devoir finir une grande portion. » Cela justifie la réponse : Une découverte progressive."},{"number":13,"points":15,"correct":"A","options":["Une attention continue à la préparation","Le remplacement de la farine par de l'eau","L'absence de toute organisation","L'arrêt définitif des fournées"],"passage":"Le boulanger conserve une pâte d'une fournée à l'autre. Cette pratique demande un suivi régulier ; elle ne permet pas de laisser la préparation sans surveillance.\n\nLe boulanger vérifie l'odeur, la texture et le temps écoulé avant de préparer la suite. Il ajuste certains gestes selon la température de l'atelier. Les apprentis découvrent qu'une recette écrite ne suffit pas toujours à décider du bon moment. Le responsable leur demande de noter leurs observations et de comparer plusieurs fournées. Il souhaite transmettre cette attention au processus, plutôt que promettre une méthode qui fonctionnerait de manière identique sans aucun contrôle des conditions réelles.","question":"Que nécessite cette méthode ?","explanation":"Le passage indique : « Le boulanger conserve une pâte d'une fournée à l'autre. Cette pratique demande un suivi régulier ; elle ne permet pas de laisser la préparation sans surveillance. » Cela justifie la réponse : Une attention continue à la préparation."},{"number":14,"points":15,"correct":"C","options":["L'accès sans limite aux stocks des autres","La fermeture aux nouveaux producteurs","Le respect des créneaux et du nettoyage","La préparation simultanée sans réservation"],"passage":"Une association partage une cuisine entre plusieurs petites entreprises. Les utilisateurs réservent des plages distinctes et nettoient après chaque passage.\n\nLes réservations passent par un tableau commun et les produits restent dans des espaces identifiés. Le responsable présente les équipements à chaque nouveau groupe. Il souhaite éviter qu'un gain économique sur le local entraîne des difficultés de propreté ou de rangement. Les utilisateurs ont donc rédigé des règles simples après avoir essayé plusieurs organisations. Un bilan mensuel permettra de revoir les points qui posent problème sans attendre qu'une dispute entre deux entreprises bloque l'ensemble du fonctionnement de la cuisine.","question":"Quelle règle rend le partage possible ?","explanation":"Le passage indique : « Une association partage une cuisine entre plusieurs petites entreprises. Les utilisateurs réservent des plages distinctes et nettoient après chaque passage. » Cela justifie la réponse : Le respect des créneaux et du nettoyage."},{"number":15,"points":15,"correct":"A","options":["Les ingrédients peuvent changer","La cuisine refuse toute question","Les allergies disparaissent au restaurant","Les indications sont volontairement fausses"],"passage":"Le chef ajoute des indications d'allergènes au menu. Il demande néanmoins aux clients concernés d'en parler à l'équipe, car certaines préparations peuvent évoluer.\n\nLes serveurs disposent d'une fiche commune, mais sont invités à demander confirmation lorsqu'une information manque. Le restaurant souhaite que les clients puissent exprimer leurs besoins sans recevoir une assurance improvisée. Les responsables expliquent aussi les limites liées au travail dans une même cuisine. Ils préfèrent donner une réponse précise, même si elle oblige à renoncer à un plat, plutôt que présenter le menu comme une garantie identique pour toutes les situations ou toutes les modifications demandées pendant le service.","question":"Pourquoi un échange reste-t-il nécessaire ?","explanation":"Le passage indique : « Le chef ajoute des indications d'allergènes au menu. Il demande néanmoins aux clients concernés d'en parler à l'équipe, car certaines préparations peuvent évoluer. » Cela justifie la réponse : Les ingrédients peuvent changer."},{"number":16,"points":15,"correct":"C","options":["Éviter toute dégustation","Mémoriser le prix des serres","Reconnaître une diversité au sein d'un aliment","Choisir uniquement la plus grosse tomate"],"passage":"Un jardin pédagogique cultive plusieurs variétés d'une même tomate. Les enfants comparent formes et goûts plutôt que classer toutes les tomates dans une seule catégorie.\n\nChaque groupe suit quelques plants et note leurs changements avant les récoltes. Une dégustation sera organisée lorsque les fruits seront mûrs. Les enseignants demandent aux enfants de décrire ce qu'ils observent avec leurs propres mots. Ils ne souhaitent pas désigner une variété gagnante une fois pour toutes : certaines conviennent mieux à une salade, d'autres à une sauce.","question":"Quel apprentissage est visé ?","explanation":"Le passage indique : « Un jardin pédagogique cultive plusieurs variétés d'une même tomate. Les enfants comparent formes et goûts plutôt que classer toutes les tomates dans une seule catégorie. » Cela justifie la réponse : Reconnaître une diversité au sein d'un aliment."},{"number":17,"points":15,"correct":"C","options":["L'absence totale de matières premières","Le besoin d'importer tous les légumes","La perte de récoltes difficiles à écouler immédiatement","Le manque de magasins d'électroménager"],"passage":"Une conserverie collecte les surplus de plusieurs fermes. Les producteurs récupèrent une partie des bocaux pour les vendre plus tard.\n\nLes volumes sont annoncés par les exploitants avant chaque tournée. L'équipe vérifie l'état des produits et choisit des recettes adaptées aux quantités disponibles. Les agriculteurs ne récupèrent donc pas nécessairement un produit identique à celui qu'ils ont apporté, mais une préparation qu'ils pourront conserver. Une étiquette indique l'origine et la composition. Le projet cherche à donner une valeur aux excédents, sans encourager volontairement une production inutile.","question":"Quel problème cette activité aide-t-elle à résoudre ?","explanation":"Le passage indique : « Une conserverie collecte les surplus de plusieurs fermes. Les producteurs récupèrent une partie des bocaux pour les vendre plus tard. » Cela justifie la réponse : La perte de récoltes difficiles à écouler immédiatement."},{"number":18,"points":15,"correct":"D","options":["Masquer l'origine des produits","Utiliser tous les restes sans distinction","Supprimer les réfrigérateurs","Vérifier la sécurité des aliments"],"passage":"Un atelier apprend à cuisiner avec des restes. Il distingue les aliments encore utilisables de ceux dont la conservation a été insuffisante.\n\nLes participants apportent des exemples de leur quotidien et discutent des délais au réfrigérateur. Les animateurs insistent sur l'importance de noter les dates et de refroidir correctement certaines préparations. Ils ne présentent pas toute transformation comme une manière d'effacer un défaut de conservation. Les recettes proposées restent simples, afin que les familles puissent les refaire avec leur équipement courant.","question":"Quelle précaution accompagne l'économie ?","explanation":"Le passage indique : « Un atelier apprend à cuisiner avec des restes. Il distingue les aliments encore utilisables de ceux dont la conservation a été insuffisante. » Cela justifie la réponse : Vérifier la sécurité des aliments."},{"number":19,"points":15,"correct":"D","options":["Augmenter les pertes en cuisine","Supprimer tous les produits frais","Fermer plusieurs jours par semaine","Simplifier la gestion des approvisionnements"],"passage":"Un restaurateur raccourcit sa carte pour acheter moins de références et mieux suivre ses stocks. Le nombre de plats diminue, pas celui des services.\n\nLes cuisiniers connaissent mieux les quantités préparées et peuvent utiliser certains ingrédients dans plusieurs recettes. Il suivra les ventes avant de modifier de nouveau la carte. L'objectif est de conserver une offre cohérente avec la taille de l'équipe, plutôt que d'afficher de nombreuses possibilités dont une partie serait souvent indisponible ou préparée sans le soin nécessaire.","question":"Quel objectif guide ce changement ?","explanation":"Le passage indique : « Un restaurateur raccourcit sa carte pour acheter moins de références et mieux suivre ses stocks. Le nombre de plats diminue, pas celui des services. » Cela justifie la réponse : Simplifier la gestion des approvisionnements."},{"number":20,"points":21,"correct":"A","options":["Plus de prévisibilité contre moins de choix instantané","Un prix changeant après chaque livraison","Une suppression de toute relation avec les fermes","Des commandes sans engagement pour les producteurs"],"passage":"Un groupement de consommateurs commande directement à des producteurs. Les prix sont discutés à l'avance pour donner de la visibilité aux deux parties. Les acheteurs acceptent en échange un choix moins immédiat qu'au supermarché. Les volumes sont précisés avant la saison, avec les conditions de retrait et les possibilités d'absence. Les producteurs peuvent ainsi préparer certains investissements et les consommateurs comprendre les engagements pris. Le groupe accepte quelques variations liées à la récolte. Il préfère discuter ces aléas dans un cadre connu plutôt que découvrir une nouvelle condition à chaque commande.","question":"Quel compromis est décrit ?","explanation":"Le passage indique : « Un groupement de consommateurs commande directement à des producteurs. Les prix sont discutés à l'avance pour donner de la visibilité aux deux parties. Les acheteurs acceptent en échange un choix moins immédiat qu'au supermarché. » Cela justifie la réponse : Plus de prévisibilité contre moins de choix instantané."},{"number":21,"points":21,"correct":"B","options":["Les mêmes produits restent disponibles partout","Le menu suit davantage les saisons","Les clients doivent apporter tous leurs légumes","Le service devient uniquement estival"],"passage":"Un restaurant privilégie des légumes de proximité. En hiver, il remplace certains plats plutôt que transporter les mêmes ingrédients de très loin. Les clients retrouveront une indication sur les substitutions, afin de comprendre pourquoi une recette connue évolue. Le chef échange régulièrement avec plusieurs fournisseurs pour prévoir les quantités. Il ne promet pas que tout ingrédient pourra toujours venir du même périmètre. Il souhaite surtout que ses choix suivent une logique expliquée, plutôt que conserver à tout prix une carte identique sans regarder les conditions d'approvisionnement.","question":"Quelle conséquence le choix local a-t-il ?","explanation":"Le passage indique : « Un restaurant privilégie des légumes de proximité. En hiver, il remplace certains plats plutôt que transporter les mêmes ingrédients de très loin. » Cela justifie la réponse : Le menu suit davantage les saisons."},{"number":22,"points":21,"correct":"A","options":["L'aménagement pratique influence les usages","Les enfants refusent tous les verres","La fontaine est inutile","L'eau doit être payante pour être bue"],"passage":"Une école installe une fontaine à eau dans son réfectoire. La consommation augmente surtout après le déplacement des verres à portée des enfants. Les enfants hésitaient auparavant à demander un verre ou devaient quitter leur table pour le trouver. Le changement ne nécessitait pas une autre fontaine, mais une meilleure organisation du service. L'école vérifiera si cette facilité reste effective pendant les périodes d'affluence et si les plus petits peuvent se servir sans difficulté.","question":"Que suggère cette observation ?","explanation":"Le passage indique : « Une école installe une fontaine à eau dans son réfectoire. La consommation augmente surtout après le déplacement des verres à portée des enfants. » Cela justifie la réponse : L'aménagement pratique influence les usages."},{"number":23,"points":21,"correct":"D","options":["L'indépendance complète vis-à-vis du climat","Une quantité identique garantie chaque jour","La disparition du besoin de travail","L'incertitude inhérente à certaines productions"],"passage":"Des agriculteurs accueillent des visiteurs pendant une journée de récolte. Ils expliquent que les volumes varient avec la météo. La rencontre montre un travail soumis à des aléas, et non une production parfaitement prévisible. Les visiteurs voient aussi les préparations et les tâches qui continuent lorsque la météo empêche de travailler dehors. Les agriculteurs expliquent leurs décisions et les possibilités de report. Ils souhaitent éviter qu'une journée agréable à la ferme donne l'image d'un métier toujours prévisible.","question":"Quelle idée la visite aide-t-elle à comprendre ?","explanation":"Le passage indique : « Des agriculteurs accueillent des visiteurs pendant une journée de récolte. Ils expliquent que les volumes varient avec la météo. La rencontre montre un travail soumis à des aléas, et non une production parfaitement prévisible. » Cela justifie la réponse : L'incertitude inhérente à certaines productions."},{"number":24,"points":21,"correct":"C","options":["Démontrer l'inutilité de tous les outils","Réserver l'activité aux professionnels","Faciliter le réemploi des apprentissages à domicile","Augmenter le coût des recettes"],"passage":"Un atelier de cuisine ouvre sans matériel sophistiqué. Les participants refont les gestes avec des ustensiles courants, afin de pouvoir reproduire les recettes chez eux. Les recettes sont choisies pour pouvoir être refaites dans une cuisine ordinaire, avec des quantités faciles à modifier. Les participants discutent de leurs propres contraintes : temps, place et nombre de convives. Le centre préfère une technique réellement réutilisée à une démonstration impressionnante mais impossible à reproduire.","question":"Pourquoi ce choix de matériel ?","explanation":"Le passage indique : « Un atelier de cuisine ouvre sans matériel sophistiqué. Les participants refont les gestes avec des ustensiles courants, afin de pouvoir reproduire les recettes chez eux. » Cela justifie la réponse : Faciliter le réemploi des apprentissages à domicile."},{"number":25,"points":21,"correct":"D","options":["Un grand format reste économique quand le prix au kilo baisse, même si le foyer n'en utilise qu'une partie.","Les quantités consommées doivent remplacer le prix par kilo, qui n'apporte aucune information utile à la comparaison.","Le prix au kilo doit déterminer le classement initial; les pertes sont pertinentes uniquement après la décision d'achat.","Le prix unitaire aide à comparer, mais les pertes peuvent annuler le gain, pour les petits ménages."],"passage":"Une épicerie affiche le prix au kilo à côté des promotions. Cette information aide à comparer des formats différents, car le paquet le plus gros n'est pas toujours le plus économique. Le commerçant affiche la même unité pour chaque référence et explique où la lire. Les clients peuvent ainsi vérifier si une promotion correspond à leur besoin. Un grand paquet peut rester intéressant pour une famille nombreuse, mais devenir inutile pour une personne qui n'en consommera qu'une partie. Lors d'un essai, un lot familial affiche un prix unitaire inférieur mais entraîne des pertes chez les petits ménages. Le responsable conserve les deux informations côte à côte: coût par kilo et quantité que chacun pense réellement consommer.","question":"Pourquoi le responsable refuse-t-il de classer les offres à partir de la seule taille des emballages ?","explanation":"D associe prix au kilo et quantité réellement consommée. A suppose qu'un tarif unitaire bas reste rentable malgré les pertes; B écarte à tort le prix au kilo; C examine le gaspillage seulement après un classement qui peut ainsi être trompeur."},{"number":26,"points":21,"correct":"C","options":["Il privilégie le nombre de convives puis attribue la même portion aux groupes ayant des profils différents.","Il fixe les portions à partir des réservations et élimine la marge afin de réduire les restes.","Prévoir les portions selon les convives et leurs habitudes, tout en gardant une réserve pour les imprévus.","Il établit le volume de préparation à partir des portions servies lors du précédent événement de même taille."],"passage":"Un traiteur propose des portions modulables selon les convives. Il demande les effectifs définitifs deux jours avant le repas pour ajuster les achats. Les clients peuvent préciser les âges et les habitudes alimentaires de leurs invités. Le traiteur propose ensuite une estimation, sans présenter chaque personne comme une consommation identique. Une petite marge reste prévue pour les imprévus. Les organisateurs souhaitent réduire les restes sans risquer de manquer, et discutent aussi du rangement de ce qui pourrait être conservé après le repas. Deux événements comptant le même nombre d'invités ont récemment produit des besoins très différents parce que la répartition entre enfants et adultes n'était pas la même. Le traiteur ajuste donc le volume prévu, tout en gardant une réserve limitée.","question":"Quel raisonnement guide le calcul des portions du traiteur ?","explanation":"C croise effectif, habitudes et petite marge. A/D infèrent que deux événements de même taille se ressemblent; B supprime la réserve prévue."},{"number":27,"points":21,"correct":"B","options":["Classer les versions familiales selon leur ancienneté permettrait d'identifier celles qui ont conservé les pratiques considérées comme traditionnelles.","Documenter une tradition vivante sans hiérarchiser les variantes transmises entre les familles, selon leurs contextes respectifs.","Pour identifier les étapes où la transmission orale a transformé une recette initiale considérée comme stable.","Comparer les substitutions pourrait aider le comité à distinguer les variantes les plus proches d'une recette de référence."],"passage":"Un livre de recettes recueille les plats transmis dans plusieurs familles. Les variantes sont conservées : le comité ne cherche pas une version unique déclarée supérieure aux autres. Ces remarques accompagnent les recettes. Le livre ne cherche pas à séparer une version pure et des copies dégradées, mais à montrer comment une pratique se transmet entre personnes et se transforme avec leurs conditions de vie. Une famille a remplacé un ingrédient introuvable dans sa région d'accueil; une autre l'a conservé en changeant seulement la cuisson. Le comité publie les deux récits avec leur contexte au lieu d'en faire une succession d'erreurs par rapport à une version officielle.","question":"Pourquoi le comité conserve-t-il des récits différents d'un même plat ?","explanation":"B documente plusieurs manières de transmettre une pratique, sans hiérarchie d'authenticité. A et D imposent un classement par origine ou fidélité; C présuppose une recette initiale stable que le texte ne retient pas."},{"number":28,"points":21,"correct":"B","options":["Les différences de durée de pause montrent que les salariés n'expriment pas leurs préférences avec la même précision.","Des contraintes peuvent expliquer des pratiques différentes malgré des préférences déclarées semblables, dans les deux services étudiés.","La pause courte indique une préférence pour les préparations rapides que les salariés n'avaient pas déclarée.","Les deux services ont reçu des informations nutritionnelles différentes, ce qui explique leurs pratiques malgré les réponses."],"passage":"Une enquête sur les repas au travail mesure la durée disponible autant que les choix alimentaires. Certains salariés disent manger vite, non par préférence, mais à cause de pauses courtes. Les chercheurs regardent les horaires, la distance du lieu de restauration et les possibilités de conserver un repas. Les réponses aideront à choisir des améliorations concrètes, plutôt qu'à adresser uniquement des conseils généraux sans effet sur les conditions du déjeuner. Dans un service, les salariés expriment la même préférence pour un repas préparé que dans un autre, mais disposent de quinze minutes de pause au lieu de quarante-cinq. Le projet prévoit de comparer l'offre et les horaires avant d'interpréter leurs réponses comme de simples choix personnels.","question":"Quelle conclusion l'enquête peut-elle tirer de la différence entre les deux services ?","explanation":"B relie des comportements différents aux contraintes de temps malgré des goûts proches. A/C réinterprètent sans preuve les préférences; D suppose une différence de formation non mentionnée."},{"number":29,"points":21,"correct":"B","options":["À garantir la rotation des producteurs même lorsqu'un candidat démontre une activité déjà soutenable à long terme.","Tester les ventes et les capacités de fabrication avant de proposer au producteur un engagement plus durable.","À mesurer principalement la popularité immédiate du produit avant de décider du développement des capacités de production.","À retenir les candidats qui vendent le plus rapidement, indépendamment de leurs possibilités de fabrication ultérieures."],"passage":"Un marché prévoit un stand pour les petits producteurs débutants. Les emplacements tournent chaque mois pour leur permettre de tester la vente avant un engagement plus long. Les participants bénéficient d'un accompagnement pour présenter leurs prix et leurs produits. Ils peuvent ensuite comparer les retours des clients avec leurs capacités de production. Les candidats discuteront de ce qu'ils ont appris avant de décider d'une présence plus régulière. La rotation empêche un participant de monopoliser une place, mais elle ne constitue pas une promesse de clientèle. Un producteur qui reçoit de nombreux compliments peut encore décider de ne pas revenir si ses volumes de fabrication ne suivent pas.","question":"À quoi sert la période de présence limitée au marché ?","explanation":"B propose un essai évaluant retours et capacité de production. A fait de la rotation une fin permanente; C/D privilégient les ventes sans vérifier la soutenabilité."},{"number":30,"points":26,"correct":"C","options":["Deux assiettes portant la même mention ont une composition comparable, même si leurs portions individuelles peuvent varier.","La mention permet de conclure à un choix nutritionnel cohérent, mais ne renseigne pas sur la provenance des ingrédients.","La mention n'établit seule ni l'origine ni la composition du repas, dans les deux exemples présentés.","Les produits disponibles au moment de la préparation définissent l'équilibre du repas davantage que sa présentation."],"passage":"L'étiquette « fait maison » rassure certains clients, mais ne décrit pas à elle seule l'origine des produits ni l'équilibre d'un repas. Une diététicienne invite à poser plusieurs questions plutôt qu'à déduire toutes les qualités d'une seule mention. Elle propose notamment de regarder les quantités et les ingrédients effectivement servis. Le sens d'une mention doit rester précis, pour éviter qu'un seul mot remplace l'ensemble des informations nécessaires à un choix. Deux assiettes portent la même mention, mais l'une utilise une grande part de produits transformés et l'autre comporte davantage de légumes. La mention peut être exacte dans les deux cas, sans résoudre la question de l'équilibre nutritionnel ni celle de l'approvisionnement.","question":"Que montre la comparaison des deux assiettes portant la même mention ?","explanation":"C constate que la mention ne suffit à établir ni composition ni origine. A infère une composition similaire, B un équilibre nutritionnel non prouvé, D remplace l'analyse de composition par la disponibilité de produits."},{"number":31,"points":26,"correct":"D","options":["L'absence de détails sur la rémunération de l'un des fournisseurs explique directement la similitude des tarifs affichés.","Des tarifs proches indiquent généralement des coûts de production comparables, sauf lorsque les volumes vendus diffèrent.","Les achats groupés réduisent les frais fixes; l'autre fournisseur doit donc appliquer une marge plus faible pour s'aligner.","Des tarifs similaires ne garantissent pas des conditions de production identiques, même lorsque les produits proposés sont comparables."],"passage":"Un prix bas peut être obtenu par de grands volumes, une organisation efficace ou des conditions défavorables aux fournisseurs. Sans information sur ces facteurs, il serait imprudent d'attribuer la même cause à tous les produits bon marché. Des comparaisons entre produits proches et des informations sur les fournisseurs peuvent aider à comprendre ces différences. Le prix reste un repère important pour le budget, sans être une explication complète du fonctionnement de la production. Deux fournisseurs proposent un tarif similaire. L'un annonce un achat groupé avec de faibles frais fixes; pour l'autre, les conditions de rémunération ne sont pas documentées. L'acheteur ne peut déduire de l'égalité des prix une égalité des conditions de production.","question":"Quelle lecture des deux tarifs respecte le mieux les informations disponibles ?","explanation":"D refuse d'inférer les conditions de production à partir de prix similaires. A/B attribuent des causes sans documents, C calcule implicitement une marge non indiquée."},{"number":32,"points":26,"correct":"B","options":["L'adaptation locale fait perdre à la recette sa mémoire familiale, même si les gestes et les occasions restent proches.","Il conserve des usages transmis en adaptant la recette à un nouveau contexte, en préservant certaines pratiques familiales.","Une texture semblable suffit à considérer que les ingrédients essentiels ont été préservés lors de la transmission.","Le changement de céréale conserve surtout le nom du plat, mais les pratiques ne peuvent plus être rapprochées."],"passage":"Les recettes d'un patrimoine culinaire sont souvent adaptées aux produits accessibles dans le lieu où vivent les familles. Cette transformation n'efface pas nécessairement leur histoire. Elle peut être précisément la manière dont la transmission continue dans un contexte différent. Les familles racontent les substitutions qu'elles ont essayées et les goûts qu'elles souhaitaient retrouver. Ces récits montrent une continuité vivante, dont les changements peuvent être décrits plutôt que dissimulés sous l'idée d'une recette restée toujours identique. Pour une famille, changer de céréale a permis de retrouver la texture recherchée malgré l'absence du produit ancien. Le récit précise le changement au lieu de présenter la recette comme intacte; la parenté avec la pratique antérieure se lit aussi dans les gestes et les occasions de partage.","question":"Dans quel sens le changement d'ingrédient peut-il faire partie de la transmission ?","explanation":"B retient la continuité de repères pratiques malgré la substitution explicitée. A/D nient les usages conservés; C infère des ingrédients identiques de la seule texture."},{"number":33,"points":26,"correct":"A","options":["Une préférence initialement faible peut refléter la méconnaissance du plat plutôt qu'un rejet après dégustation.","La seconde note montre que les recettes nouvelles ont été modifiées entre les deux enquêtes, d'où leur meilleur accueil.","La hausse de la note moyenne montre que le plat nouveau sera apprécié de la même manière par tous les élèves.","Les dégustations neutralisent les habitudes antérieures, y compris pour les plats déjà connus des élèves."],"passage":"Une cantine veut améliorer ses menus à partir d'un vote. Les plats peu connus risquent d'obtenir peu de voix avant même d'avoir été goûtés. L'équipe ajoute des dégustations aux questionnaires pour éviter que la consultation ne reproduise seulement les habitudes existantes. L'équipe comparera leurs avis avant et après l'essai pour voir si le menu futur doit être ajusté ou simplement mieux présenté. Un plat nouveau reçoit peu de votes lors d'un premier sondage. Après dégustation, sa note moyenne augmente fortement, alors que celle des plats déjà connus varie peu. L'équipe distingue désormais la réaction à un nom de plat de l'appréciation après expérience.","question":"Que permet d'interpréter la seconde mesure des préférences ?","explanation":"A explique que le premier vote peut refléter la méconnaissance, car la note augmente après dégustation sans changement de recette annoncé. B invente une révision du plat; C généralise à tous les élèves et D prétend supprimer les habitudes pour toutes les recettes."},{"number":34,"points":26,"correct":"A","options":["Adapter les livraisons aux produits, au stockage et aux pertes constatées, ainsi qu'aux exigences des cuisines concernées.","Réduire le nombre de trajets permet d'évaluer le gain du dispositif, les pertes de cuisine appartenant au budget alimentaire.","Une cadence fixe pour chaque catégorie de produit rend les livraisons prévisibles et compense les contraintes de stockage.","Les commandes supplémentaires de produits fragiles peuvent être laissées au choix des restaurants, sans comptage des trajets."],"passage":"Un producteur remplace des livraisons quotidiennes par deux tournées hebdomadaires. Les trajets diminuent, mais certains restaurants doivent adapter leurs capacités de stockage. L'économie logistique suppose donc une coordination entre ceux qui livrent et ceux qui reçoivent. Le calendrier sera discuté à l'avance avec les cuisines. Certains produits nécessiteront un autre rythme, tandis que d'autres pourront être livrés ensemble sans difficulté. L'essai devra donc être évalué pour chaque type d'approvisionnement. Un restaurant peut conserver deux livraisons groupées de conserves mais doit encore recevoir certains produits fragiles plus souvent. La baisse globale des kilomètres parcourus ne serait pas une économie durable si les nouvelles contraintes provoquaient des pertes en cuisine.","question":"Quelle condition rend la réduction des tournées réellement pertinente ?","explanation":"A requiert une coordination des catégories, des stocks et des pertes. B/D retirent certains coûts du bilan, C applique une cadence unique malgré des contraintes différentes."},{"number":35,"points":26,"correct":"D","options":["Les deux cuisines ont un rendement équivalent contre le gaspillage, car elles compostent la même quantité de restes à la fin du service.","La seconde cuisine valorise davantage d'aliments par repas, puisque son poids de déchets compostés est identique malgré un surplus moindre.","La différence de onze kilos prouve que toutes les matières restantes dans la première cuisine étaient comestibles et auraient pu être évitées.","À nombre de repas égal, la seconde cuisine produit moins de surplus; le même tonnage de compost ne mesure donc pas la prévention."],"passage":"La lutte contre le gaspillage en cuisine est parfois réduite au recyclage des restes. Un collectif insiste d'abord sur les prévisions, les achats et les portions. Le traitement final reste utile, mais intervient après que des décisions évitables ont déjà produit un surplus. Ces informations peuvent conduire à modifier l'organisation du service avant même de chercher de nouvelles recettes pour transformer les aliments non consommés. Dans deux cuisines, la même quantité de déchets est compostée. La première produit beaucoup de restes et la seconde ajuste ses achats au nombre de repas, ce qui réduit la quantité jetée avant le compostage. Le collectif considère ces deux résultats comme distincts. Le bilan chiffré précise les mêmes cent repas préparés dans les deux cuisines. Dans la première, vingt-cinq kilos d'aliments non servis restent à la fin du service, dont dix sont compostés. Dans la seconde, les responsables ont revu les achats et les portions: quatorze kilos restent, dont dix sont également compostés. Les deux cuisines annoncent donc le même poids valorisé, mais la seconde a évité onze kilos de surplus en amont. L'équipe de mesure avertit que les restes ne sont pas tous comestibles et qu'une comparaison entre services devrait distinguer les épluchures des aliments préparés non servis. Le comité veut publier des indicateurs séparés: masse de surplus pour cent repas, nature des restes et part finalement valorisée. Il refuse un classement fondé sur le seul tonnage du compost, tout comme un calcul qui considérerait tous les déchets résiduels comme évitables.","question":"Quelle comparaison le bilan permet-il de soutenir sans assimiler prévention et valorisation ?","explanation":"D s'appuie sur les 25 et 14 kilos restants pour cent repas et sur les 10 kilos compostés dans chaque cuisine. La prévention porte sur la quantité produite en amont, non sur le tonnage valorisé. A confond égalité du compost et réduction des surplus; B transforme une égalité de masse en valorisation plus grande; C ignore la distinction explicitement demandée entre restes comestibles et non comestibles."},{"number":36,"points":33,"correct":"B","options":["Le nombre de commandes communes a diminué après une modification du choix disponible au moment de la réservation.","Réduire trajets et emballages superflus tout en conservant les adaptations nécessaires aux contraintes alimentaires personnelles des foyers.","La préférence pour les paniers différents explique à elle seule la totalité des trajets et des emballages.","Les paniers communs rendent les commandes plus efficaces en empêchant toute prise en compte des contraintes alimentaires."],"passage":"Un service de paniers « personnalisés » promet de répondre à chaque préférence. Pour y parvenir, il multiplie les petites commandes et les emballages séparés. Les clients gagnent en choix, mais le système perd une partie de l'efficacité du panier commun. La personnalisation peut déplacer les coûts matériels vers l'organisation qui la rend possible. Pour préserver une partie de cette souplesse, le service propose désormais quelques choix communs plutôt qu'une composition entièrement différente pour chaque foyer. Les clients peuvent indiquer des contraintes essentielles, mais toutes les préférences ne donneront plus lieu à un emballage séparé. Le responsable souhaite mesurer les volumes réellement transportés et jetés, pas seulement la satisfaction au moment de la commande. Il espère ainsi conserver un service utile, tout en rendant visibles les ressources mobilisées derrière une offre qui semblait simplement apporter davantage de liberté à chacun. Le responsable compare deux mois: le nombre de clients reste stable, mais les petites commandes individualisées multiplient les trajets et les cartons. Une formule intermédiaire supprime certaines variantes sans toucher aux contraintes alimentaires que les clients jugent indispensables.","question":"Que cherche principalement à corriger la formule intermédiaire ?","explanation":"B réduit les ressources mobilisées par des choix individualisés tout en conservant les contraintes essentielles. A ajoute une évolution des commandes non constatée; C attribue tous les coûts aux préférences sans les autres facteurs; D nie les adaptations conservées."},{"number":37,"points":33,"correct":"B","options":["Elle privilégie les produits de saison mais laisse les exceptions hors du menu pour garder un message simple.","Elle explique la priorité locale et les exceptions, rendant les choix vérifiables, au lieu d'une promesse générale.","Elle établit qu'un fournisseur local peut remplacer tous les ingrédients même lorsque certaines épices ne sont pas régionales.","Elle publie la provenance des légumes sans préciser les raisons du choix des ingrédients venus d'ailleurs."],"passage":"Un restaurant annonce une cuisine locale. Son menu comporte surtout des produits de proximité, mais certains ingrédients complémentaires viennent d'ailleurs. Le chef publie ces exceptions et leurs raisons. La cohérence de son engagement repose sur des choix expliqués, plutôt que sur une formule absolue que la pratique démentirait. Il indique les fournisseurs principaux et la période à laquelle certains produits deviennent disponibles. Les clients peuvent ainsi comprendre pourquoi une recette change ou pourquoi une épice n'est pas produite dans la région. Le restaurateur souhaite éviter qu'une promesse trop générale transforme chaque exception en soupçon de tromperie. Cette précision n'empêche pas la discussion sur ses choix. Elle permet au contraire de les comparer avec d'autres possibilités, en distinguant une priorité réelle d'une affirmation commerciale qui paraîtrait valable pour chaque ingrédient et pendant toute l'année. Sur un menu, le chef indique qu'une épice vient de loin alors que les légumes sont achetés dans la région selon la saison. Un autre établissement affiche simplement « 100 % local » sans préciser ses achats. Les clients ne peuvent pas vérifier les mêmes choses à partir des deux annonces.","question":"En quoi la démarche du premier chef rend-elle son engagement plus crédible ?","explanation":"B rend la promesse locale vérifiable en précisant sa portée et ses exceptions. A et D omettent des explications importantes; C transforme une priorité locale en approvisionnement intégral alors que des exceptions subsistent."},{"number":38,"points":33,"correct":"C","options":["La brochure suffit à assurer des pratiques identiques dès lors que les ménages peuvent reformuler les recommandations, même si leur équipement diffère.","Les difficultés de conservation expliquent à elles seules toutes les différences entre quartiers, puisque les participants du premier comprenaient le message.","Le second dispositif accompagne une évolution des pratiques, mais l'accès aux produits et les situations initiales empêchent d'en isoler l'effet.","L'atelier de cuisine démontre la supériorité d'une méthode pédagogique sur toute intervention commerciale, indépendamment des conditions de départ."],"passage":"Une ville distribue des brochures pour encourager une alimentation variée. Une enquête montre cependant que plusieurs ménages disposent d'un équipement de cuisson limité et de peu de commerces accessibles. La connaissance des recommandations n'est pas leur principale difficulté. Des conseils utiles doivent s'accompagner d'une attention aux conditions concrètes qui permettent de les suivre. Les associations proposent de compléter la campagne par des ateliers utilisant le matériel réellement disponible dans les logements. Elles demandent aussi que l'accès aux commerces et aux lieux de conservation soit examiné. Certaines personnes connaissent déjà les conseils et souhaitent les suivre, mais doivent composer avec un budget ou un horaire peu compatible avec l'offre locale. Les responsables veulent donc éviter un message qui ferait de ces contraintes une faute personnelle. La réussite du programme dépendra de ce qu'il rend effectivement possible dans le quotidien des familles auxquelles il s'adresse. Deux ménages connaissent les mêmes recommandations. Le premier dispose d'une cuisine équipée et de commerces proches; le second ne peut conserver certains aliments ni se déplacer aux heures d'ouverture. Répéter la brochure ne modifierait pas ces différences concrètes. Une seconde enquête suit des familles après deux ateliers. Dans le premier quartier, les participants reçoivent la brochure et savent expliquer les recommandations, mais plusieurs déclarent encore renoncer aux légumes frais faute de conservation adaptée. Dans le second, un atelier de cuisine avec le matériel réellement disponible est associé à une ouverture plus tardive du point de vente. Les participants de ce quartier décrivent davantage de repas préparés selon les conseils. Les organisateurs observent cependant que les deux groupes différaient déjà par leur équipement et leur proximité des commerces. Ils ne présentent donc pas l'écart comme une preuve de l'effet exclusif de l'atelier. Pour la suite, ils prévoient de mesurer séparément compréhension des conseils, accès concret aux produits et changements observés dans les pratiques, afin que le succès d'une brochure ne soit pas confondu avec son application.","question":"Quelle interprétation des deux quartiers respecte à la fois le résultat observé et ses limites ?","explanation":"C sépare la compréhension des recommandations de leur application concrète. Les pratiques progressent avec l'intervention combinée dans le second quartier, mais la différence d'équipement et de distance initiale exclut une attribution causale simple. A assimile savoir et possibilité d'agir; B fait de la seule conservation une cause exclusive; D attribue le changement à l'atelier seul sans distinguer l'accès au point de vente."},{"number":39,"points":33,"correct":"D","options":["Chaque diminution de poids ouvre droit à un ajustement monétaire, tandis que l'information sur les récoltes relève du libre choix du producteur.","La ferme doit décrire les soins apportés, mais la variabilité des récoltes rend l'information saisonnière facultative.","Le risque accepté par les membres écarte tout remboursement, même quand les engagements du producteur ne sont pas tenus.","L'aléa climatique peut modifier la quantité reçue sans remboursement automatique, mais la ferme demeure tenue aux soins et informations prévus."],"passage":"Une ferme propose aux clients de partager les risques d'une saison en payant un panier à l'avance. Certains craignent de recevoir moins lors d'une mauvaise récolte. Le producteur explique que le contrat n'est pas une garantie de volume identique, mais une relation différente avec l'activité agricole. Le prix finance aussi une continuité de production confrontée à l'incertitude. Le groupe prévoit une visite des cultures et une information régulière sur l'évolution de la saison. Les membres pourront discuter des substitutions possibles, tout en comprenant qu'un engagement ne fait pas disparaître les aléas du climat. Le producteur garde la responsabilité d'expliquer ses choix et de travailler avec soin. Les acheteurs, eux, acceptent que leur contribution ne corresponde pas toujours au même poids de produits. L'année suivante, deux membres ayant payé le même montant reçoivent des volumes différents selon les récoltes des parcelles concernées. Le contrat précise les modalités d'information et les choix de remplacement, mais ne promet pas d'ajuster rétroactivement chaque contribution au poids reçu. Au terme d'une autre saison, la ferme a connu une baisse de rendement sur certaines parcelles malgré les soins documentés. Les membres avaient réglé des contributions identiques, mais leurs paniers, répartis selon les parcelles et les produits disponibles, ont varié en poids. Le contrat prévoit une réunion pour expliquer les aléas, un remplacement possible par d'autres légumes et un remboursement seulement si la ferme n'a pas assuré les engagements de production et d'information précisés au départ. Il n'introduit aucune régularisation automatique au kilogramme manquant. Un membre estime que toute variation de poids prouve un défaut de service; un autre fait remarquer que l'acceptation du risque climatique ne retire pas au producteur ses obligations de diligence et de transparence. Les deux conviennent que la description des récoltes et des substitutions doit pouvoir être vérifiée, même lorsque le montant versé n'est pas recalculé.","question":"Quelle interprétation distingue correctement le risque partagé des obligations que le producteur conserve ?","explanation":"D distingue un aléa de rendement accepté par les membres et des obligations contractuelles toujours vérifiables. A introduit un remboursement au poids exclu; B rend facultative l'information; C nierait même le remboursement prévu en cas de manquement."}]}$bank_7$::jsonb),
('tcf-reading-08','tcf-reading-2026-11-close-reading-v4',$bank_8${"id":"tcf-reading-08","title":"TCF Reading · Test 08","seconds":3600,"version":"tcf-reading-2026-11-close-reading-v4","maxPoints":699,"questions":[{"number":1,"points":3,"correct":"B","options":["Dix-neuf heures trente","Dix-neuf heures quinze","Dix-huit heures quarante-cinq","Vingt heures"],"passage":"La piscine ferme ses bassins à dix-neuf heures. Les vestiaires restent accessibles quinze minutes supplémentaires.\n\nMerci de prévoir le temps nécessaire avant la fermeture des vestiaires. Le personnel rappellera cette règle à l'entrée de chaque séance.","question":"Jusqu'à quand peut-on se changer ?","explanation":"Le passage indique : « La piscine ferme ses bassins à dix-neuf heures. Les vestiaires restent accessibles quinze minutes supplémentaires. » Cela justifie la réponse : Dix-neuf heures quinze."},{"number":2,"points":3,"correct":"B","options":["Un ballon","Un tapis","Une chaise","Un casque"],"passage":"Le cours de yoga est déplacé au gymnase. Apportez votre tapis ; les chaises seront fournies aux personnes qui en ont besoin.\n\nL'animateur accueillera les participants devant la salle.","question":"Quel matériel est demandé ?","explanation":"Le passage indique : « Le cours de yoga est déplacé au gymnase. Apportez votre tapis ; les chaises seront fournies aux personnes qui en ont besoin. » Cela justifie la réponse : Un tapis."},{"number":3,"points":3,"correct":"C","options":["Uniquement les livreurs","Les visiteurs sans motif","Les patients ayant rendez-vous","Toute personne souhaitant s'inscrire"],"passage":"L'accueil du cabinet sera fermé mardi matin. Les consultations déjà prévues sont maintenues ; sonnez à la porte latérale.\n\nLes demandes non urgentes seront traitées dès le retour de l'équipe d'accueil.","question":"Qui peut venir mardi matin ?","explanation":"Le passage indique : « L'accueil du cabinet sera fermé mardi matin. Les consultations déjà prévues sont maintenues ; sonnez à la porte latérale. » Cela justifie la réponse : Les patients ayant rendez-vous."},{"number":4,"points":3,"correct":"D","options":["Une sortie sans chaussures","Une course plus rapide","L'accès au parcours glissant","Un itinéraire alternatif"],"passage":"Le parcours de marche est glissant après la pluie. Utilisez provisoirement la boucle courte sur sol stabilisé.\n\nDes panneaux indiquent la déviation à l'entrée du parc. Les équipes vérifieront l'état du terrain avant de rouvrir le passage habituel.","question":"Que conseille l'annonce ?","explanation":"Le passage indique : « Le parcours de marche est glissant après la pluie. Utilisez provisoirement la boucle courte sur sol stabilisé. » Cela justifie la réponse : Un itinéraire alternatif."},{"number":5,"points":9,"correct":"D","options":["Une route inconnue de nuit","Une compétition chronométrée","Une ascension difficile","Un trajet sans montée importante"],"passage":"Je reprends doucement le vélo après ma pause. Pour dimanche, choisissons le trajet plat ; nous réserverons les côtes à une autre sortie.\n\nLe groupe peut conserver une allure tranquille et s'arrêter lorsque ce sera nécessaire. Je veux reprendre régulièrement sans transformer cette première sortie en épreuve trop difficile.","question":"Quel parcours est souhaité ?","explanation":"Le passage indique : « Je reprends doucement le vélo après ma pause. Pour dimanche, choisissons le trajet plat ; nous réserverons les côtes à une autre sortie. » Cela justifie la réponse : Un trajet sans montée importante."},{"number":6,"points":9,"correct":"A","options":["Contacter le secrétariat","Venir sans prévenir un autre jour","Annuler tous les soins","Demander à un voisin de consulter"],"passage":"Votre rendez-vous de contrôle est avancé à jeudi. Prévenez le secrétariat si ce nouvel horaire ne vous convient pas.\n\nLe cabinet proposera un autre créneau selon les disponibilités. Merci de signaler votre réponse rapidement pour éviter de laisser une place inutilisée.","question":"Que faire en cas d'indisponibilité ?","explanation":"Le passage indique : « Votre rendez-vous de contrôle est avancé à jeudi. Prévenez le secrétariat si ce nouvel horaire ne vous convient pas. » Cela justifie la réponse : Contacter le secrétariat."},{"number":7,"points":9,"correct":"B","options":["Recevoir un équipement définitif","Essayer avant de s'équiper","Participer sans jamais s'inscrire","Éviter toute séance encadrée"],"passage":"L'association prête des bâtons de marche pendant les trois premières séances. Ensuite, chacun choisira s'il souhaite continuer l'activité.\n\nUn animateur vérifiera leur taille et expliquera les gestes de base. Vous pourrez ensuite poser vos questions avant de vous engager dans une pratique régulière.","question":"Quel est l'intérêt du prêt ?","explanation":"Le passage indique : « L'association prête des bâtons de marche pendant les trois premières séances. Ensuite, chacun choisira s'il souhaite continuer l'activité. » Cela justifie la réponse : Essayer avant de s'équiper."},{"number":8,"points":9,"correct":"B","options":["Un départ sans accompagnateur","Des arrêts plus fréquents","Une distance doublée","La suppression des boissons"],"passage":"Nous maintenons la randonnée, mais avec davantage de pauses à cause de la chaleur. Emportez de l'eau et prévenez si vous préférez renoncer.\n\nLe guide vérifiera les points d'eau et adaptera l'allure au groupe.","question":"Quelle adaptation est prévue ?","explanation":"Le passage indique : « Nous maintenons la randonnée, mais avec davantage de pauses à cause de la chaleur. Emportez de l'eau et prévenez si vous préférez renoncer. » Cela justifie la réponse : Des arrêts plus fréquents."},{"number":9,"points":9,"correct":"B","options":["Aux enfants accompagnés","Aux adultes qui apprennent","Aux nageurs en compétition seulement","Aux entraîneurs professionnels"],"passage":"La séance découverte de natation est réservée aux adultes débutants. Il n'est pas nécessaire de savoir nager pour s'inscrire.\n\nLes exercices commenceront dans une zone où chacun peut garder ses repères. Un échange permettra de préciser les attentes avant le premier passage dans l'eau.","question":"À qui s'adresse la séance ?","explanation":"Le passage indique : « La séance découverte de natation est réservée aux adultes débutants. Il n'est pas nécessaire de savoir nager pour s'inscrire. » Cela justifie la réponse : Aux adultes qui apprennent."},{"number":10,"points":9,"correct":"D","options":["Un projet de compétition","Un déménagement en montagne","Une interdiction de courir","Une meilleure organisation du quotidien"],"passage":"Je vais marcher le midi plutôt que courir tard le soir. Cela s'accorde mieux avec mes horaires et me laisse du temps en famille.\n\nJe compte aussi préparer mes affaires à l'avance pour ne pas renoncer au dernier moment.","question":"Qu'est-ce qui motive ce changement ?","explanation":"Le passage indique : « Je vais marcher le midi plutôt que courir tard le soir. Cela s'accorde mieux avec mes horaires et me laisse du temps en famille. » Cela justifie la réponse : Une meilleure organisation du quotidien."},{"number":11,"points":15,"correct":"A","options":["Elle n'est pas l'objectif principal","Elle exclut les nouveaux membres","Elle détermine le droit d'entrer","Elle impose un temps identique"],"passage":"Un club organise une séance sans classement. Les participants choisissent leur rythme et peuvent interrompre l'exercice avant la fin.\n\nLes animateurs proposent plusieurs exercices au même endroit et expliquent les adaptations possibles. Une personne qui débute n'a pas à suivre exactement le programme d'un habitué. Le club souhaite que chacun trouve une manière de participer sans craindre de ralentir les autres. Les responsables observeront les inscriptions, mais aussi les retours après plusieurs semaines. Une séance accueillante n'atteint pas son objectif si les nouveaux venus se sentent encore incapables de revenir seuls ou de demander une pause.","question":"Quelle place est donnée à la performance ?","explanation":"Le passage indique : « Un club organise une séance sans classement. Les participants choisissent leur rythme et peuvent interrompre l'exercice avant la fin. » Cela justifie la réponse : Elle n'est pas l'objectif principal."},{"number":12,"points":15,"correct":"A","options":["L'atelier ne remplace pas un suivi individuel","Les animateurs prescrivent systématiquement un traitement","Aucune question ne peut être posée","Les participants reçoivent tous un diagnostic"],"passage":"Une résidence propose des rencontres autour du sommeil. Les animateurs donnent des informations générales et orientent les situations particulières vers un professionnel.\n\nLes participants peuvent parler de leurs habitudes, mais ne sont pas invités à dévoiler un dossier médical devant le groupe. Les séances abordent notamment l'organisation de la soirée et les conditions du logement. Les intervenants rappellent que des difficultés persistantes peuvent demander une consultation.","question":"Quelle limite est précisée ?","explanation":"Le passage indique : « Une résidence propose des rencontres autour du sommeil. Les animateurs donnent des informations générales et orientent les situations particulières vers un professionnel. » Cela justifie la réponse : L'atelier ne remplace pas un suivi individuel."},{"number":13,"points":15,"correct":"A","options":["Permettre différentes capacités de participation","Supprimer les explications","Réserver le parc aux spécialistes","Imposer une difficulté unique"],"passage":"Le parcours sportif du parc comporte des variantes assises et debout. Les panneaux montrent plusieurs niveaux pour un même mouvement.\n\nLes indications ne supposent pas que l'on connaisse déjà les appareils. Des dessins montrent les positions et rappellent qu'une pause est possible. Le service souhaite accueillir les personnes qui ne fréquentent pas les salles, autant que les sportifs habituels. Les usagers pourront signaler un mouvement difficile à comprendre. Une première évaluation regardera la variété des participants et la facilité d'utilisation du parcours, plutôt que le seul nombre d'équipements installés ou la vitesse à laquelle ils sont utilisés.","question":"Quel objectif poursuit l'aménagement ?","explanation":"Le passage indique : « Le parcours sportif du parc comporte des variantes assises et debout. Les panneaux montrent plusieurs niveaux pour un même mouvement. » Cela justifie la réponse : Permettre différentes capacités de participation."},{"number":14,"points":15,"correct":"D","options":["Pour imposer un classement plus strict","Pour limiter l'accès aux nouveaux venus","Pour remplacer toutes les sorties","Pour diversifier les façons de pratiquer"],"passage":"Un club de course accueille un groupe de marche rapide. Certains membres souhaitent bouger régulièrement sans rechercher la vitesse.\n\nLes rendez-vous gardent une progression et un encadrement, mais les distances sont adaptées aux objectifs annoncés par les participants. Certains cherchent une activité après le travail ; d'autres veulent retrouver une habitude interrompue. Le responsable souhaite éviter qu'une même image de la performance fasse croire que le club n'accueille que des coureurs rapides. Les deux groupes pourront partager des rencontres et quelques exercices, sans que l'un soit considéré comme une version moins valable de l'autre.","question":"Pourquoi ce groupe est-il créé ?","explanation":"Le passage indique : « Un club de course accueille un groupe de marche rapide. Certains membres souhaitent bouger régulièrement sans rechercher la vitesse. » Cela justifie la réponse : Pour diversifier les façons de pratiquer."},{"number":15,"points":15,"correct":"C","options":["L'existence d'un accueil","La diversité des horaires","La dépendance aux outils numériques","Le besoin d'un rendez-vous"],"passage":"Les consultations d'un centre se réservent aussi par téléphone. Le site internet n'est pas l'unique moyen d'obtenir un créneau.\n\nLes personnes qui appellent reçoivent les mêmes informations sur les créneaux et les documents utiles. Les secrétaires peuvent expliquer une étape incomprise sans demander l'aide d'un proche équipé. Le centre ne veut pas supprimer les démarches en ligne, pratiques pour une partie du public. Il souhaite simplement conserver une possibilité réelle pour ceux qui ne peuvent pas les utiliser seuls. Les responsables suivront les attentes sur chaque canal pour éviter qu'un accès annoncé reste beaucoup plus difficile que l'autre.","question":"Quel obstacle cherche-t-on à réduire ?","explanation":"Le passage indique : « Les consultations d'un centre se réservent aussi par téléphone. Le site internet n'est pas l'unique moyen d'obtenir un créneau. » Cela justifie la réponse : La dépendance aux outils numériques."},{"number":16,"points":15,"correct":"B","options":["Remplacer tous les meubles par des écrans","Agir sur l'organisation et les pauses","Exiger l'immobilité toute la journée","Supprimer les changements de tâche"],"passage":"Une entreprise réorganise ses postes pour éviter de rester longtemps dans la même position. Les pauses courtes complètent cet aménagement.\n\nLes salariés ont participé aux essais en indiquant les gestes qui provoquaient une gêne. Certaines tâches seront alternées et quelques équipements déplacés pour faciliter les changements de position. L'entreprise veut observer le travail réel avant de distribuer uniquement des recommandations individuelles. Une affiche pourra rappeler des repères, mais ne remplacera pas une organisation permettant effectivement de bouger.","question":"Quelle approche est adoptée ?","explanation":"Le passage indique : « Une entreprise réorganise ses postes pour éviter de rester longtemps dans la même position. Les pauses courtes complètent cet aménagement. » Cela justifie la réponse : Agir sur l'organisation et les pauses."},{"number":17,"points":15,"correct":"B","options":["Comparer uniquement les chaussures","Mieux comprendre l'effort réellement ressenti","Remplacer tout mouvement par un questionnaire","Garantir des progrès identiques"],"passage":"Un entraîneur fait noter les sensations après l'exercice, pas seulement la distance parcourue. Une même distance peut représenter un effort différent selon les jours.\n\nLe carnet reste personnel et sert de base à une discussion avec l'entraîneur. Les participants peuvent y signaler un sommeil court, une reprise après une absence ou un effort inhabituel dans la journée. Le club souhaite ainsi éviter une comparaison trop mécanique entre deux sorties. Les chiffres restent utiles pour suivre une progression, mais prennent un autre sens lorsqu'ils sont rapprochés des conditions dans lesquelles ils ont été obtenus.","question":"Pourquoi recueillir ces sensations ?","explanation":"Le passage indique : « Un entraîneur fait noter les sensations après l'exercice, pas seulement la distance parcourue. Une même distance peut représenter un effort différent selon les jours. » Cela justifie la réponse : Mieux comprendre l'effort réellement ressenti."},{"number":18,"points":15,"correct":"D","options":["Une participation obligatoirement gratuite","Une réservation réservée aux donateurs","Une portion proportionnelle au paiement","Un accueil indépendant de la contribution financière"],"passage":"Le centre social propose un atelier cuisine et santé à prix libre. Le montant versé n'influence pas la taille de la portion servie.\n\nLes participants cuisinent ensemble avant de partager le repas. Le centre souhaite préserver une activité commune plutôt que distinguer plusieurs catégories de convives. Les recettes sont pensées pour être reproduites avec un équipement courant. Le bilan prendra en compte l'équilibre financier de l'atelier, mais aussi la possibilité pour des personnes aux budgets différents de s'y retrouver régulièrement dans les mêmes conditions d'accueil.","question":"Quel principe est appliqué ?","explanation":"Le passage indique : « Le centre social propose un atelier cuisine et santé à prix libre. Le montant versé n'influence pas la taille de la portion servie. » Cela justifie la réponse : Un accueil indépendant de la contribution financière."},{"number":19,"points":15,"correct":"C","options":["Distribuer les dossards avant le départ","Remplacer les vestiaires","Faciliter la récupération dans un environnement apaisé","Organiser une seconde course"],"passage":"Pour une course locale, les organisateurs installent un espace calme après l'arrivée. Les participants peuvent récupérer sans rester dans la foule.\n\nL'organisation rappelle que cet espace ne remplace pas les secours prévus pour un problème particulier. Il répond surtout au besoin de se poser après l'effort et de retrouver ses proches tranquillement. Les responsables interrogeront les participants sur sa localisation, car un équipement utile en principe peut être délaissé s'il reste difficile à trouver au milieu des autres installations.","question":"À quoi sert cet espace ?","explanation":"Le passage indique : « Pour une course locale, les organisateurs installent un espace calme après l'arrivée. Les participants peuvent récupérer sans rester dans la foule. » Cela justifie la réponse : Faciliter la récupération dans un environnement apaisé."},{"number":20,"points":21,"correct":"C","options":["Remplacer tous les déplacements quotidiens","Sélectionner les marcheurs les plus rapides","Soutenir une pratique régulière et partagée","Atteindre une distance maximale"],"passage":"Un quartier propose des promenades accompagnées pour les personnes qui hésitent à sortir seules. Le programme varie selon le groupe : le lien social et la régularité importent davantage que le nombre de kilomètres. Les animateurs préparent plusieurs possibilités de trajet et demandent aux nouveaux venus ce qui leur paraît réalisable. Les pauses offrent un moment pour échanger avec les autres habitants. Le centre souhaite que les personnes puissent ensuite proposer elles-mêmes une sortie. Il suivra la régularité des rencontres et les relations qui se maintiennent, sans transformer le programme en concours de distance ou de vitesse.","question":"Quelle priorité est donnée ?","explanation":"Le passage indique : « Un quartier propose des promenades accompagnées pour les personnes qui hésitent à sortir seules. Le programme varie selon le groupe : le lien social et la régularité importent davantage que le nombre de kilomètres. » Cela justifie la réponse : Soutenir une pratique régulière et partagée."},{"number":21,"points":21,"correct":"C","options":["Aucune donnée n'a été recueillie","Les réponses concernent uniquement les enfants","Le profil des participants peut influencer les résultats","Les clubs refusent toute enquête"],"passage":"Une étude locale sur l'activité physique repose sur des volontaires déjà membres de clubs. Ses auteurs signalent que leurs réponses ne représentent pas forcément les personnes éloignées du sport. Les chercheurs chercheront ensuite à rencontrer d'autres habitants, y compris ceux qui ne disposent pas d'un équipement adapté ou n'aiment pas les activités proposées. Ces réponses permettront de distinguer les préférences et les obstacles. Le premier questionnaire reste utile pour comprendre la vie des clubs, mais sa portée doit être clairement annoncée.","question":"Quelle limite est reconnue ?","explanation":"Le passage indique : « Une étude locale sur l'activité physique repose sur des volontaires déjà membres de clubs. Ses auteurs signalent que leurs réponses ne représentent pas forcément les personnes éloignées du sport. » Cela justifie la réponse : Le profil des participants peut influencer les résultats."},{"number":22,"points":21,"correct":"B","options":["Confirmer que chacun l'utilise déjà","Comprendre les obstacles à une participation plus large","Supprimer toutes les activités gratuites","Fermer le terrain aux usagers actuels"],"passage":"Une commune rénove un terrain, puis observe surtout une fréquentation masculine. Elle consulte les autres habitants sur les horaires, l'éclairage et les activités proposées. Les réponses évoquent parfois la difficulté de venir sans connaître quelqu'un, ou l'absence d'une activité souhaitée. Il ne souhaite pas simplement compter les entrées et déclarer le projet terminé. La consultation doit aider à comprendre qui utilise le lieu, qui reste à l'écart et quelles modifications pourraient changer cette situation.","question":"Pourquoi poursuivre la consultation ?","explanation":"Le passage indique : « Une commune rénove un terrain, puis observe surtout une fréquentation masculine. Elle consulte les autres habitants sur les horaires, l'éclairage et les activités proposées. » Cela justifie la réponse : Comprendre les obstacles à une participation plus large."},{"number":23,"points":21,"correct":"D","options":["Celle entre débutants et entraîneurs uniquement","Celle entre les jours ouvrés et les congés scolaires","Celle entre deux vestiaires","Celle entre activité personnelle et évaluation au travail"],"passage":"Un employeur propose un cours sportif facultatif pendant la pause. Les salariés demandent que la participation ne soit pas utilisée comme signe d'engagement professionnel. Des personnes apprécient l'offre tout en préférant se reposer ou régler une démarche pendant la pause. Elles souhaitent pouvoir choisir sans craindre un jugement sur leur attitude. La direction précisera donc le caractère facultatif du cours et demandera aux responsables de ne pas le commenter dans les entretiens.","question":"Quelle séparation souhaitent-ils préserver ?","explanation":"Le passage indique : « Un employeur propose un cours sportif facultatif pendant la pause. Les salariés demandent que la participation ne soit pas utilisée comme signe d'engagement professionnel. » Cela justifie la réponse : Celle entre activité personnelle et évaluation au travail."},{"number":24,"points":21,"correct":"C","options":["Une augmentation des obstacles matériels","Un classement plus précis","Un accompagnement humain","Une fermeture des inscriptions"],"passage":"Un club prête du matériel adapté, mais manque de personnel pour accompagner les nouveaux membres. L'équipement élargit les possibilités sans suffire à assurer l'accueil. Les nouveaux pratiquants peuvent avoir besoin d'explications, de repères ou d'une présence rassurante lors des premières séances. L'association cherche donc des personnes formées à cet accueil et réorganise quelques horaires. Le bilan distinguera les prêts effectués et les séances que les personnes ont pu suivre dans de bonnes conditions.","question":"Quel besoin reste présent ?","explanation":"Le passage indique : « Un club prête du matériel adapté, mais manque de personnel pour accompagner les nouveaux membres. L'équipement élargit les possibilités sans suffire à assurer l'accueil. » Cela justifie la réponse : Un accompagnement humain."},{"number":25,"points":21,"correct":"C","options":["L'augmentation de la fréquentation tardive suffit à confirmer la réussite même si les délais du matin augmentent.","La diminution des absences mesure l'effet du nouvel horaire, sans qu'il soit nécessaire de distinguer les publics concernés.","Une fréquentation de nouveaux publics compatible avec des délais et une qualité d'accueil acceptables.","La durée d'ouverture supplémentaire devient l'indicateur central, indépendamment du nombre de consultations effectivement réalisées."],"passage":"Un centre propose des horaires de consultation plus tardifs. Il mesure ensuite les annulations et le temps d'attente, afin de vérifier que l'ouverture répond réellement à un besoin. Les responsables regarderont notamment si de nouveaux publics peuvent venir sans demander un arrangement exceptionnel. Les équipes expliqueront aussi les contraintes rencontrées après l'ouverture. L'augmentation du nombre d'heures ne sera pas présentée comme un résultat suffisant si les créneaux restent vides ou si la qualité de l'accueil diminue. Après deux mois, les réservations tardives augmentent, mais l'attente moyenne s'allonge le lendemain matin. Les responsables séparent donc la fréquentation des nouveaux créneaux, l'arrivée de personnes auparavant empêchées et les éventuelles conséquences sur le reste du service.","question":"Quel bilan permettrait de conclure à une amélioration réelle du service ?","explanation":"C exige de toucher de nouveaux publics tout en préservant un service acceptable. A/B/D retiennent un indicateur isolé et ignorent les conséquences sur les autres créneaux."},{"number":26,"points":21,"correct":"A","options":["Parce que les rappels peuvent encourager certains utilisateurs mais exercer une pression sur d'autres.","L'utilisation des rappels mesure mieux l'assiduité que les choix de rythme ou de rendez-vous collectifs.","Des rendez-vous de groupe apportent à chacun une motivation supérieure aux messages de rappel individuels.","Les personnes ayant désactivé les messages semblent moins désireuses de poursuivre une pratique régulière."],"passage":"Une application de sport envoie des rappels quotidiens. Certains utilisateurs les trouvent utiles ; d'autres désactivent les messages pour éviter une pression supplémentaire. Elle recueillera les retours sur l'usage dans la durée, pas seulement lors de l'inscription. Les responsables veulent éviter qu'un outil présenté comme encourageant devienne une source de culpabilité. Ils rappellent qu'une notification ne remplace pas les conditions pratiques, le plaisir ou le soutien qui permettent de conserver une activité. Dans un groupe suivi six semaines, les utilisateurs qui désactivent les rappels ne sont pas tous moins actifs: certains préfèrent des rendez-vous collectifs. Ceux qui gardent les rappels ne les trouvent pas tous encourageants à chaque période.","question":"Pourquoi l'équipe ne peut-elle pas utiliser l'activation des rappels comme mesure directe de motivation ?","explanation":"A montre que le réglage des messages dépend aussi de la pression ressentie et du mode de pratique. B/D déduisent une motivation des notifications, C infère une supériorité générale du groupe non établie."},{"number":27,"points":21,"correct":"C","options":["Les questions sur les traitements peuvent être abordées collectivement si les situations comparées paraissent médicalement proches.","La comparaison de deux dossiers serait possible en groupe si l'identité des patients était omise dans la discussion.","Les questions générales peuvent être abordées publiquement, tandis que les situations médicales identifiables requièrent un cadre confidentiel.","Les informations pratiques peuvent être données pendant la réunion, mais les questions liées au fonctionnement des consultations doivent rester privées."],"passage":"Un médecin participe à une réunion publique sur la prévention. Il refuse de commenter les dossiers personnels dans la salle et propose des échanges confidentiels dans un autre cadre. Les personnes peuvent poser des questions sur l'organisation générale du service et sur les ressources disponibles. Les cas individuels seront abordés par les canaux habituels, dans des conditions permettant un échange adapté. Pendant la réunion, une personne demande si le traitement prescrit à son voisin convient à son propre cas. Le médecin explique le fonctionnement des consultations, mais reporte toute comparaison de dossiers à un entretien individuel.","question":"Quelle limite le médecin trace-t-il entre information collective et conseil individuel ?","explanation":"C autorise l'information générale et réserve les situations médicales individuelles au cadre confidentiel. A/B transforment la réunion en comparaison clinique; D classe à tort l'organisation des consultations comme sujet privé."},{"number":28,"points":21,"correct":"A","options":["L'accès réel dépend aussi des possibilités de transport pour rentrer chez soi, après la séance du soir.","Les personnes motorisées bénéficient moins des nouveaux créneaux parce qu'elles partent avant la fermeture des transports.","Les utilisateurs non motorisés quittent les lieux plus tôt principalement parce qu'ils préfèrent les séances courtes.","L'extension du gymnase réduit la demande de transport public le soir chez les usagers de tous les quartiers."],"passage":"Un gymnase reste ouvert plus longtemps, mais l'arrêt de bus ferme tôt. Les habitants sans voiture ne profitent pas des nouveaux créneaux. Les associations proposent de comparer les horaires du réseau et les sorties réelles du gymnase. Une meilleure coordination pourrait être plus utile qu'une nouvelle campagne d'inscription. Elle souhaite éviter que l'ouverture soit annoncée comme une amélioration identique pour tous, alors que certains habitants ne disposent pas du moyen de rentrer chez eux. Une enquête montre que les derniers utilisateurs du gymnase quittent les lieux avant la fermeture de l'établissement, précisément pour attraper le dernier autobus. Les résidents motorisés utilisent davantage le nouveau créneau que les autres.","question":"Pourquoi la simple extension de l'ouverture ne produit-elle pas les mêmes effets selon les habitants ?","explanation":"A constate que l'accès dépend du trajet retour et pas seulement de la salle ouverte. B inverse les groupes, C attribue une préférence sans preuve, D généralise un effet non mesuré."},{"number":29,"points":21,"correct":"D","options":["Les activités restent identiques pour tous mais leurs fréquences sont adaptées à l'âge et au niveau des participants.","Le programme renonce à mesurer les progrès individuels afin de ne pas réintroduire une comparaison liée au poids.","La perte de poids demeure la principale mesure, tandis que les exercices possibles varient selon les préférences.","Suivre plusieurs pratiques choisies selon les objectifs de chacun, plutôt que mesurer tous les progrès par le poids."],"passage":"Une association remplace son défi de perte de poids par un suivi de pratiques choisies avec les participants. Elle veut éviter de réduire le bien-être à un seul chiffre. Les participants discutent de ce qu'ils souhaitent rendre plus facile dans leur quotidien. Certains choisissent une promenade régulière, d'autres un moment de préparation des repas ou une reprise progressive d'activité. Le suivi sera ajusté à ces objectifs. Deux participants souhaitent des activités très différentes et fixent chacun un rythme réaliste. L'association évalue leur participation par rapport à leurs propres objectifs, au lieu de les classer à partir d'une variation de poids commune.","question":"Quel changement introduit le nouveau suivi par rapport à l'ancien défi ?","explanation":"D suit des pratiques choisies à partir des besoins et non un indicateur corporel unique. A conserve une pratique uniforme, B supprime le suivi pourtant individualisé, C maintient l'ancien critère."},{"number":30,"points":26,"correct":"D","options":["Une séance gratuite devient suffisante pour les personnes travaillant tard lorsque son programme correspond à leurs attentes.","La fréquence de présence permet de distinguer les personnes motivées avant d'examiner les contraintes familiales.","L'absence malgré la gratuité indique surtout une préférence pour des activités individuelles sans calendrier fixe.","Les modalités proposées peuvent rester incompatibles avec le travail ou les responsabilités familiales, pour certains participants."],"passage":"Les campagnes qui invitent chacun à bouger supposent parfois que le temps disponible est librement choisi. Les emplois du temps irréguliers et les charges familiales peuvent rendre difficile une activité régulière. Adapter les propositions suppose de comprendre ces contraintes plutôt que d'attribuer toute absence à un manque de volonté. Ils évaluent ensuite si ces possibilités touchent effectivement les personnes jusqu'alors absentes, au lieu de supposer que l'affichage d'une offre suffit à la rendre accessible. L'association organise une séance gratuite à 18 heures; elle constate que les mêmes personnes restent absentes lorsque leur travail finit après cette heure. Elle teste ensuite deux horaires et une formule pouvant être suivie en famille avant d'évaluer l'engagement.","question":"Quelle hypothèse l'association cherche-t-elle à distinguer du simple manque de volonté ?","explanation":"D identifie horaires et responsabilités comme des barrières d'accès. A suppose la gratuité suffisante, B/C infèrent une motivation ou une préférence de l'absence."},{"number":31,"points":26,"correct":"D","options":["L'évolution du nombre de nouveaux inscrits suffit pour comparer deux saisons, même lorsque les anciens ne reviennent pas.","La taille maximale de chaque groupe indique la part des participants qui pourront continuer une activité durable.","Le renouvellement des cartes donne la mesure de fidélité même si elles ne sont pas utilisées ensuite.","La proportion des participants encore actifs et les obstacles qui expliquent les départs, après plusieurs mois de pratique."],"passage":"Une salle sportive mesure le succès d'un programme par le nombre d'inscriptions. Des animateurs proposent aussi de regarder qui continue après trois mois et pour quelles raisons. Attirer un public et lui permettre de rester actif sont deux résultats liés, mais distincts. Ces échanges permettent de comprendre les obstacles et d'ajuster les séances plutôt que présenter le nombre d'inscrits comme une preuve complète de réussite. À l'inscription, deux groupes ont le même effectif. Trois mois plus tard, le premier conserve la moitié de ses membres et l'autre presque tous. Les animateurs souhaitent comprendre non seulement ce qui attire, mais ce qui rend la participation soutenable.","question":"Quelle information complète utilement le nombre initial d'inscriptions ?","explanation":"D suit la présence réelle et les causes de départ. A se limite au recrutement, B à une capacité potentielle, C à un acte administratif sans usage."},{"number":32,"points":26,"correct":"C","options":["Étendre l'observation à plusieurs utilisateurs afin de déterminer si les progrès se retrouvent avec des pratiques diverses.","Vérifier quels participants avaient bénéficié d'un accompagnement pendant l'essai avant d'interpréter ses résultats.","Généraliser à tous les acheteurs un effet obtenu sous des conditions accompagnées particulières.","Présenter l'outil comme une aide possible dont l'effet dépend de l'usage régulier, selon les limites connues."],"passage":"Une publicité promet une amélioration rapide grâce à un équipement. Un professionnel rappelle que les effets dépendent de l'usage, de la régularité et des situations individuelles. L'achat n'est donc pas en lui-même une preuve de bénéfice. L'utilisateur doit notamment savoir dans quelles conditions la comparaison a été réalisée. Une amélioration observée dans un essai précis ne se transforme pas automatiquement en promesse identique pour chaque personne achetant le produit. L'essai cité dans la publicité a été mené avec un accompagnement régulier, tandis que l'annonce vend seulement l'objet. Le professionnel demande de distinguer les conditions du test, la façon dont l'équipement est utilisé et la situation de la personne.","question":"Quelle inférence publicitaire le professionnel juge-t-il insuffisamment fondée ?","explanation":"C est l'extrapolation injustifiée d'un essai accompagné à tous les acheteurs. A/B/D sont des précautions ou interprétations compatibles avec les preuves disponibles."},{"number":33,"points":26,"correct":"D","options":["Le chemin est adopté presque uniquement par les habitants déjà inscrits à une activité sportive organisée.","Les programmes en salle perdent leur utilité, puisque la voie publique remplace la pratique d'entraînement.","Les trajets deviennent plus sûrs et encouragent surtout les anciens membres des clubs à pratiquer plus souvent.","Il facilite des marches quotidiennes sans inscription à un programme sportif, au cours de trajets ordinaires."],"passage":"Des aménagements urbains favorisent les déplacements à pied. Leur effet dépasse les personnes qui s'inscrivent volontairement à une activité : un chemin sûr et agréable modifie aussi les trajets ordinaires. La promotion du mouvement peut ainsi passer par le cadre quotidien plutôt que par des programmes spécialisés. Les services observent donc les trajets ordinaires et les points où les habitants renoncent à marcher. Le nouveau chemin est surtout fréquenté pour rejoindre les commerces et les transports. Une partie de ses utilisateurs ne participe à aucun programme sportif, mais marche plus régulièrement parce que le trajet est devenu sûr.","question":"Quel mécanisme explique que l'aménagement touche des personnes non inscrites à une activité ?","explanation":"D décrit une activité physique utilitaire créée par un trajet plus sûr, y compris chez les non-inscrits. A/C ramènent l'effet aux sportifs, B nie abusivement l'intérêt des clubs."},{"number":34,"points":26,"correct":"A","options":["Elle permet une reprise accompagnée et adaptée sans effacer le parcours déjà engagé, même après une interruption.","Une interruption oblige le participant à revalider son parcours, même lorsque ses acquis restent documentés.","La reprise suit le même protocole pour tous afin que la difficulté du retour soit évaluée de façon comparable.","Le maintien de l'ancien dossier dispense la personne de discuter avec l'animateur des capacités au retour."],"passage":"Un programme de reprise d'activité accepte les interruptions. Les participants peuvent revenir sans recommencer toutes les démarches. Les animateurs considèrent les parcours irréguliers comme une réalité à accompagner, et non comme une faute qui justifierait l'exclusion. Les animateurs demandent simplement de reprendre contact pour adapter le retour. Ils veulent maintenir une porte ouverte, tout en organisant un groupe qui puisse accueillir les personnes sans ignorer les contraintes réelles de chacune. Une participante s'interrompt plusieurs semaines pour s'occuper d'un proche. À son retour, elle reprend à un rythme réduit après un échange avec l'animateur; son ancien dossier reste valable et ses besoins sont réévalués.","question":"En quoi l'organisation favorise-t-elle une pratique durable ?","explanation":"A réunit continuité du parcours et adaptation au retour. B efface les acquis, C uniformise les besoins, D supprime l'accompagnement prévu."},{"number":35,"points":26,"correct":"C","options":["Les entretiens servent à affiner la proportion de salariés stressés, plutôt qu'à différencier les sources de tension.","Des scores comparables justifient une intervention commune avant d'examiner les mécanismes spécifiques à chaque équipe.","Ils montrent que des scores identiques peuvent recouvrir des mécanismes différents nécessitant des réponses distinctes.","Les explications recueillies permettent de recalculer le score en donnant plus de poids aux interruptions fréquentes."],"passage":"Une enquête mesure le stress au travail avec un questionnaire très court. Elle permet de repérer des tendances, mais ne décrit pas les causes précises dans chaque service. Les responsables complètent donc les chiffres par des échanges avec les équipes. Les équipes peuvent alors expliquer les interruptions, les priorités concurrentes et les moments difficiles. Le service souhaite construire des pistes d'amélioration à partir de ce dialogue, sans considérer chaque score comme une explication déjà complète. Dans deux services, la même proportion de salariés signale un stress élevé. Les entretiens révèlent pourtant des sources différentes: interruptions fréquentes dans l'un, échéances contradictoires dans l'autre. Les responsables ne veulent pas prescrire une réponse uniforme à partir du score seul.","question":"Quel apport spécifique les échanges fournissent-ils après les questionnaires ?","explanation":"C s'appuie sur les entretiens révélant des causes différentes derrière des scores égaux: interruptions d'un côté, échéances contradictoires de l'autre. A limite à tort les échanges au taux mesuré; B traite les deux services de la même manière; D transforme une explication qualitative en recalcul non prévu."},{"number":36,"points":33,"correct":"A","options":["Des freins économiques et sociaux peuvent se cumuler, d'où l'intérêt de réponses complémentaires, dans la pratique quotidienne.","Une baisse de cotisation résout la difficulté d'accès, tandis que l'accompagnement ne fait qu'améliorer le confort.","La présence d'un proche durant la première séance explique aussi le budget disponible pour continuer à venir.","Le nombre de demandes augmente suffisamment pour conclure que les freins sociaux ont diminué chez tous."],"passage":"Un club veut rendre ses activités accessibles à tous en réduisant les cotisations. Les demandes augmentent, mais des personnes restent absentes : certaines n'osent pas venir seules, d'autres ne se reconnaissent pas dans les images utilisées. L'obstacle financier est réel, sans être la seule barrière à une pratique accueillante. L'association cherche désormais des relais dans les lieux fréquentés par ces habitants et propose des premières séances accompagnées. Elle conserve aussi les tarifs réduits, car les contraintes se cumulent souvent au lieu de se remplacer. Les responsables souhaitent éviter de conclure que les absents ne s'intéressent pas à l'activité. Ils vérifieront plutôt si les nouveaux moyens d'accueil changent les expériences des personnes qui viennent pour la première fois. L'objectif reste d'ouvrir des possibilités concrètes, sans transformer une mesure utile en réponse présentée comme suffisante à toutes les difficultés. Après la réduction du prix, davantage d'habitants consultent le programme mais certains n'entrent toujours pas dans la salle. Des séances accompagnées les amènent à essayer une première fois, tandis que d'autres participants ont encore besoin du tarif réduit pour continuer.","question":"Que révèle la combinaison des tarifs réduits et des premières séances accompagnées ?","explanation":"A reconnaît des obstacles économiques et sociaux cumulables, traités par des aides complémentaires. B et D présument qu'une mesure efface l'autre difficulté; C relie sans preuve accompagnement et budget."},{"number":37,"points":33,"correct":"B","options":["La fatigue perçue doit remplacer les pas comme indicateur unique dès que les membres ressentent un changement.","Parce que des chiffres semblables peuvent recouvrir des expériences individuelles différentes, y compris à quantité de pas égale.","Le plaisir déclaré fournit une échelle commune permettant de comparer directement les résultats de tous les participants.","La durée de marche indique mieux que le total des pas si la personne peut retrouver une activité sociale."],"passage":"Les outils de suivi comptent facilement les pas ou les minutes d'exercice. Ils décrivent moins bien le plaisir, la fatigue ou la confiance retrouvée. Un animateur utilise les chiffres comme point de discussion, sans en faire la définition complète du progrès. Ce qui se mesure simplement n'épuise pas ce qui compte pour la personne. Une personne peut marcher moins longtemps qu'une autre tout en retrouvant la possibilité de sortir de chez elle. Une autre cherche surtout à partager une activité avec des amis. L'animateur souhaite pouvoir entendre ces objectifs sans les remplacer par un classement unique. Il ne rejette pas les mesures, mais demande qu'elles restent des outils de compréhension. Les participants pourront choisir ce qu'ils veulent suivre et expliquer ce qu'ils ressentent. Deux membres atteignent le même nombre de pas. L'une se fatigue davantage qu'avant; l'autre se sent capable de reprendre un trajet qu'elle évitait. L'animateur conserve la mesure, mais discute de ce qu'elle représente réellement pour chacun.","question":"Pourquoi l'animateur ne classe-t-il pas les progrès à partir du seul nombre de pas ?","explanation":"B constate que des totaux égaux peuvent correspondre à des situations distinctes de fatigue ou d'autonomie. A/C substituent un autre classement unique, et D attribue à la durée un pouvoir de description non démontré."},{"number":38,"points":33,"correct":"A","options":["Adapter les équipements à des usages de rencontre observés après l'ouverture, sans les limiter au sport.","Sur une hausse générale de l'activité physique due aux bancs, mesurée avant les premières rencontres du quartier.","Sur la nécessité de réserver les appareils aux usagers qui les utilisent selon les exercices du plan initial.","Sur un objectif de fréquentation sportive qui demeure inchangé malgré les rencontres spontanées observées."],"passage":"Une ville installe des équipements sportifs dans un parc. Les services observent des usages imprévus : certains habitants s'y retrouvent pour discuter et font quelques mouvements ensemble. Plutôt que restreindre cet usage, ils ajoutent des bancs. Un aménagement peut produire des bénéfices différents de ceux que ses concepteurs avaient précisément anticipés. Les agents constatent que les rencontres régulières encouragent parfois des personnes jusque-là hésitantes à essayer les appareils. Ils vont donc continuer à observer le lieu à différentes heures avant de fixer de nouvelles règles. Les usagers pourront proposer de petits changements et signaler les difficultés. La commune ne veut pas transformer chaque usage imprévu en erreur à corriger. Elle cherche à comprendre ce que l'installation rend possible dans la vie du quartier, au-delà du programme exact qui avait été imaginé sur le plan initial. Lorsque les bancs sont installés, des personnes qui venaient d'abord pour discuter commencent à utiliser les appareils avec des voisins. Les agents notent cette évolution sans la traiter comme le résultat nécessairement prévu dès la conception.","question":"Sur quoi repose l'adaptation décidée par la ville ?","explanation":"A décrit l'adaptation à des usages réels, notamment les échanges et l'essai progressif des appareils. B affirme un effet général non mesuré, C restreint les usages que la ville accueille, D ignore l'ajustement du projet."},{"number":39,"points":33,"correct":"A","options":["Les séances semblent améliorer le ressenti immédiat dans les deux services; la réduction durable des heures supplémentaires coïncide avec une réorganisation, sans preuve causale isolée.","La baisse des heures supplémentaires dans le premier service montre que les séances de relaxation y ont fonctionné plus efficacement que dans le second, même si les salariés décrivent des charges de travail initiales différentes.","La proximité des effectifs permet d'isoler l'effet de la réorganisation malgré l'absence de tirage au sort.","Les déclarations positives des deux équipes rendent secondaires les différences d'heures supplémentaires observées pendant le suivi."],"passage":"Une organisation souhaite prévenir l'épuisement professionnel en proposant des séances de relaxation. Les salariés apprécient l'offre, mais demandent aussi de revoir une répartition de tâches devenue irréaliste. Un soutien individuel peut être utile sans remplacer la transformation des conditions collectives qui produisent la difficulté. Certains décrivent des journées où les demandes s'ajoutent sans que les priorités soient revues. D'autres évoquent des interruptions qui rendent difficile l'achèvement d'une tâche. Les représentants souhaitent que ces éléments soient discutés avec les responsables du service. Ils ne demandent pas de supprimer les séances proposées, mais de ne pas les utiliser comme preuve que le problème serait désormais traité. Le programme sera donc accompagné d'un examen des effectifs, des délais et des possibilités de récupération. Son intérêt dépendra aussi de cette cohérence entre aide personnelle et fonctionnement quotidien du travail. Dans un service, une séance de relaxation a lieu chaque semaine, mais la quantité de dossiers urgents ne change pas et les heures supplémentaires continuent d'augmenter. Le comité propose d'évaluer séparément les bénéfices ressentis de la séance et les effets d'une révision des délais. Pour vérifier ce qui change réellement, deux services de taille proche conservent les mêmes séances hebdomadaires pendant huit semaines. Dans le premier, les responsables révisent également les délais et répartissent les urgences; dans le second, le nombre de dossiers et les interruptions restent inchangés. Dans les deux services, les participants déclarent se sentir plus détendus immédiatement après la séance. Mais seul le premier présente une baisse durable des heures supplémentaires. Les salariés de ce premier service disent aussi avoir pu refuser certaines urgences sans justification individuelle. La direction signale que les deux équipes n'étaient pas constituées par tirage au sort et que les volumes de dossiers avaient déjà légèrement divergé avant le début de l'observation. Le comité refuse donc d'attribuer avec certitude toute la différence à la réorganisation, tout en refusant d'assimiler le ressenti à une réduction de la surcharge.","question":"Quelle interprétation des observations reste la mieux justifiée sans attribuer abusivement les résultats à une seule mesure ?","explanation":"A sépare le soulagement déclaré dans les deux services de la baisse durable des heures supplémentaires, observée seulement avec une réorganisation. B suppose un effet propre plus fort des séances; C isole abusivement un effet causal sans répartition aléatoire; D minimise une différence objective de surcharge."}]}$bank_8$::jsonb),
('tcf-reading-09','tcf-reading-2026-11-close-reading-v4',$bank_9${"id":"tcf-reading-09","title":"TCF Reading · Test 09","seconds":3600,"version":"tcf-reading-2026-11-close-reading-v4","maxPoints":699,"questions":[{"number":1,"points":3,"correct":"B","options":["Acheter un billet obligatoire","Assister à la séance de quinze heures","Revenir uniquement le mois prochain","Visiter gratuitement une autre ville"],"passage":"Le planétarium annule la séance de midi pour réparation. Les billets restent valables pour celle de quinze heures.\n\nLes personnes indisponibles pourront contacter l'accueil pour un échange. La boutique restera ouverte pendant les horaires habituels du musée.","question":"Quelle solution est proposée ?","explanation":"Le passage indique : « Le planétarium annule la séance de midi pour réparation. Les billets restent valables pour celle de quinze heures. » Cela justifie la réponse : Assister à la séance de quinze heures."},{"number":2,"points":3,"correct":"A","options":["Un carnet","Un tournevis","Une perceuse","Un robot terminé"],"passage":"L'atelier robotique prête des tournevis. Apportez seulement un carnet pour noter vos essais.\n\nLes animateurs montreront comment utiliser chaque outil. Aucun montage ne devra être commencé avant la présentation des consignes communes.","question":"Quel objet faut-il apporter ?","explanation":"Le passage indique : « L'atelier robotique prête des tournevis. Apportez seulement un carnet pour noter vos essais. » Cela justifie la réponse : Un carnet."},{"number":3,"points":3,"correct":"B","options":["Uniquement les chercheurs","Des enfants accompagnés et inscrits","Des classes sans réservation","Des mineurs obligatoirement seuls"],"passage":"Le laboratoire ouvre ses portes samedi sur inscription. Les enfants doivent être accompagnés ; les groupes scolaires ont un autre créneau.\n\nUne confirmation précisera l'entrée et la durée du parcours.","question":"Qui peut venir samedi ?","explanation":"Le passage indique : « Le laboratoire ouvre ses portes samedi sur inscription. Les enfants doivent être accompagnés ; les groupes scolaires ont un autre créneau. » Cela justifie la réponse : Des enfants accompagnés et inscrits."},{"number":4,"points":3,"correct":"D","options":["Tout le matériel est vendu","L'horaire est reporté d'un an","Les participants montent seuls sur le toit","L'activité se poursuit à l'intérieur"],"passage":"L'observation des étoiles dépend de la météo. Si le ciel est couvert, une présentation aura lieu dans la salle attenante.\n\nCette solution permet de conserver la rencontre même si les conditions extérieures sont défavorables.","question":"Que se passe-t-il en cas de nuages ?","explanation":"Le passage indique : « L'observation des étoiles dépend de la météo. Si le ciel est couvert, une présentation aura lieu dans la salle attenante. » Cela justifie la réponse : L'activité se poursuit à l'intérieur."},{"number":5,"points":9,"correct":"C","options":["Pour supprimer tous les résultats","Pour attendre un financement","Pour contrôler la fiabilité de l'instrument","Pour changer le sujet du projet"],"passage":"Je t'envoie mes mesures demain après avoir vérifié le thermomètre. Les valeurs de ce matin semblaient inhabituelles.\n\nJ'ai demandé à une collègue de refaire un relevé avec un autre appareil. Nous comparerons les deux séries avant de rédiger le compte rendu et de tirer une conclusion.","question":"Pourquoi l'envoi est-il différé ?","explanation":"Le passage indique : « Je t'envoie mes mesures demain après avoir vérifié le thermomètre. Les valeurs de ce matin semblaient inhabituelles. » Cela justifie la réponse : Pour contrôler la fiabilité de l'instrument."},{"number":6,"points":9,"correct":"C","options":["Une caméra professionnelle","Une antenne radio","Aucun télescope n'est exigé","Un grand télescope"],"passage":"Le club d'astronomie accueille les curieux sans télescope personnel. Des instruments seront installés par les bénévoles.\n\nLes bénévoles aideront chacun à regarder et répondront aux questions. Une carte du ciel sera distribuée pour retrouver ensuite quelques repères sans matériel complexe.","question":"Quel équipement personnel est obligatoire ?","explanation":"Le passage indique : « Le club d'astronomie accueille les curieux sans télescope personnel. Des instruments seront installés par les bénévoles. » Cela justifie la réponse : Aucun télescope n'est exigé."},{"number":7,"points":9,"correct":"A","options":["Une faible lumière extérieure","Un accès réservé aux vendeurs","Une exposition maximale au soleil","Une température tropicale"],"passage":"Notre groupe cherche un local sombre pour tester les lampes. Une grande fenêtre rendrait les comparaisons plus difficiles.\n\nIl nous faut surtout garder les mêmes conditions pendant les essais. Nous noterons chaque changement pour comprendre ce qui pourrait expliquer une différence entre deux résultats.","question":"Quelle caractéristique du local est recherchée ?","explanation":"Le passage indique : « Notre groupe cherche un local sombre pour tester les lampes. Une grande fenêtre rendrait les comparaisons plus difficiles. » Cela justifie la réponse : Une faible lumière extérieure."},{"number":8,"points":9,"correct":"A","options":["Aussi aux personnes sans formation scientifique","Uniquement aux chercheurs diplômés","Seulement aux vendeurs d'instruments","Aux participants refusant les explications"],"passage":"Bonjour, la conférence reste ouverte aux non-spécialistes. Le vocabulaire sera expliqué et un temps sera prévu pour les questions.\n\nLes personnes souhaitant approfondir recevront des références après la rencontre, sans devoir tout comprendre dès les premières minutes.","question":"À quel public s'adresse l'événement ?","explanation":"Le passage indique : « Bonjour, la conférence reste ouverte aux non-spécialistes. Le vocabulaire sera expliqué et un temps sera prévu pour les questions. » Cela justifie la réponse : Aussi aux personnes sans formation scientifique."},{"number":9,"points":9,"correct":"D","options":["La présence d'un animateur","L'observation des pièces","L'ouverture de l'atelier","La réparation de l'appareil"],"passage":"Apportez votre appareil cassé à l'atelier démontage. Nous étudierons ses composants, sans garantir sa remise en marche.\n\nLes objets dangereux ou trop volumineux seront refusés, et les propriétaires repartiront avec les pièces à la fin de la séance.","question":"Quel résultat n'est pas garanti ?","explanation":"Le passage indique : « Apportez votre appareil cassé à l'atelier démontage. Nous étudierons ses composants, sans garantir sa remise en marche. » Cela justifie la réponse : La réparation de l'appareil."},{"number":10,"points":9,"correct":"C","options":["Éviter toute répétition","Obtenir un résultat décidé d'avance","Rendre les conditions comparables","Augmenter la couleur des liquides"],"passage":"Nous répéterons l'expérience avec des récipients identiques. Les formes différentes utilisées hier empêchaient de comparer correctement.\n\nNous conserverons les autres paramètres pour mieux identifier l'effet observé. Le groupe préparera un tableau commun avant de recommencer les mesures dans les conditions prévues.","question":"Pourquoi changer les récipients ?","explanation":"Le passage indique : « Nous répéterons l'expérience avec des récipients identiques. Les formes différentes utilisées hier empêchaient de comparer correctement. » Cela justifie la réponse : Rendre les conditions comparables."},{"number":11,"points":15,"correct":"A","options":["L'heure de la mesure","Le lieu choisi","La longueur du bâton","Le nombre de saisons"],"passage":"Des collégiens mesurent l'ombre d'un bâton à plusieurs heures. Ils gardent le bâton au même endroit pour observer l'évolution au cours de la journée.\n\nIls notent chaque observation sur un dessin du sol, avec la date et l'état du ciel. Les journées couvertes donnent aussi lieu à une discussion sur ce qui reste visible. Leur professeur ne leur demande pas de retrouver un chiffre annoncé d'avance, mais de décrire une série cohérente. Les résultats seront comparés entre deux groupes pour repérer les difficultés de lecture. Les élèves expliqueront ensuite les limites de leur expérience, notamment ce qu'ils ne peuvent pas déduire d'une seule journée d'observation.","question":"Qu'est-ce qui varie dans leur protocole ?","explanation":"Le passage indique : « Des collégiens mesurent l'ombre d'un bâton à plusieurs heures. Ils gardent le bâton au même endroit pour observer l'évolution au cours de la journée. » Cela justifie la réponse : L'heure de la mesure."},{"number":12,"points":15,"correct":"B","options":["Dissimuler les méthodes employées","Rendre les tentatives infructueuses utiles à d'autres","Remplacer les expériences futures par des opinions","Prouver que toute recherche échoue"],"passage":"Une équipe publie aussi les essais qui n'ont pas confirmé son hypothèse. Ces résultats peuvent éviter à d'autres de répéter inutilement les mêmes démarches.\n\nLe compte rendu décrit les conditions et les vérifications réalisées avant l'arrêt de la tentative. Les auteurs souhaitent rendre ces informations compréhensibles, même lorsque le résultat ne se transforme pas en application immédiate. Une autre équipe pourra ainsi comparer ses propres méthodes et identifier une différence utile.","question":"Quel intérêt présente cette publication ?","explanation":"Le passage indique : « Une équipe publie aussi les essais qui n'ont pas confirmé son hypothèse. Ces résultats peuvent éviter à d'autres de répéter inutilement les mêmes démarches. » Cela justifie la réponse : Rendre les tentatives infructueuses utiles à d'autres."},{"number":13,"points":15,"correct":"D","options":["Elle fonctionne comme un volcan réel","Elle remplace toutes les observations","Elle permet de prévoir toute éruption","Elle simplifie la réalité"],"passage":"Un musée prête une maquette démontable de volcan. Les visiteurs découvrent une représentation simplifiée, pas une reproduction de tous les phénomènes réels.\n\nLes médiateurs montrent ce qui a été conservé et ce qui a été laissé de côté pour rendre l'ensemble lisible. Les visiteurs peuvent poser des questions sur la différence entre une représentation et une observation sur le terrain. Des photographies et des mesures complètent donc l'activité. Elles permettent de comprendre pourquoi plusieurs outils sont nécessaires pour étudier un phénomène dont les dimensions et les rythmes ne tiennent pas dans une salle.","question":"Quelle limite de la maquette est indiquée ?","explanation":"Le passage indique : « Un musée prête une maquette démontable de volcan. Les visiteurs découvrent une représentation simplifiée, pas une reproduction de tous les phénomènes réels. » Cela justifie la réponse : Elle simplifie la réalité."},{"number":14,"points":15,"correct":"C","options":["Rendre les capteurs invisibles aux oiseaux","Augmenter automatiquement les températures","Éviter une influence locale qui fausserait la comparaison","Accélérer la croissance des arbres"],"passage":"Des bénévoles relèvent la température de leur quartier. Les capteurs sont placés à l'ombre, loin des murs chauffés par le soleil.\n\nLes participants reçoivent une fiche d'installation et photographient l'emplacement choisi. Une équipe vérifiera quelques points avant d'utiliser les séries dans une carte commune. Les habitants peuvent aussi noter les changements survenus autour du capteur, comme un déplacement ou des travaux. Le projet souhaite multiplier les observations sans présenter tous les nombres recueillis comme directement comparables. Les consignes communes servent à distinguer une différence entre quartiers d'un effet produit par la manière de placer l'appareil.","question":"Pourquoi préciser leur emplacement ?","explanation":"Le passage indique : « Des bénévoles relèvent la température de leur quartier. Les capteurs sont placés à l'ombre, loin des murs chauffés par le soleil. » Cela justifie la réponse : Éviter une influence locale qui fausserait la comparaison."},{"number":15,"points":15,"correct":"D","options":["Le prix du verre","La vitesse de livraison du produit","La couleur des couvercles","La facilité d'utilisation pour divers profils"],"passage":"Une invention facilite l'ouverture des bocaux. Ses concepteurs invitent des utilisateurs aux forces différentes pour tester la poignée.\n\nLes volontaires essaient plusieurs positions et expliquent les moments où la prise leur semble inconfortable. Les concepteurs notent aussi les remarques des personnes qui comprennent moins vite la forme du dispositif. L'essai ne consiste pas à choisir l'utilisateur le plus habile, mais à voir si la poignée facilite réellement le geste pour des personnes différentes. Les prototypes seront modifiés avant une seconde séance. Le groupe veut éviter qu'un bon résultat obtenu par une seule personne serve de promesse générale au moment de présenter le produit.","question":"Quel critère veulent-ils examiner ?","explanation":"Le passage indique : « Une invention facilite l'ouverture des bocaux. Ses concepteurs invitent des utilisateurs aux forces différentes pour tester la poignée. » Cela justifie la réponse : La facilité d'utilisation pour divers profils."},{"number":16,"points":15,"correct":"C","options":["Éviter toute comparaison","Remplacer les images actuelles par des publicités","Observer des changements sur la durée","Garantir que rien ne change"],"passage":"Un observatoire diffuse des images en direct, mais archive aussi les séries anciennes. Les comparaisons dans le temps aident à repérer des évolutions lentes.\n\nLes responsables gardent les dates, les réglages et les informations sur les instruments utilisés. Les chercheurs qui consultent les archives peuvent ainsi apprécier les différences entre deux séries. L'observatoire souhaite que les anciennes données restent compréhensibles lorsque les appareils changent. Il ne conserve pas seulement de belles images, mais des éléments permettant de poser de nouvelles questions.","question":"À quoi servent les archives ?","explanation":"Le passage indique : « Un observatoire diffuse des images en direct, mais archive aussi les séries anciennes. Les comparaisons dans le temps aident à repérer des évolutions lentes. » Cela justifie la réponse : Observer des changements sur la durée."},{"number":17,"points":15,"correct":"D","options":["Le nombre d'affiches commerciales","Le nom du livreur","La forme de la facture","L'autonomie de la batterie"],"passage":"Un fabricant annonce une batterie plus légère. L'équipe de test mesure aussi sa durée de fonctionnement avant de juger le progrès.\n\nLes essais portent sur des usages comparables, avec les mêmes réglages. L'équipe indique les conditions retenues pour que les lecteurs puissent apprécier la portée du résultat. Elle examine aussi les situations où le gain de poids serait particulièrement utile. Un appareil destiné à rester posé ne présente pas les mêmes besoins qu'un équipement porté pendant plusieurs heures. Les résultats seront donc présentés avec plusieurs critères plutôt qu'une seule formule annonçant un progrès identique pour tous les acheteurs.","question":"Quelle information complémentaire est nécessaire ?","explanation":"Le passage indique : « Un fabricant annonce une batterie plus légère. L'équipe de test mesure aussi sa durée de fonctionnement avant de juger le progrès. » Cela justifie la réponse : L'autonomie de la batterie."},{"number":18,"points":15,"correct":"C","options":["Écarter tous les non-spécialistes","Interdire les désaccords","Mieux organiser la discussion","Fixer les réponses avant le débat"],"passage":"La médiathèque organise un débat avec une chercheuse. Les questions seront regroupées par thème pour éviter de répéter les mêmes échanges.\n\nLes participants peuvent envoyer une question auparavant ou la poser pendant le temps d'échange. L'animatrice expliquera pourquoi certaines demandes sont rapprochées et laissera la possibilité de signaler un point oublié. La bibliothèque souhaite conserver une discussion accessible malgré la diversité du public. La chercheuse pourra préciser ce qu'elle sait et ce qui dépasse son domaine de travail.","question":"Pourquoi regrouper les questions ?","explanation":"Le passage indique : « La médiathèque organise un débat avec une chercheuse. Les questions seront regroupées par thème pour éviter de répéter les mêmes échanges. » Cela justifie la réponse : Mieux organiser la discussion."},{"number":19,"points":15,"correct":"A","options":["Explorer le fonctionnement du dispositif","Éviter de modifier l'orientation","Ouvrir immédiatement un restaurant","Garantir une cuisson par tous les temps"],"passage":"Un club construit un four solaire. Le repas prévu reste simple : l'objectif est de comprendre les effets de l'orientation et de l'ensoleillement.\n\nLes participants compareront plusieurs positions et noteront le temps nécessaire dans les conditions du jour. Le responsable a prévu une solution pour le repas si le ciel se couvre durablement. Il veut éviter que cette contrainte empêche de poursuivre les observations. Le groupe discutera ensuite de ce que l'essai montre réellement et des situations où un tel appareil peut être utile.","question":"Quel est l'objectif principal ?","explanation":"Le passage indique : « Un club construit un four solaire. Le repas prévu reste simple : l'objectif est de comprendre les effets de l'orientation et de l'ensoleillement. » Cela justifie la réponse : Explorer le fonctionnement du dispositif."},{"number":20,"points":21,"correct":"B","options":["Les essais sur petites pièces sont toujours inutiles","Le changement d'échelle doit être vérifié","Les matériaux sont déjà interdits","Toute comparaison est impossible"],"passage":"Une étude compare deux matériaux sur de petites pièces. Ses auteurs demandent des essais supplémentaires avant de généraliser les résultats à de grandes constructions. Les spécialistes devront notamment examiner la résistance dans la durée et les contraintes de fabrication. Une petite pièce permet de contrôler facilement certaines conditions qui deviennent plus difficiles à maintenir ailleurs. Le laboratoire souhaite publier un résultat utile sans lui attribuer une portée que l'expérience n'a pas encore vérifiée. Les partenaires pourront ensuite choisir les essais nécessaires à leur propre projet.","question":"Quelle prudence expriment-ils ?","explanation":"Le passage indique : « Une étude compare deux matériaux sur de petites pièces. Ses auteurs demandent des essais supplémentaires avant de généraliser les résultats à de grandes constructions. » Cela justifie la réponse : Le changement d'échelle doit être vérifié."},{"number":21,"points":21,"correct":"C","options":["Éliminer les artisans du projet","Choisir uniquement la meilleure photographie","Croiser mesures techniques et expérience d'usage","Remplacer toute mesure par une anecdote"],"passage":"Un laboratoire échange avec des artisans sur les usages d'un nouvel outil. Les chercheurs disposent de mesures précises ; les professionnels signalent des contraintes rencontrées pendant une journée réelle. Un outil rapide sur une table d'essai peut être difficile à nettoyer, à ranger ou à utiliser avec des gants. Les artisans décrivent ces situations avec des exemples. L'équipe veut intégrer ces remarques pendant qu'il est encore possible de modifier le prototype. La consultation ne remplace pas les mesures ; elle aide à choisir celles qui correspondent aux difficultés réellement rencontrées.","question":"Quel est l'intérêt de l'échange ?","explanation":"Le passage indique : « Un laboratoire échange avec des artisans sur les usages d'un nouvel outil. Les chercheurs disposent de mesures précises ; les professionnels signalent des contraintes rencontrées pendant une journée réelle. » Cela justifie la réponse : Croiser mesures techniques et expérience d'usage."},{"number":22,"points":21,"correct":"B","options":["Un laboratoire et un musée","Un potentiel et un résultat déjà généralisable","Une expérience et une absence totale de résultat","Deux découvertes nécessairement opposées"],"passage":"Une annonce parle d'une découverte « prometteuse ». Le compte rendu précise qu'elle a été observée dans des conditions limitées. Les deux formulations ne sont pas contradictoires, mais elles n'autorisent pas la même attente. Les journalistes sont invités à expliquer la taille de l'essai et les étapes encore nécessaires. Les chercheurs ne souhaitent ni minimiser une piste intéressante, ni laisser croire qu'elle donne déjà une solution disponible pour tous.","question":"Que faut-il distinguer ?","explanation":"Le passage indique : « Une annonce parle d'une découverte « prometteuse ». Le compte rendu précise qu'elle a été observée dans des conditions limitées. Les deux formulations ne sont pas contradictoires, mais elles n'autorisent pas la même attente. » Cela justifie la réponse : Un potentiel et un résultat déjà généralisable."},{"number":23,"points":21,"correct":"A","options":["Relier les mesures aux situations vécues","Remplacer la carte par des votes","Annuler toutes les températures enregistrées","Garantir une météo uniforme"],"passage":"Une ville utilise des capteurs pour repérer les îlots de chaleur. Elle confronte les données aux témoignages des habitants, notamment pour identifier les lieux utilisés aux heures chaudes. Certains points sont très chauds mais peu fréquentés, tandis que d'autres accueillent de longues attentes sans ombre. Les responsables souhaitent distinguer ces situations avant de décider où intervenir. Les témoignages ne changent pas la température mesurée ; ils apportent une information sur son importance dans la vie quotidienne.","question":"Pourquoi ajouter ces témoignages ?","explanation":"Le passage indique : « Une ville utilise des capteurs pour repérer les îlots de chaleur. Elle confronte les données aux témoignages des habitants, notamment pour identifier les lieux utilisés aux heures chaudes. » Cela justifie la réponse : Relier les mesures aux situations vécues."},{"number":24,"points":21,"correct":"B","options":["L'absence de tout réglage","La vérification des mesures","La suppression des relevés","L'achat d'un appareil plus lourd"],"passage":"Un appareil de mesure devient moins cher. Les utilisateurs doivent toujours l'étalonner : une grande diffusion ne garantit pas que chaque instrument donne spontanément une valeur fiable. La notice fournit une procédure courte et un repère pour contrôler l'appareil. Les utilisateurs peuvent signaler une difficulté au distributeur ou à l'association qui organise les relevés. Un instrument accessible financièrement reste utile si les personnes savent aussi dans quelles conditions elles peuvent se fier aux valeurs qu'il affiche.","question":"Quelle exigence demeure ?","explanation":"Le passage indique : « Un appareil de mesure devient moins cher. Les utilisateurs doivent toujours l'étalonner : une grande diffusion ne garantit pas que chaque instrument donne spontanément une valeur fiable. » Cela justifie la réponse : La vérification des mesures."},{"number":25,"points":21,"correct":"D","options":["Une ouverture rapide permet de diagnostiquer correctement la panne sans vérifier si la pièce concernée est vendue séparément.","Remplacer le mécanisme entier peut simplifier la réparation, même si seule une pièce fragile est défectueuse.","Une ouverture rapide rend la réparation accessible dès lors que le mécanisme complet est proposé à la vente.","Parce que le diagnostic et l'accès à l'élément à remplacer conditionnent aussi la réparation effective, sur le terrain."],"passage":"Un concours récompense une solution réparable avec des outils courants. Le jury regarde aussi les pièces détachées disponibles ; une conception démontable serait peu utile sans possibilité de remplacer les éléments. Les candidats présentent un exemple de démontage et expliquent les outils nécessaires. Le jury demande aussi comment un utilisateur pourra identifier la pièce défectueuse. Il souhaite distinguer une possibilité théorique d'ouverture et une réparation réellement réalisable. Un appareil s'ouvre en moins de cinq minutes, mais sa pièce la plus fragile n'est vendue qu'avec l'ensemble du mécanisme. Un autre demande un démontage plus long mais permet l'achat de l'élément seul. Le jury compare alors faisabilité matérielle et réparation accessible.","question":"Pourquoi la facilité de démontage ne suffit-elle pas à désigner le produit le plus réparable ?","explanation":"D exige l'identification de la panne et l'accès réel à la pièce à remplacer. A et C présument que l'ouverture ou la vente d'un ensemble suffit à la réparation accessible; B néglige la difficulté et le coût d'un remplacement intégral pour une seule pièce."},{"number":26,"points":21,"correct":"A","options":["Confronter des hypothèses divergentes aux mêmes observations et à des mesures qui pourraient les départager.","Les spécialistes doivent choisir l'explication la plus largement admise avant de recueillir de nouvelles mesures.","L'écart entre leurs hypothèses rend les relevés communs trop incertains pour être comparés efficacement.","Leur désaccord tient principalement à des méthodes différentes qu'ils n'ont pas encore cherché à harmoniser."],"passage":"Des scientifiques expliquent leur travail dans des ateliers publics. Ils présentent leurs désaccords sur certaines interprétations sans remettre en cause les observations communes. Les visiteurs découvrent des méthodes communes de vérification, mais aussi des questions qui restent ouvertes. Les intervenants expliquent comment ils comparent leurs interprétations et quelles observations pourraient les conduire à changer d'avis. Le programme veut donner une image plus précise du travail scientifique, sans le réduire à une collection de certitudes ni à une simple opposition d'opinions sans critères partagés. Deux spécialistes utilisent les mêmes mesures, mais l'un attribue l'écart à l'appareil et l'autre à une variation naturelle. Ils présentent un prochain relevé qui pourrait départager ces hypothèses plutôt que demander au public de choisir par préférence.","question":"Que révèle le désaccord présenté pendant l'atelier ?","explanation":"A montre que les hypothèses partagent des observations et peuvent être départagées par des tests. B demande une adhésion préalable, C nie la comparabilité, D attribue le désaccord à des méthodes divergentes alors que les mesures sont communes."},{"number":27,"points":21,"correct":"A","options":["Il aide à détecter les anomalies manquées par le logiciel avant le jugement humain, par un contrôle ciblé.","L'examen des images non signalées confirme la fiabilité globale du tri tant qu'aucune anomalie n'a été signalée.","Le contrôle des images rejetées permet de réduire l'intervention des lecteurs humains après une première validation automatique.","Le contrôle sert surtout à estimer combien de temps le logiciel économise sur les images ordinaires sans anomalie."],"passage":"Un logiciel repère des anomalies dans des photographies. Les cas signalés sont ensuite examinés par une personne. L'outil accélère le tri, mais ne remplace pas la décision finale. Les personnes chargées de la lecture finale doivent comprendre les erreurs possibles et les limites des images utilisées. Le laboratoire conserve aussi des exemples où le logiciel n'a rien signalé, afin de vérifier ce qu'il pourrait manquer. Le logiciel détecte souvent de faibles contrastes mais manque parfois une anomalie à la périphérie. Le laboratoire vérifie des images signalées et non signalées, puis confie le jugement final à un lecteur formé.","question":"Quel rôle joue l'examen d'images que le logiciel n'a pas signalées ?","explanation":"A décrit la recherche d'anomalies manquées pour vérifier les faux négatifs. B prend l'absence d'alerte pour preuve, C réduit à tort la supervision, D limite l'évaluation à la vitesse."},{"number":28,"points":21,"correct":"C","options":["Le changement d'appareil confirme un effet de la température, mais montre que les autres paramètres de préparation sont secondaires.","La reproduction partielle établit que l'appareil n'influence pas le résultat si la température est conservée.","Le résultat semble transférable sous certaines conditions de préparation qu'il faut expliciter, pour ce type de matériau.","La dépendance à la température réduit la fiabilité initiale au point de devoir suspendre toute conclusion."],"passage":"Une équipe répète une expérience dans un second laboratoire. Les conditions sont décrites précisément afin de comprendre d'éventuelles différences. Les équipes gardent une trace des réglages et discutent des écarts avant de modifier leur protocole. Elles veulent distinguer un effet du matériel d'une différence liée à la préparation. Il reste essentiel pour savoir dans quelles conditions un résultat peut être utilisé par d'autres personnes et avec quel degré de confiance. Le second laboratoire retrouve l'effet avec un appareil différent, mais seulement lorsque les échantillons sont préparés à la même température que dans le premier. Les chercheurs enregistrent ce paramètre pour préciser la portée de l'observation.","question":"Quelle conclusion est justifiée par la reproduction partielle du résultat ?","explanation":"C reconnaît la reproduction sous une condition de température qu'il faut préciser. A écarte sans preuve d'autres paramètres de préparation; B généralise l'indépendance du matériel; D veut suspendre toute conclusion alors que la portée de l'effet a été mieux définie."},{"number":29,"points":21,"correct":"C","options":["Une démonstration techniquement réussie suffit pour prévoir l'adoption si le produit répond aux performances annoncées.","Les coûts d'entretien peuvent affecter l'adoption, mais les habitudes des utilisateurs se modifient automatiquement après l'achat.","L'adoption dépend aussi des coûts et des pratiques des utilisateurs concernés, au-delà de la performance technique.","Les premières inventions avaient moins de qualités techniques, ce qui explique leur moindre diffusion malgré les démonstrations."],"passage":"Une exposition présente des inventions abandonnées. Certaines avaient de bonnes performances techniques, mais ne répondaient pas aux pratiques ou aux moyens des utilisateurs. Les visiteurs peuvent ainsi suivre une histoire moins simple qu'une opposition entre réussite et mauvaise invention. Le musée souhaite montrer que l'adoption d'un objet dépend de plusieurs acteurs et de contraintes concrètes, qui ne sont pas toujours visibles dans une démonstration technique réalisée devant un public enthousiaste. Une invention démontrée avec succès exigeait toutefois une maintenance chère et des gestes absents des habitudes du public visé. Une autre, moins spectaculaire, a été adoptée grâce à son intégration facile dans le travail courant.","question":"Que met en évidence la comparaison des deux inventions ?","explanation":"C associe l'adoption aux coûts et aux pratiques. A suppose un transfert automatique de performance à usage, B minimise la difficulté d'intégration, D attribue l'échec à une faible qualité technique non établie."},{"number":30,"points":26,"correct":"B","options":["Une moyenne plus élevée permettrait de distinguer directement les résultats dispersés sans consulter les notes individuelles.","Une moyenne identique peut masquer des distributions et des besoins différents, dans les classes étudiées.","Une distribution présentant des extrêmes donne nécessairement une moyenne trompeuse qu'il faudrait recalculer autrement.","Deux groupes ayant la même moyenne montrent des performances comparables dans presque toutes les catégories d'élèves."],"passage":"Un chiffre moyen résume une série de mesures, mais peut masquer des écarts importants. Une médiatrice montre deux ensembles ayant la même moyenne et des répartitions très différentes. L'indicateur reste correct ; sa lecture doit être complétée. Elle invite donc le public à regarder plusieurs valeurs et les écarts entre elles. Les participants apprennent à poser une question sur ce qu'un résumé laisse visible ou rend plus difficile à voir. Une classe et une autre obtiennent une note moyenne de 12; dans la première, presque tous se situent autour de 12, tandis que la seconde rassemble surtout des notes très faibles et très fortes. La moyenne ne change pas, mais les besoins d'accompagnement sont différents.","question":"Pourquoi le même chiffre moyen conduit-il ici à des interprétations distinctes ?","explanation":"B distingue moyenne et répartition des notes. A et D infèrent la dispersion d'un résumé insuffisant, C qualifie la moyenne d'erronée alors qu'elle peut être exacte."},{"number":31,"points":26,"correct":"B","options":["Les pannes apparues plus tard devraient invalider les mesures de performance réalisées sous l'assistance du concepteur.","Un fonctionnement ponctuel assisté ne permet pas, seul, d'établir la fiabilité dans les conditions ordinaires, sur plusieurs jours.","Le maintien d'une assistance technique pendant le pilote permettrait de prédire plus sûrement son usage quotidien sans suivi.","La démonstration ne doit être prise en compte que si les conditions du site pilote sont strictement identiques."],"passage":"Un prototype fonctionne en démonstration sous la surveillance de ses concepteurs. Pour apprécier son usage futur, il faut aussi observer l'entretien, les erreurs ordinaires et les contraintes des lieux d'installation. La réussite ponctuelle ne constitue pas encore un bilan d'utilisation. Le fabricant souhaite que les futurs utilisateurs puissent apprécier l'écart entre une possibilité technique montrée une fois et un service fiable dans leurs propres conditions de travail. En laboratoire, le concepteur corrige aussitôt chaque blocage. Sur le site pilote, les utilisateurs ne disposent pas de cette présence permanente et signalent des pannes après plusieurs jours. Une démonstration courte ne révèle pas les mêmes problèmes.","question":"Quelle limite d'évaluation illustre la différence entre la démonstration et le site pilote ?","explanation":"B constate qu'un essai ponctuel accompagné ne mesure pas la fiabilité durable. A invalide abusivement la performance instantanée, C continue de masquer les problèmes de maintenance, D impose des conditions identiques plutôt qu'une évaluation contextualisée."},{"number":32,"points":26,"correct":"B","options":["Les fiches de provenance suffisent à analyser de nouveaux phénomènes sans reprendre de mesures sur les spécimens.","Elles relient des observations nouvelles au contexte des prélèvements anciens, indispensable pour interpréter les nouvelles mesures.","La localisation initiale assure la validité d'hypothèses futures même lorsque leurs méthodes ont profondément changé.","Les informations anciennes restent plus fiables que les nouvelles analyses lorsqu'un instrument différent est employé."],"passage":"Les collections anciennes d'un musée peuvent servir à de nouvelles recherches. Des méthodes récentes révèlent des informations que les premiers collecteurs ne pouvaient pas observer. La conservation maintient ainsi des possibilités de questions futures, pas seulement le souvenir d'un savoir déjà établi. Les chercheurs peuvent revenir sur des spécimens avec des questions nouvelles. La valeur d'une collection dépend alors aussi des descriptions et des conditions de conservation qui permettent de comprendre ce qui a été recueilli à l'époque. Des échantillons anciens ont été conservés avec leurs lieux de prélèvement. Une nouvelle technique permet de mesurer aujourd'hui une propriété inconnue à l'époque; sans ces informations sur l'origine des échantillons, l'analyse aurait moins de portée.","question":"Pourquoi les informations de collecte participent-elles à la valeur scientifique des spécimens ?","explanation":"B montre que le contexte d'origine donne un sens aux mesures réalisées plus tard. A/C font des métadonnées une preuve suffisante, D les oppose aux méthodes récentes au lieu de les associer."},{"number":33,"points":26,"correct":"D","options":["La plage ajoutée évite de comparer les catégories, car le graphique décrit désormais une variation possible plutôt qu'une valeur.","La représentation d'une marge d'erreur réduit directement l'incertitude des mesures sur lesquelles le graphique repose.","Une seconde couche graphique rend les catégories plus comparables parce qu'elles disposent de davantage d'indicateurs visibles.","Elle rend visible l'incertitude susceptible de modifier la comparaison de deux estimations apparemment bien ordonnées."],"passage":"Une représentation graphique peut simplifier un ensemble complexe sans le trahir. Le risque apparaît lorsqu'elle efface une limite essentielle, par exemple une incertitude sur une estimation. La clarté ne consiste donc pas toujours à retirer des informations, mais à rendre visibles celles qui changent l'interprétation. Le médiateur présente les choix de représentation et invite les lecteurs à comparer deux versions. Dans une première version, l'estimation est représentée par une barre unique; dans la seconde, une plage d'incertitude est ajoutée. Le public comprend alors que deux catégories présentées dans un ordre précis pourraient en réalité être très proches.","question":"En quoi la seconde représentation est-elle plus fidèle malgré un élément graphique supplémentaire ?","explanation":"D rend visible l'incertitude pouvant modifier l'interprétation du classement. A évite à tort la comparaison, B confond représentation et réduction de l'erreur, C attribue la justesse au nombre d'éléments."},{"number":34,"points":26,"correct":"B","options":["L'observation peut retarder la mise au point technique de prototypes qui respectent déjà parfaitement le cahier des charges.","Qu'une solution ingénieuse réponde à un problème mal défini avec les usagers, avant tout choix de prototype.","La consultation aide à améliorer les prototypes, mais ne remet pas en cause la définition initiale du problème.","Il serait préférable de tester les solutions puis de reformuler le besoin, afin de préserver l'inventivité initiale."],"passage":"Un programme encourage les jeunes à inventer rapidement une solution. Les animateurs ajoutent ensuite une étape d'observation du problème avec les utilisateurs. Une réponse ingénieuse peut être mal orientée si la difficulté initiale a été définie sans ceux qui la rencontrent. Le centre souhaite préserver l'imagination des participants tout en l'orientant vers une difficulté qu'ils ont suffisamment comprise pour proposer une réponse réellement pertinente. Deux prototypes répondent parfaitement à la consigne écrite, mais les personnes censées s'en servir expliquent qu'elles rencontrent un problème différent. Les animateurs font reformuler le besoin avant de choisir lequel développer.","question":"Quel risque l'étape d'observation vise-t-elle à réduire ?","explanation":"B évite de développer une réponse technique à un problème mal défini avec les utilisateurs. A se concentre sur le délai du développement; C conserve à tort le cadrage écrit sans le réviser; D reporte l'observation jusqu'après la réalisation du prototype."},{"number":35,"points":26,"correct":"A","options":["Elle rend visibles les conclusions révisées à partir de preuves nouvelles, ainsi que les observations contradictoires.","Elle démontre que les observations initiales étaient suffisantes, mais avaient été présentées dans une forme trop prudente.","Elle prouve que la première hypothèse reposait uniquement sur une erreur de mesure identifiable après publication.","Elle conserve le résultat initial comme référence, puis présente les données contraires comme une exception secondaire."],"passage":"Une publication scientifique accepte qu'une hypothèse soit corrigée à la lumière de nouveaux résultats. Ce changement n'est pas automatiquement une preuve d'incompétence initiale. Il peut manifester une démarche qui accepte de distinguer ce qui était plausible de ce que les observations permettent désormais d'affirmer. Ils souhaitent que le lecteur puisse suivre le raisonnement, plutôt que prendre la modification comme une simple contradiction sans explication. Une équipe avait défendu une explication raisonnable avec les mesures disponibles. Une nouvelle série plus précise la contredit; les auteurs publient ce qui change et distinguent l'ancienne incertitude de la conclusion désormais mieux étayée.","question":"Pourquoi la correction de l'hypothèse peut-elle renforcer la confiance dans la démarche ?","explanation":"A correspond à une révision motivée par des mesures nouvelles et expliquée au lecteur. B inverse l'apport des nouvelles données; C attribue l'hypothèse initiale à une erreur non démontrée; D minimise les preuves contradictoires."},{"number":36,"points":33,"correct":"D","options":["Financer les projets dont les méthodes sont solides sans demander de présenter leur progression durant les premières années.","Comparer seulement le potentiel d'application rapide des résultats, même lorsque les méthodes sont exploratoires.","Exiger une prévision des usages futurs, mais accepter un calendrier plus long pour les travaux fondamentaux.","Suivre les méthodes et résultats sans exiger d'application commerciale immédiatement prévisible, au cours du projet exploratoire."],"passage":"Une fondation souhaite ne financer que des recherches dont l'application serait immédiatement prévisible. Des chercheurs rappellent que certaines méthodes utiles aujourd'hui proviennent de travaux d'abord motivés par des questions fondamentales. Exiger d'avance un bénéfice précis peut écarter des explorations dont l'intérêt se révèle autrement ou plus tard. Les responsables de la fondation craignent de financer des travaux dont ils ne pourraient pas annoncer rapidement l'utilité au public. Les chercheurs proposent donc des comptes rendus qui rendent visible la progression des questions et des méthodes. Ils ne demandent pas de renoncer à tout bilan. Ils veulent seulement éviter qu'un calendrier trop court et une définition unique du bénéfice empêchent d'explorer des pistes importantes. La discussion porte ainsi sur les formes de responsabilité d'un projet, et sur la manière d'expliquer un travail dont les effets ne peuvent pas toujours être prévus avec précision au moment de son lancement. Une proposition de recherche fondamentale ne promet pas d'application dans les deux ans mais présente des méthodes reproductibles et des jalons mesurables. Le comité doit décider si cette forme de suivi peut satisfaire son exigence de responsabilité.","question":"Quelle solution correspond au compromis proposé par les chercheurs ?","explanation":"D retient des comptes rendus sur méthodes et questions sans exiger une application commerciale prévisible. A abandonne le suivi; B/C réintroduisent un critère d'usage prédéterminé au lieu d'évaluer la progression."},{"number":37,"points":33,"correct":"D","options":["Elle permet de prédire le prochain épisode en utilisant la zone commune aux deux hypothèses de pluie.","Elle indique que la route doit être fermée sans délibération dès lors que les deux cartes montrent un risque.","Elle montre que l'exposition de l'axe reste constante, mais ne dit rien de la vulnérabilité à protéger.","Elle identifie une vulnérabilité présente sous plusieurs hypothèses, sans transformer les cartes en certitudes, dans la décision locale."],"passage":"Une simulation aide une commune à anticiper les crues. Ses cartes dépendent d'hypothèses sur la pluie et l'état des sols. Les responsables les utilisent pour comparer des scénarios, sans les présenter comme une photographie certaine de l'avenir. La force de l'outil tient à l'explicitation des possibles, non à la disparition de l'incertitude. La commune publiera les hypothèses principales et présentera plusieurs situations aux habitants. Certaines cartes permettront d'examiner un épisode fréquent, d'autres un événement plus rare mais plus grave. Les responsables devront choisir des aménagements qui restent utiles malgré cette diversité. Ils souhaitent que l'outil aide à comprendre leurs décisions, sans lui attribuer la responsabilité de les prendre seul. Les personnes concernées pourront ainsi discuter des priorités et des limites du dispositif. Deux cartes reposent sur des pluies de fréquences différentes. La zone inondée varie fortement, mais une route figure dans les deux périmètres. Les élus envisagent de sécuriser d'abord cet axe sans affirmer qu'une carte prédit le prochain épisode.","question":"En quoi la comparaison de scénarios aide-t-elle la décision sur la route ?","explanation":"D tire des scénarios une vulnérabilité commune, sans confondre hypothèse et prévision. A prétend dater l'épisode; B retire aux élus le choix d'aménagement; C ignore la vulnérabilité précisément repérée."},{"number":38,"points":33,"correct":"D","options":["Il établit qu'une omission volontaire des auteurs initiaux a créé la différence entre les deux laboratoires.","Il rend la conclusion initiale inutile puisqu'une modification de préparation rapproche les résultats obtenus.","Il prouve que la comparaison entre laboratoires n'a d'intérêt que lorsque tous les instruments sont identiques.","Il révèle une condition expérimentale influente et précise quand le résultat publié peut être reproduit."],"passage":"Une équipe cherche à reproduire un résultat publié et obtient un écart. Avant d'accuser les premiers auteurs, elle examine les instruments, les matériaux et les conditions de l'essai. Un désaccord expérimental devient une source d'information lorsqu'on recherche ce qui le produit, plutôt que de le réduire immédiatement à une faute. Les deux laboratoires échangent leurs observations et préparent de nouveaux essais. Ils découvrent parfois qu'un détail jugé secondaire dans le premier compte rendu modifie le résultat. Cette découverte peut enrichir la compréhension du phénomène, même si elle complique l'annonce initiale. Les chercheurs souhaitent rendre ces étapes visibles pour éviter que toute différence soit interprétée comme un conflit personnel. La publication des méthodes devient alors aussi importante que celle de la conclusion. D'autres équipes pourront examiner les mêmes éléments, essayer des conditions différentes et préciser progressivement la portée de ce qui a été observé. Le groupe découvre que l'échantillon avait été séché plus longtemps dans le second laboratoire. Lorsqu'il harmonise ce détail, les résultats se rapprochent, sans rendre inutile la publication de l'écart initial.","question":"Quelle valeur scientifique conserve l'écart initial une fois le détail identifié ?","explanation":"D montre que l'écart révèle un facteur de préparation influent et précise les conditions de reproductibilité. A suppose une intention malhonnête; B efface à tort la découverte; C exige une identité instrumentale non soutenue."},{"number":39,"points":33,"correct":"A","options":["Maintenir une série commune aux sites et distinguer les mesures exploratoires sur l'exposition locale, sans mélanger les résultats lors des comparaisons.","Mesurer les sites selon les horaires jugés les plus représentatifs par chaque quartier, puis corriger les différences après la collecte.","Remplacer la série normalisée par les relevés au niveau des poussettes, puisque le pic découvert à l'arrêt confirme leur priorité scientifique.","Les mesures supplémentaires deviennent directement comparables à la série principale lorsqu'elles sont relevées au même arrêt."],"passage":"Des citoyens participent à une enquête sur la qualité de l'air. Les scientifiques les associent au choix des lieux, mais conservent un protocole commun de mesure. La participation n'exige pas l'abandon de la rigueur ; elle peut enrichir les questions posées tout en maintenant des conditions qui rendent les résultats comparables. Les habitants connaissent des endroits où les personnes attendent longtemps et des horaires où la circulation change. Ils apportent ces repères lors de la préparation des relevés. Les spécialistes expliquent ensuite les règles de placement et les vérifications nécessaires pour éviter des comparaisons trompeuses. Le groupe discutera les résultats ensemble, avec les circonstances de chaque mesure. Les participants ne deviennent pas interchangeables, mais leurs connaissances se complètent. Le projet souhaite ainsi produire des informations plus utiles au territoire, tout en permettant au public de comprendre comment un résultat est construit et quelles questions il laisse encore ouvertes. Les riverains signalent un arrêt d'autobus très fréquenté au moment où les voitures se concentrent. Les scientifiques retiennent le lieu, mais imposent la même hauteur de capteur et les mêmes périodes de mesure que pour les autres sites. Après une première campagne, le groupe découvre un pic de pollution à l'arrêt proposé par les riverains. Une association souhaite ajouter un capteur au niveau des poussettes et mesurer uniquement les heures de sortie d'école, alors que le protocole initial impose une hauteur commune et des créneaux identiques dans tous les lieux comparés. Les scientifiques proposent de conserver la série standardisée pour les comparaisons entre sites et d'effectuer, en complément clairement identifié, des relevés exploratoires à la hauteur suggérée. Ces relevés supplémentaires pourraient éclairer l'exposition des enfants, sans être directement mêlés à la série principale. Lors d'un essai, les deux hauteurs donnent effectivement des valeurs différentes au même arrêt. Le rapport précise donc à quelle méthode appartient chaque résultat et demande de nouveaux relevés avant de conclure sur la cause de l'écart. Les habitants participent au choix des questions complémentaires, mais les règles de la série commune ne changent pas au gré des sites.","question":"Quelle organisation des relevés permet de répondre à une question locale sans invalider la comparaison principale ?","explanation":"A conserve une série standardisée entre sites et sépare les mesures exploratoires réalisées à d'autres hauteurs. B change les créneaux selon le quartier; C supprime la série commune; D confond le même lieu de mesure avec une méthode directement comparable."}]}$bank_9$::jsonb),
('tcf-reading-10','tcf-reading-2026-11-close-reading-v4',$bank_10${"id":"tcf-reading-10","title":"TCF Reading · Test 10","seconds":3600,"version":"tcf-reading-2026-11-close-reading-v4","maxPoints":699,"questions":[{"number":1,"points":3,"correct":"B","options":["Rencontrer tous les enseignants","Travailler dans la salle","Emprunter des livres","Inscrire une classe"],"passage":"La salle d'étude ouvre désormais le dimanche matin. Le prêt de documents reste fermé ce jour-là.\n\nLe personnel pourra orienter les lecteurs vers les rayons accessibles. Merci de respecter les espaces réservés au travail silencieux.","question":"Quel service est disponible dimanche ?","explanation":"Le passage indique : « La salle d'étude ouvre désormais le dimanche matin. Le prêt de documents reste fermé ce jour-là. » Cela justifie la réponse : Travailler dans la salle."},{"number":2,"points":3,"correct":"B","options":["Une personne déjà experte","Une personne débutante","Uniquement un diplômé","Un professeur seulement"],"passage":"Le cours d'initiation commence mercredi. Aucun niveau préalable n'est demandé ; le matériel sera prêté.\n\nUne première rencontre permettra de présenter les objectifs et l'organisation. Les candidats peuvent poser leurs questions avant de confirmer.","question":"Qui peut s'inscrire ?","explanation":"Le passage indique : « Le cours d'initiation commence mercredi. Aucun niveau préalable n'est demandé ; le matériel sera prêté. » Cela justifie la réponse : Une personne débutante."},{"number":3,"points":3,"correct":"C","options":["Dans une autre école","Uniquement par courrier","Au secrétariat mardi","À la bibliothèque dimanche"],"passage":"Les copies seront remises lundi en classe. Les élèves absents pourront les récupérer au secrétariat mardi.\n\nLe secrétariat demandera simplement le nom de l'élève et sa classe. Les documents ne seront pas laissés dans un lieu ouvert à tous.","question":"Où un élève absent pourra-t-il récupérer sa copie ?","explanation":"Le passage indique : « Les copies seront remises lundi en classe. Les élèves absents pourront les récupérer au secrétariat mardi. » Cela justifie la réponse : Au secrétariat mardi."},{"number":4,"points":3,"correct":"D","options":["Un cours obligatoire pour les parents","Un examen pour les enfants","Une sortie scolaire payante","Une garde pendant la réunion"],"passage":"La réunion des parents se déroulera sans les élèves. Un accueil gratuit des enfants est organisé dans la salle voisine.\n\nLe service est proposé pendant toute la durée des échanges. Merci de signaler le nombre d'enfants au moment de confirmer votre venue.","question":"Quel accompagnement est proposé ?","explanation":"Le passage indique : « La réunion des parents se déroulera sans les élèves. Un accueil gratuit des enfants est organisé dans la salle voisine. » Cela justifie la réponse : Une garde pendant la réunion."},{"number":5,"points":9,"correct":"C","options":["Un changement définitif de professeur","Une dispense de tous les cours","Les exercices qu'elle manquera","Un diplôme sans examen"],"passage":"Je suis inscrit au cours du soir, mais je travaillerai deux mercredis ce mois-ci. Pourrais-tu me transmettre les exercices de ces séances ?\n\nJe veux éviter de prendre du retard avant le prochain chapitre. Si certains points demandent une explication, je contacterai ensuite le formateur pour savoir comment les reprendre.","question":"Que demande cette personne ?","explanation":"Le passage indique : « Je suis inscrit au cours du soir, mais je travaillerai deux mercredis ce mois-ci. Pourrais-tu me transmettre les exercices de ces séances ? » Cela justifie la réponse : Les exercices qu'elle manquera."},{"number":6,"points":9,"correct":"A","options":["Un nombre minimal de confirmations","La réussite à un concours","Une expérience professionnelle précise","L'achat immédiat d'un manuel"],"passage":"Votre inscription est reçue. Le groupe n'ouvrira que si six personnes confirment ; nous vous informerons avant tout paiement.\n\nLe centre vous indiquera aussi les autres créneaux possibles. Si le groupe n'ouvre pas, vous pourrez choisir une autre formule ou renoncer sans frais.","question":"Quelle condition détermine l'ouverture ?","explanation":"Le passage indique : « Votre inscription est reçue. Le groupe n'ouvrira que si six personnes confirment ; nous vous informerons avant tout paiement. » Cela justifie la réponse : Un nombre minimal de confirmations."},{"number":7,"points":9,"correct":"D","options":["Être vendu en classe","Décorer définitivement l'école","Remplacer l'inscription","Soutenir une prise de parole"],"passage":"Apporte un objet de ton choix pour la séance de langue. Il servira de point de départ à une courte présentation orale.\n\nVous pourrez expliquer pourquoi vous l'avez choisi et raconter un souvenir qui lui est associé. Aucun objet coûteux ou particulièrement original n'est nécessaire pour participer à cet exercice.","question":"À quoi servira l'objet ?","explanation":"Le passage indique : « Apporte un objet de ton choix pour la séance de langue. Il servira de point de départ à une courte présentation orale. » Cela justifie la réponse : Soutenir une prise de parole."},{"number":8,"points":9,"correct":"D","options":["Un cours de dessin artistique uniquement","Un changement de lieu de travail","Une préparation à tous les examens","Un apprentissage lié à une tâche précise"],"passage":"Je souhaite apprendre à lire les plans de mon atelier, pas préparer un examen général. Peux-tu m'indiquer le module correspondant ?\n\nJ'utilise déjà ces documents au quotidien, mais certains symboles restent difficiles à interpréter.","question":"Quel besoin est exprimé ?","explanation":"Le passage indique : « Je souhaite apprendre à lire les plans de mon atelier, pas préparer un examen général. Peux-tu m'indiquer le module correspondant ? » Cela justifie la réponse : Un apprentissage lié à une tâche précise."},{"number":9,"points":9,"correct":"B","options":["Écarter les débutants","Partager une méthode sans l'imposer","Défendre une solution obligatoire","Comparer les notes publiquement"],"passage":"La bibliothèque organise un échange de méthodes de révision. Chaque participant peut présenter une pratique qui l'aide, sans prétendre qu'elle convient à tous.\n\nL'animateur aidera à comparer les pratiques et les situations dans lesquelles elles fonctionnent.","question":"Quelle attitude est attendue ?","explanation":"Le passage indique : « La bibliothèque organise un échange de méthodes de révision. Chaque participant peut présenter une pratique qui l'aide, sans prétendre qu'elle convient à tous. » Cela justifie la réponse : Partager une méthode sans l'imposer."},{"number":10,"points":9,"correct":"A","options":["En autonomie avec une aide possible","Sans aucun travail prévu","Avec un examen permanent","Uniquement en présence du directeur"],"passage":"Le stage d'été comprend des matinées encadrées et des après-midi de travail autonome. Un tuteur reste joignable pendant ces périodes.\n\nLes participants auront quelques exercices à terminer et pourront organiser leur temps. Une rencontre courte permettra de vérifier les difficultés avant de poursuivre la suite du programme.","question":"Comment sont organisés les après-midi ?","explanation":"Le passage indique : « Le stage d'été comprend des matinées encadrées et des après-midi de travail autonome. Un tuteur reste joignable pendant ces périodes. » Cela justifie la réponse : En autonomie avec une aide possible."},{"number":11,"points":15,"correct":"A","options":["Multiplier les moyens d'accès à la consigne","Imposer une seule méthode","Réserver l'audio aux enseignants","Supprimer la lecture pour tous"],"passage":"Une école propose une version audio des consignes. Le texte écrit demeure disponible ; les élèves peuvent choisir le support qui les aide.\n\nLes supports sont préparés avec le même contenu pour que personne ne reçoive une consigne différente par erreur. Les élèves peuvent réécouter un passage ou revenir au texte lorsqu'un mot leur échappe. L'équipe souhaite distinguer la compréhension de la tâche et les difficultés d'accès à son énoncé. Les enseignants observeront les usages avant de décider quels documents adapter ensuite. Ils ne présentent pas le choix du support comme une dispense d'apprendre à lire, mais comme une aide pour participer aux activités prévues.","question":"Quel principe est retenu ?","explanation":"Le passage indique : « Une école propose une version audio des consignes. Le texte écrit demeure disponible ; les élèves peuvent choisir le support qui les aide. » Cela justifie la réponse : Multiplier les moyens d'accès à la consigne."},{"number":12,"points":15,"correct":"C","options":["Éviter toute interaction","Supprimer les activités libres","Favoriser la participation de chacun","Classer définitivement les participants"],"passage":"Un atelier de conversation accueille des adultes de niveaux différents. Les activités alternent échanges libres et petits groupes pour que chacun puisse prendre la parole.\n\nLes personnes peuvent commencer par des échanges courts puis rejoindre une discussion plus longue. Les animateurs proposent des thèmes proches du quotidien et demandent aux habitués de laisser un temps de réponse. Le centre veut éviter qu'un niveau élevé chez quelques participants rende les autres invisibles.","question":"Pourquoi varier les groupes ?","explanation":"Le passage indique : « Un atelier de conversation accueille des adultes de niveaux différents. Les activités alternent échanges libres et petits groupes pour que chacun puisse prendre la parole. » Cela justifie la réponse : Favoriser la participation de chacun."},{"number":13,"points":15,"correct":"A","options":["Identifier le statut des informations","Écrire sans vérifier","Éliminer toutes les questions","Publier uniquement des certitudes personnelles"],"passage":"Des élèves rédigent un journal scientifique. Avant publication, ils doivent distinguer les faits vérifiés des hypothèses qu'ils souhaitent tester.\n\nLes groupes doivent indiquer d'où viennent leurs informations et conserver les documents consultés. Un enseignant les aide à voir quand une formulation affirme davantage que ce que la source permet. Les textes seront relus avant d'être montrés aux autres classes. Le projet souhaite donner une expérience concrète de publication, avec ses responsabilités. Les élèves pourront poser de nouvelles questions sans les présenter immédiatement comme des découvertes établies. Ils apprendront aussi à expliquer une incertitude plutôt qu'à la cacher pour rendre leur article plus impressionnant.","question":"Quel apprentissage est travaillé ?","explanation":"Le passage indique : « Des élèves rédigent un journal scientifique. Avant publication, ils doivent distinguer les faits vérifiés des hypothèses qu'ils souhaitent tester. » Cela justifie la réponse : Identifier le statut des informations."},{"number":14,"points":15,"correct":"C","options":["Les participants choisissent leur diplôme","Les examens sont tirés au sort","Les acquis initiaux sont pris en compte","Le tarif dépend de la taille des classes"],"passage":"Une formation professionnelle reconnaît certains acquis après entretien et exercice. Le parcours peut donc être plus court pour une personne déjà expérimentée.\n\nLes candidats apportent des exemples de tâches réalisées et décrivent les responsabilités qu'ils avaient réellement. L'exercice permet de vérifier certains points sans se fier uniquement au titre d'un ancien poste. Cette reconnaissance ne garantit pas une validation automatique : elle sert à rendre le parcours plus pertinent. Les participants savent ainsi pourquoi certaines séances leur sont proposées et pourquoi d'autres ne doivent pas nécessairement être suivies une seconde fois.","question":"Pourquoi la durée peut-elle varier ?","explanation":"Le passage indique : « Une formation professionnelle reconnaît certains acquis après entretien et exercice. Le parcours peut donc être plus court pour une personne déjà expérimentée. » Cela justifie la réponse : Les acquis initiaux sont pris en compte."},{"number":15,"points":15,"correct":"C","options":["Distribuer des notes secrètes","Éviter toute correction","Apprendre à partir des erreurs","Remplacer définitivement l'évaluation"],"passage":"Un enseignant autorise un premier essai non noté. Les élèves reçoivent un retour puis reprennent leur travail avant l'évaluation.\n\nLe retour porte sur des éléments précis du raisonnement et sur les moyens de progresser. Les élèves peuvent poser une question avant de reprendre le document. L'enseignant souhaite que la note finale ne soit pas la première information reçue sur la qualité de leur démarche. Il prévoit aussi un temps pour comparer les deux versions et identifier les changements utiles. Ce travail n'efface pas les exigences de l'évaluation ; il rend plus visible ce qui peut être appris entre une tentative initiale et une production plus aboutie.","question":"À quoi sert le premier essai ?","explanation":"Le passage indique : « Un enseignant autorise un premier essai non noté. Les élèves reçoivent un retour puis reprennent leur travail avant l'évaluation. » Cela justifie la réponse : Apprendre à partir des erreurs."},{"number":16,"points":15,"correct":"D","options":["Recopier une publicité sans commentaire","Évaluer le salaire des visiteurs","Donner uniquement une impression avant la visite","Confronter une représentation à l'expérience"],"passage":"La classe visite une entreprise après avoir préparé des questions. Le compte rendu devra comparer les attentes initiales et les observations réelles.\n\nCertains découvrent des tâches peu visibles pendant une simple présentation du métier. Les responsables de l'entreprise répondent aux questions, mais ne corrigent pas toutes les impressions à leur place. L'école souhaite que les jeunes apprennent à formuler un constat et à l'appuyer sur une situation concrète, plutôt qu'à reproduire uniquement les éléments les plus valorisants d'une brochure de recrutement ou d'une visite préparée pour eux.","question":"Quelle démarche est demandée ?","explanation":"Le passage indique : « La classe visite une entreprise après avoir préparé des questions. Le compte rendu devra comparer les attentes initiales et les observations réelles. » Cela justifie la réponse : Confronter une représentation à l'expérience."},{"number":17,"points":15,"correct":"A","options":["Une barrière matérielle à la formation","Le manque de places de parking","Le nombre de devoirs","La durée du trimestre"],"passage":"Un centre prête des calculatrices pour éviter que l'achat soit un obstacle à l'inscription. Les appareils doivent être rendus après le cours.\n\nLes étudiants peuvent poser des questions sans supposer qu'ils connaissent déjà le modèle. La formation ne veut pas évaluer une différence d'équipement familial à la place de la compétence travaillée. Les responsables suivront les demandes de prêt afin de prévoir un stock suffisant. Ils souhaitent que les personnes découvrent ce droit assez tôt pour ne pas abandonner une inscription simplement parce qu'elles pensent devoir acheter immédiatement du matériel supplémentaire.","question":"Quel problème cherche-t-on à réduire ?","explanation":"Le passage indique : « Un centre prête des calculatrices pour éviter que l'achat soit un obstacle à l'inscription. Les appareils doivent être rendus après le cours. » Cela justifie la réponse : Une barrière matérielle à la formation."},{"number":18,"points":15,"correct":"B","options":["La suppression de la cour","Différentes façons de vivre la pause","Une obligation de rester en classe","Un examen pendant la récréation"],"passage":"Une école aménage un espace calme accessible pendant les pauses. Il complète la cour active sans imposer le silence à tous les élèves.\n\nLes élèves ont participé au choix des sièges et des règles d'usage. Certaines personnes y lisent, d'autres préfèrent simplement s'asseoir quelques minutes. L'établissement souhaite reconnaître des besoins différents pendant le même temps de pause. Le bilan portera sur la manière dont les espaces se complètent, plutôt que sur une compétition entre ceux qui choisissent de jouer dehors et ceux qui recherchent un environnement plus calme.","question":"Quel choix est offert ?","explanation":"Le passage indique : « Une école aménage un espace calme accessible pendant les pauses. Il complète la cour active sans imposer le silence à tous les élèves. » Cela justifie la réponse : Différentes façons de vivre la pause."},{"number":19,"points":15,"correct":"A","options":["Vérifier le contexte de l'image","Se fier uniquement à sa première impression","Ignorer la date de publication","Compter les couleurs"],"passage":"Un groupe apprend à identifier les sources d'une photographie. Les participants recherchent sa date et son contexte avant d'interpréter ce qu'elle semble montrer.\n\nLes animateurs montrent comment une même image peut circuler avec des commentaires différents. Les participants essaient ensuite la démarche sur des exemples préparés pour l'atelier. Ils ne cherchent pas à démontrer que toute photographie serait fausse, mais à comprendre ce qui permet de lui attribuer un sens précis.","question":"Quelle précaution est enseignée ?","explanation":"Le passage indique : « Un groupe apprend à identifier les sources d'une photographie. Les participants recherchent sa date et son contexte avant d'interpréter ce qu'elle semble montrer. » Cela justifie la réponse : Vérifier le contexte de l'image."},{"number":20,"points":21,"correct":"D","options":["Éviter tout travail personnel","Obtenir immédiatement tous les diplômes","Interdire une poursuite d'études","Commencer progressivement sans perdre ses acquis"],"passage":"Des adultes souhaitent reprendre des études, mais hésitent à suivre un long programme. Le centre propose un premier module court, dont les acquis pourront être conservés s'ils continuent. Le centre précise les étapes suivantes et les conditions de reprise dès le début. Les personnes peuvent ainsi décider si elles souhaitent poursuivre après avoir découvert le rythme et le travail demandé. L'objectif est de proposer une première expérience suffisamment complète pour être utile, sans transformer une hésitation initiale en échec. Les acquis seront décrits dans un document conservé par l'apprenant.","question":"Que permet ce dispositif ?","explanation":"Le passage indique : « Des adultes souhaitent reprendre des études, mais hésitent à suivre un long programme. Le centre propose un premier module court, dont les acquis pourront être conservés s'ils continuent. » Cela justifie la réponse : Commencer progressivement sans perdre ses acquis."},{"number":21,"points":21,"correct":"D","options":["Toutes les questions sont inutiles","Les élèves comprennent toujours les consignes","La répétition prouve nécessairement un refus d'apprendre","La clarté de l'enseignement doit aussi être examinée"],"passage":"Une équipe enseignante analyse les questions posées après le cours. Des demandes répétées sur une consigne peuvent indiquer un problème d'explication, pas seulement un manque d'attention des élèves. Les formateurs regroupent les difficultés récurrentes et comparent la façon dont les consignes ont été présentées. Ils peuvent alors modifier un exemple ou prévoir une explication supplémentaire. Elle permet simplement de ne pas attribuer automatiquement une difficulté collective à des défauts individuels, alors qu'une même formulation a peut-être laissé plusieurs personnes dans l'incertitude.","question":"Quelle interprétation est ajoutée ?","explanation":"Le passage indique : « Une équipe enseignante analyse les questions posées après le cours. Des demandes répétées sur une consigne peuvent indiquer un problème d'explication, pas seulement un manque d'attention des élèves. » Cela justifie la réponse : La clarté de l'enseignement doit aussi être examinée."},{"number":22,"points":21,"correct":"D","options":["Isolement et contrôle permanent","Absence d'horaires et absence de contact","Cours uniquement en présence","Autonomie et accompagnement"],"passage":"Un cours en ligne reste consultable longtemps, mais prévoit des rendez-vous réguliers avec un tuteur. Les concepteurs veulent associer souplesse d'accès et soutien dans la durée. Les échanges avec le tuteur servent à préparer les étapes suivantes et à discuter des obstacles rencontrés. Les participants n'ont pas tous le même emploi du temps ni le même équipement. Le programme prévoit donc plusieurs possibilités de rendez-vous, sans laisser chacun seul face à une liste de vidéos.","question":"Quels éléments sont combinés ?","explanation":"Le passage indique : « Un cours en ligne reste consultable longtemps, mais prévoit des rendez-vous réguliers avec un tuteur. Les concepteurs veulent associer souplesse d'accès et soutien dans la durée. » Cela justifie la réponse : Autonomie et accompagnement."},{"number":23,"points":21,"correct":"C","options":["Imposer une langue unique au domicile","Classer les familles selon leurs revenus","Reconnaître des pratiques linguistiques diverses","Organiser un examen pour les parents"],"passage":"Une école invite les familles à expliquer les langues utilisées à la maison. Le projet ne mesure pas une maîtrise parfaite ; il rend visibles des ressources souvent absentes des échanges scolaires. Les enfants peuvent apporter une chanson, expliquer une expression ou raconter un usage quotidien. Les enseignants ne demandent pas aux parents de représenter toute une langue ou tout un pays. Ils souhaitent donner une place à des expériences présentes dans la classe, sans transformer l'activité en concours.","question":"Quel objectif est poursuivi ?","explanation":"Le passage indique : « Une école invite les familles à expliquer les langues utilisées à la maison. Le projet ne mesure pas une maîtrise parfaite ; il rend visibles des ressources souvent absentes des échanges scolaires. » Cela justifie la réponse : Reconnaître des pratiques linguistiques diverses."},{"number":24,"points":21,"correct":"D","options":["Éviter toute mise en pratique","Commencer par un classement des participants","Apprendre toutes les commandes sans usage","Partir d'un besoin pour introduire les notions"],"passage":"Un atelier de programmation commence par un problème concret, puis introduit les commandes nécessaires. Les participants comprennent ainsi à quoi sert l'outil avant d'en mémoriser la syntaxe. Les premiers essais peuvent être faits sans écrire toutes les lignes à partir de zéro. Les participants pourront modifier l'exemple et observer le résultat. Le centre souhaite que les nouvelles commandes deviennent des moyens d'agir et de comprendre, plutôt que des mots mémorisés sans lien avec un objectif identifiable.","question":"Quelle progression pédagogique est choisie ?","explanation":"Le passage indique : « Un atelier de programmation commence par un problème concret, puis introduit les commandes nécessaires. Les participants comprennent ainsi à quoi sert l'outil avant d'en mémoriser la syntaxe. » Cela justifie la réponse : Partir d'un besoin pour introduire les notions."},{"number":25,"points":21,"correct":"B","options":["Le tuteur peut fournir une réponse après une première erreur, puis demander à l'élève d'en expliquer les étapes.","Le tuteur oriente le raisonnement et reconnaît les situations nécessitant l'aide du professeur, dans les cas difficiles.","Le tuteur peut organiser la progression des exercices si l'enseignant garde la responsabilité de l'évaluation finale.","Le tuteur peut présenter sa propre méthode puis demander au camarade de refaire l'exercice pour la vérifier."],"passage":"Une association propose un tutorat entre élèves. Les tuteurs apprennent à poser des questions plutôt qu'à fournir directement la réponse. Les élèves préparant une aide reçoivent quelques repères pour écouter et vérifier ce que leur camarade a déjà essayé. Ils doivent savoir quand demander l'intervention du professeur. Il donne à chacun un rôle précis et permet aussi de découvrir que comprendre un exercice et aider quelqu'un à le comprendre sont deux activités différentes. Un tuteur remarque une erreur de calcul, mais demande d'abord à son camarade quelle étape lui semble incertaine. Quand une notion n'est plus maîtrisée par aucun des deux, ils sollicitent l'enseignant.","question":"Quelle frontière distingue le tutorat décrit d'une substitution à l'enseignant ?","explanation":"B décrit un tutorat qui questionne l'élève et sollicite le professeur lorsque la notion dépasse les deux camarades. A et D font du tuteur le fournisseur de la solution; C lui confie une organisation de la progression que le passage n'attribue pas à ce rôle."},{"number":26,"points":21,"correct":"A","options":["Parce que le transfert dépend des acquis et des occasions de les utiliser, dans le contexte professionnel.","Parce qu'une réaction favorable pendant le cours permet d'estimer les acquis mais non la fréquence de leur usage.","Parce que l'application des compétences se mesure surtout lorsque le nouveau poste ressemble au métier antérieur.","Parce que les participants ayant attendu plusieurs mois avant d'appliquer un savoir le perdent nécessairement."],"passage":"Le centre compare la satisfaction immédiate et l'utilisation réelle des compétences quelques mois plus tard. Un cours apprécié peut avoir peu d'effet si les participants n'ont pas l'occasion de pratiquer. Les anciens participants seront invités à décrire une situation où ils ont utilisé la formation et une autre où ils n'ont pas réussi à la mobiliser. Ils souhaitent distinguer un apprentissage réel, une appréciation favorable et les conditions nécessaires pour que ces acquis servent ensuite dans le travail ou dans les démarches prévues. Deux anciens élèves déclarent la même satisfaction. L'un utilise régulièrement la méthode apprise; l'autre travaille dans un service où il n'a pas accès au matériel nécessaire. Le bilan sépare acquis, occasion d'appliquer et ressenti.","question":"Pourquoi une satisfaction identique ne permet-elle pas de conclure au même effet de la formation ?","explanation":"A associe acquis et occasions réelles d'application. B confond satisfaction et compétence, C restreint sans preuve les situations de transfert, D suppose une perte automatique des connaissances."},{"number":27,"points":21,"correct":"C","options":["Sur la démarche adoptée par la majorité des camarades, puisque son utilisation répétée facilite la vérification.","Sur le nombre d'étapes requis, à condition que les deux procédures donnent des réponses correctes.","Sur les exigences du problème et les qualités respectives de chaque démarche correctement justifiée, dans chaque situation.","Sur la méthode présentée en premier par l'enseignant, dont les contraintes de calcul seraient normalement mieux connues."],"passage":"Un professeur montre deux solutions correctes à un problème. Les élèves doivent expliquer leurs différences plutôt que deviner laquelle l'enseignant préfère. Le professeur garde un rôle de vérification et ne présente pas toutes les propositions comme correctes par principe. Il veut que les élèves justifient leurs choix à partir du problème, au lieu de chercher seulement un indice sur la réponse qu'ils pensent attendue dans la classe. Une procédure est plus courte mais demande davantage de calcul mental; l'autre comporte davantage d'étapes et reste plus facile à vérifier. Les élèves doivent comparer ces propriétés en fonction du problème, sans qu'une seule méthode soit attendue.","question":"Sur quoi l'élève doit-il fonder le choix entre les deux solutions ?","explanation":"C demande de confronter les propriétés des deux méthodes au problème. A privilégie la popularité, B la brièveté sans contexte, D infère une préférence du professeur."},{"number":28,"points":21,"correct":"A","options":["Conserver des fonctions complémentaires et ajuster leur disponibilité en fonction des usages observés, entre examens et semaines ordinaires.","Conserver le même nombre de places de groupe, puis répondre aux demandes d'espace calme par un changement d'horaires.","Donner la priorité aux livres fragiles en limitant la durée des réservations de salles de travail collectif.","Accorder temporairement presque tout l'espace aux demandes de silence durant les examens, puis revenir au plan initial."],"passage":"Une université transforme une partie de sa bibliothèque en salles de groupe. Elle conserve des zones silencieuses après consultation des étudiants. Les étudiants ont expliqué à quels moments ils travaillent seuls, en groupe ou avec un document fragile. Elle souhaite éviter qu'un changement présenté comme moderne efface une fonction encore importante. Le bilan examinera la disponibilité réelle des espaces, notamment pendant les périodes où les demandes de travail individuel augmentent fortement. Pendant les examens, les salles de groupe sont pleines mais les demandes d'espaces silencieux doublent. La direction vérifie les besoins selon les périodes plutôt que d'évaluer l'aménagement sur une seule semaine.","question":"Quel principe devrait guider la répartition de l'espace de la bibliothèque ?","explanation":"A répartit les usages complémentaires selon la fréquentation constatée. B fige l'espace, C traite un autre usage comme solution globale, D fait presque disparaître les salles de groupe sans examen des besoins simultanés."},{"number":29,"points":21,"correct":"C","options":["Des absences répétées peuvent révéler une difficulté pédagogique malgré les bonnes notes obtenues aux évaluations.","Un stagiaire qui réussit les exercices pourrait compenser ses absences à l'aide des supports sans aide logistique.","Parce que les absences observées correspondent ici à des contraintes d'accès malgré des acquis suffisants.","Les difficultés de garde rendent les évaluations moins fiables comme preuve des acquis du stagiaire."],"passage":"Des participants abandonnent une formation malgré de bons résultats. Les entretiens révèlent des difficultés de garde et de transport. Le centre modifie ses aides plutôt que simplifier automatiquement les contenus. Les responsables ont contacté les personnes parties avant la fin pour comprendre leur expérience. Plusieurs souhaitaient continuer et savaient réaliser les exercices demandés. Le centre propose donc des solutions d'organisation et des relais locaux avant de revoir le niveau pédagogique. Un stagiaire réussit les évaluations mais manque trois cours faute de garde d'enfant. Le centre lui propose un soutien logistique plutôt qu'un cours simplifié; il vérifie ensuite si la présence reprend.","question":"Pourquoi le centre agit-il d'abord sur l'organisation de la formation ?","explanation":"C relie les absences à des obstacles de garde ou de transport malgré des acquis satisfaisants. A imagine une difficulté pédagogique non montrée; B suppose que les supports suffisent à lever les contraintes; D remet sans preuve en cause la validité des évaluations."},{"number":30,"points":26,"correct":"C","options":["Une procédure identique à appliquer à toute erreur afin de rendre les réponses plus homogènes.","La certitude de réussir à la tentative suivante, dès lors que l'élève identifie l'étape incorrecte.","Une compréhension exploitable de l'erreur et une possibilité d'ajuster la prochaine démarche, lors d'une reprise.","Une manière de valoriser toute réponse pour maintenir l'envie de poursuivre sans modifier la démarche."],"passage":"Le droit à l'erreur est souvent invoqué en formation. Il suppose pourtant un retour permettant de comprendre et de reprendre. Sans cet accompagnement, répéter qu'on peut se tromper laisse l'apprenant face à une difficulté inchangée. Le formateur peut montrer comment analyser une tentative et préparer le prochain essai. La personne dispose alors d'éléments pour agir, au lieu d'être simplement rassurée sans savoir ce qu'elle pourrait modifier concrètement. Le retour doit rester précis et utilisable pour la prochaine tentative. Deux apprenants commettent la même erreur. Le premier reçoit seulement « ce n'est pas grave »; le second examine son étape fautive et essaie une autre démarche. Seul le second possède une indication pour la prochaine tentative.","question":"Qu'apporte le retour détaillé que la seule permission de se tromper ne fournit pas ?","explanation":"C ajoute une analyse permettant de corriger le raisonnement. A uniformise des erreurs différentes, B promet la réussite, D néglige l'ajustement concret."},{"number":31,"points":26,"correct":"B","options":["Que le suivi des réponses soit jugé moins précis lorsque l'élève explore de nouvelles méthodes de résolution.","Qu'un parcours centré sur des erreurs passées réduise l'expérience de situations nouvelles et le transfert des acquis.","Que l'enseignant donne plus de poids aux erreurs passées qu'aux évaluations réalisées pendant les nouvelles tâches.","Que les exercices adaptés au niveau du moment retardent la vérification de compétences qui resteraient identiques."],"passage":"Un programme personnalise les exercices à partir des réponses précédentes. Les enseignants souhaitent garder une vue sur les choix du logiciel. Une adaptation automatique peut être utile tout en enfermant un élève dans des tâches trop semblables à celles qu'il a déjà réalisées. Les enseignants conservent donc des possibilités de changer la proposition ou d'introduire une tâche moins familière. Après plusieurs réponses faibles en géométrie, un élève reçoit presque exclusivement des exercices similaires. Il réussit ensuite mieux, mais n'a plus d'occasion d'appliquer les notions dans une situation nouvelle; le professeur introduit des tâches différentes.","question":"Quel risque la modification du parcours vise-t-elle à limiter ?","explanation":"B identifie une adaptation qui enferme l'élève dans des tâches similaires, limitant le transfert. A/C/D décrivent d'autres problèmes possibles mais pas le manque d'exposition à des contextes nouveaux observé."},{"number":32,"points":26,"correct":"B","options":["Parce que les élèves les plus avancés doivent rester responsables de toutes les étapes du projet commun.","Parce qu'un bon projet peut masquer une participation inégale des membres, même quand la production finale est satisfaisante.","Parce que les rôles attribués au début suffisent à établir les compétences que chacun a réellement acquises.","Parce que la rotation des rôles peut rendre la qualité du travail moins stable d'une séance à la suivante."],"passage":"Une école développe des projets collectifs. Pour éviter que seuls les élèves déjà à l'aise prennent les décisions, les rôles tournent et les méthodes sont discutées. Travailler ensemble ne suffit pas spontanément à répartir les occasions d'apprendre. Chaque élève pourra expliquer sa contribution et les difficultés rencontrées dans le rôle occupé. Cette attention évite de considérer qu'un résultat collectif réussi prouve automatiquement que tous les membres ont eu les mêmes occasions de travailler. Le groupe rend un projet réussi, mais son porte-parole a dirigé tous les échanges et les autres n'ont jamais présenté de décision. La rotation donne à chacun une occasion identifiable de mener, vérifier ou expliquer.","question":"Pourquoi un résultat collectif satisfaisant ne suffit-il pas à évaluer l'apprentissage des membres ?","explanation":"B désigne le risque que le bon résultat masque l'inégalité de participation et des occasions d'apprentissage. A préconise de concentrer les tâches, C confond attribution initiale et contribution réelle, D suppose une instabilité des résultats due aux rotations que le passage ne constate pas."},{"number":33,"points":26,"correct":"C","options":["Considérer qu'une expérience répétée suffit pour prouver la compétence sans examen complémentaire de sa réalisation.","Privilégier le récit oral pour les compétences que le candidat ne parvient pas à documenter à l'écrit.","Assimiler une difficulté à décrire une expérience à une absence de savoir-faire pratique, dans le dossier présenté.","Adapter les modalités de présentation d'un acquis revient à réduire les exigences techniques du référentiel."],"passage":"Un adulte utilise efficacement un outil au travail mais peine à l'expliquer dans un dossier de formation. Son accompagnateur distingue la compétence pratique et la capacité à la décrire. L'une ne prouve pas automatiquement l'autre. Des exemples concrets et une observation peuvent compléter le dossier. Le centre souhaite éviter qu'une difficulté de rédaction masque un savoir réel, tout en aidant la personne à présenter ses acquis de manière compréhensible pour un évaluateur extérieur. Une candidate démontre oralement une procédure qu'elle applique chaque jour mais peine à en produire une description écrite. Le centre ajoute une observation guidée et une aide à la rédaction avant de statuer sur les compétences.","question":"Quel biais l'accompagnement cherche-t-il à éviter ?","explanation":"C évite de confondre difficulté d'expression écrite et absence de savoir-faire. A supprimerait la vérification pratique; B remplacerait un biais par un autre; D assimile à tort aménagement et baisse des exigences."},{"number":34,"points":26,"correct":"D","options":["L'ordre de publication des résultats et le moment auquel les établissements ont fermé leurs inscriptions.","Les ressources consacrées aux épreuves peuvent expliquer les écarts, mais ne règlent pas les différences de dénominateur.","Le nombre d'étudiants présents aux examens pourrait suffire à comparer les résultats si les abandons sont publiés séparément.","Le périmètre des étudiants comptabilisés, notamment ceux partis avant l'examen, afin de comparer les établissements."],"passage":"Un établissement publie son taux de réussite. Il précise aussi les caractéristiques des étudiants accueillis et les parcours interrompus. Sans ces informations, comparer deux taux pourrait confondre l'effet de l'enseignement avec les conditions de recrutement ou de vie des étudiants. Les responsables souhaitent une comparaison utile, sans transformer un indicateur simple en verdict sur toutes les dimensions d'un établissement. Deux écoles publient 85 % de réussite. Dans la première, le calcul exclut les nombreux étudiants partis avant l'examen; la seconde suit l'ensemble des inscrits. La comparaison brute négligerait cette différence de périmètre.","question":"Quelle information est indispensable pour interpréter les taux annoncés ?","explanation":"D exige de comparer les étudiants inclus dans les deux taux, notamment les départs antérieurs à l'examen. A concerne le calendrier; B les moyens; C conserve une comparaison entre seuls présents qui ne règle pas la différence de périmètre annoncée."},{"number":35,"points":26,"correct":"B","options":["En donnant plus d'indices lorsque les exercices deviennent familiers pour maintenir la sécurité des réponses.","En diminuant progressivement et en réapparaissant de façon ciblée lorsque la difficulté l'exige, en situation nouvelle.","En conservant le même niveau d'aide pour rendre les performances comparables d'une séance à l'autre.","En retirant les aides après la première réussite, quitte à reprendre l'exercice si un problème nouveau apparaît."],"passage":"Un atelier vise l'autonomie. Les formateurs donnent progressivement moins d'indices, sans supprimer brutalement leur soutien. L'autonomie n'est pas supposée présente dès l'entrée : elle se construit dans une relation dont l'intensité évolue. Les apprenants sont invités à demander un appui lorsqu'une difficulté nouvelle apparaît. Le centre ne considère pas cette demande comme un échec de l'autonomie, mais comme une ressource possible pour continuer à progresser. La formatrice retire d'abord les exemples guidés, puis propose une situation moins familière. Si l'apprenant bloque, elle lui offre une question ciblée sans reprendre tout le raisonnement à sa place.","question":"Comment l'aide contribue-t-elle ici au développement de l'autonomie ?","explanation":"B décrit un étayage progressif et réajustable selon la difficulté. A augmente l'aide quand elle devrait diminuer; C la fige; D confond une première réussite et l'autonomie face à une situation nouvelle."},{"number":36,"points":33,"correct":"B","options":["Le nombre de tablettes distribuées et les compétences numériques déclarées, supposées directement comparables entre familles.","Le matériel distribué et les conditions réelles d'apprentissage à domicile, y compris l'accès aux ressources numériques.","La disponibilité d'un appareil à l'école et l'obligation de poursuivre toutes les tâches à domicile en ligne.","Le temps consacré aux devoirs et le niveau scolaire, considérés indépendamment de l'accès à la connexion."],"passage":"Une école distribue des tablettes à tous les élèves et constate des usages très différents. Certains disposent chez eux d'un espace calme et d'un adulte disponible ; d'autres partagent une connexion fragile. L'égalité d'équipement ne garantit pas l'égalité des conditions d'apprentissage. Certaines familles doivent attendre qu'un appareil soit libre pour terminer un devoir, tandis que d'autres peuvent reprendre les consignes à tout moment. L'école va donc proposer un accès encadré après les cours et des supports utilisables sans connexion permanente. Les enseignants examineront aussi la charge demandée à la maison. Le matériel distribué reste un progrès, mais ses effets dépendent des situations dans lesquelles il est utilisé. Le projet doit être évalué à partir de ces usages réels, pas seulement du nombre de tablettes remises lors d'une première journée de lancement. À équipement identique, un devoir vidéo se charge sans difficulté chez certains élèves, tandis que d'autres doivent attendre une connexion partagée. L'école ajoute une possibilité hors ligne plutôt que conclure à une égalité d'apprentissage.","question":"Quelle différence faut-il distinguer lorsqu'on évalue la distribution des tablettes ?","explanation":"B distingue l'égalité du matériel des conditions réelles de son usage, connexion et soutien. A/C assimilent équipement à apprentissage; D écarte précisément l'environnement matériel qui explique les différences."},{"number":37,"points":33,"correct":"A","options":["La flexibilité des règles de parcours et l'accès à l'accompagnement, en cohérence avec la promesse faite.","La durée totale du cursus, en maintenant les échéances communes pour préserver la comparabilité de l'évaluation.","La quantité d'exercices proposés en ligne, afin que les étudiants puissent apprendre seuls malgré les interruptions.","La difficulté des évaluations, adaptée aux rythmes individuels mais sans modifier la disponibilité des accompagnateurs."],"passage":"Une formation promet de respecter le rythme de chacun. Mais son calendrier final reste rigide, et les aides disparaissent après une courte période. Les participants qui ont besoin de plus de temps sont alors les premiers exclus. Une personnalisation annoncée doit être cohérente avec l'organisation qui encadre réellement les parcours. Les responsables avaient surtout décrit les possibilités offertes par les supports, sans regarder les délais ni la disponibilité des accompagnateurs. Les personnes intéressées pourront ainsi choisir en connaissant les limites du programme. Le centre souhaite conserver des objectifs communs sans prétendre qu'un outil flexible rend toutes les contraintes sans importance. Les résultats seront étudiés avec les abandons et les reprises, afin de vérifier si la nouvelle organisation aide effectivement ceux qui avaient du mal à suivre le rythme prévu. Une participante termine les exercices numériques à son rythme mais manque la date finale commune après une période de garde familiale. Les responsables envisagent des échéances de rattrapage et des aides prolongées.","question":"Que doit modifier le centre pour que la personnalisation soit autre chose qu'une propriété des supports ?","explanation":"A demande d'accorder délais de parcours et disponibilité d'aide avec la personnalisation annoncée. B/C/D changent durée, quantité ou niveau sans traiter ensemble les échéances rigides et le soutien limité."},{"number":38,"points":33,"correct":"B","options":["La capacité de suivre les étapes lorsque le chapitre et la formule pertinente sont indiqués à l'avance.","Le repérage des conditions dans lesquelles la méthode répond au problème posé, avant son exécution correcte.","La possibilité de reconnaître plusieurs formules d'un même chapitre avant de les appliquer successivement.","L'habitude de vérifier le résultat obtenu après avoir exécuté la méthode déjà désignée dans la consigne."],"passage":"Apprendre une méthode ne signifie pas toujours savoir quand l'utiliser. Des élèves réussissent un exercice familier, puis échouent lorsque le même problème apparaît dans une présentation différente. Le professeur multiplie les contextes et fait discuter les choix. La maîtrise implique aussi de reconnaître les situations auxquelles un savoir peut répondre. Les exercices proposés ensuite changent de présentation et mélangent plusieurs notions. Les élèves doivent expliquer pourquoi ils en choisissent une plutôt qu'une autre. Le professeur observe les hésitations, car elles peuvent révéler un repère mal compris malgré une procédure bien mémorisée. Il ne cherche pas à multiplier les pièges. Il veut rendre possible un passage des tâches familières à celles où il faut d'abord identifier le problème. Les retours aideront chacun à reconnaître des indices pertinents et à vérifier une démarche, plutôt qu'à reproduire automatiquement un geste appris dans un ordre toujours identique. Un élève applique une formule lorsque le chapitre est annoncé, mais choisit la mauvaise procédure lorsque plusieurs notions sont mélangées. Le professeur fait justifier les indices qui orientent vers une méthode.","question":"Quelle capacité manque à l'élève qui sait exécuter la formule dans un exercice familier ?","explanation":"B porte sur l'identification des indices qui rendent une méthode pertinente dans un contexte nouveau. A décrit la compétence déjà acquise; C reste à l'intérieur d'un chapitre désigné; D concerne le contrôle après sélection et non la sélection."},{"number":39,"points":33,"correct":"A","options":["L'expérience devient une ressource lorsqu'on peut expliciter ses conditions de validité et la réviser face à une contrainte nouvelle.","Une longue pratique antérieure garantit des méthodes plus sûres que l'application d'un critère appris seulement pendant la formation.","La correction d'un automatisme lors d'une seule mise en situation établit que le participant saura ensuite s'adapter dans tous les contextes.","L'analyse des méthodes antérieures devient secondaire dès lors que le formateur a expliqué le critère applicable aujourd'hui."],"passage":"Un centre valorise l'expérience de ses apprenants adultes. Il ne considère pourtant pas que cette expérience suffit à répondre à toute question. Les échanges mettent parfois en évidence des habitudes efficaces dans un contexte et inadaptées dans un autre. Reconnaître un parcours permet d'en faire une ressource d'analyse, sans le transformer en vérité intangible. Les apprenants apportent des exemples et discutent des conditions dans lesquelles leurs solutions ont fonctionné. Le formateur introduit d'autres situations pour faire apparaître les points communs et les différences. Certains participants découvrent qu'ils possèdent des ressources utiles sans avoir encore les mots pour les décrire. D'autres doivent modifier un automatisme longtemps efficace dans leur ancien contexte. Le cours ne demande donc ni d'oublier son parcours ni de s'y enfermer. Il propose de le travailler avec d'autres repères, afin de préparer des décisions plus adaptées aux situations nouvelles rencontrées pendant la formation ou ensuite. Un professionnel explique une pratique qui fonctionnait dans son ancien service; une nouvelle situation introduit une contrainte absente auparavant. Le groupe identifie ce qui reste transférable et ce qu'il faut modifier au lieu de rejeter ou d'appliquer sans examen l'expérience passée. Pour une évaluation, deux professionnels expérimentés résolvent un incident familier selon leur ancienne procédure. Dans le nouveau cadre, la même procédure impose désormais un délai de contrôle supplémentaire. L'un explique pourquoi son automatisme ancien doit être interrompu à cette étape; l'autre répète correctement le geste ancien, mais ne vérifie pas les nouvelles contraintes. Le formateur ne leur attribue pas des compétences générales différentes sur la seule base de cette observation. Il demande plutôt que chacun nomme ce qui reste pertinent, la condition nouvelle qui change le choix, puis un critère permettant de vérifier l'adaptation. Un troisième participant, moins expérimenté, réussit également en mobilisant ce critère après avoir écouté les deux raisonnements. Le centre précise qu'un bon parcours antérieur n'autorise pas à ignorer le contexte, et qu'une correction ponctuelle ne démontre pas, sans nouvel essai, une maîtrise transférable dans toute situation.","question":"Quelle conclusion pédagogique est la plus solidement appuyée par l'évaluation décrite ?","explanation":"A fait de l'expérience antérieure une ressource soumise à l'analyse des conditions nouvelles. B privilégie l'ancienneté même quand la procédure ne convient plus; C généralise à partir d'une seule correction; D marginalise à tort l'examen des pratiques passées."}]}$bank_10$::jsonb),
('tcf-reading-11','tcf-reading-2026-11-close-reading-v4',$bank_11${"id":"tcf-reading-11","title":"TCF Reading · Test 11","seconds":3600,"version":"tcf-reading-2026-11-close-reading-v4","maxPoints":699,"questions":[{"number":1,"points":3,"correct":"C","options":["Des meubles démontés","Des aliments ouverts","Des couvertures propres","Des vêtements mouillés"],"passage":"La collecte de couvertures se termine samedi. Déposez uniquement des articles propres et secs ; les vêtements seront collectés le mois prochain.\n\nLes articles non adaptés ne doivent pas être laissés devant le local.","question":"Que peut-on donner cette semaine ?","explanation":"Le passage indique : « La collecte de couvertures se termine samedi. Déposez uniquement des articles propres et secs ; les vêtements seront collectés le mois prochain. » Cela justifie la réponse : Des couvertures propres."},{"number":2,"points":3,"correct":"D","options":["Tous les matins","Le dimanche soir","Le lundi seulement","Le jeudi"],"passage":"La permanence d'entraide reçoit sans rendez-vous le jeudi. Les autres jours, un appel préalable est nécessaire.\n\nMerci de prévoir un temps d'attente pendant les périodes de forte fréquentation.","question":"Quand peut-on venir directement ?","explanation":"Le passage indique : « La permanence d'entraide reçoit sans rendez-vous le jeudi. Les autres jours, un appel préalable est nécessaire. » Cela justifie la réponse : Le jeudi."},{"number":3,"points":3,"correct":"D","options":["Les musiciens du soir uniquement","Tous les convives","Les clients du marché","Les bénévoles chargés de l'installation"],"passage":"Les bénévoles du repas partagé se retrouveront à neuf heures pour installer les tables. Le public arrivera à midi.\n\nLes personnes inscrites pour une autre mission garderont leur horaire habituel de présence.","question":"Qui est attendu à neuf heures ?","explanation":"Le passage indique : « Les bénévoles du repas partagé se retrouveront à neuf heures pour installer les tables. Le public arrivera à midi. » Cela justifie la réponse : Les bénévoles chargés de l'installation."},{"number":4,"points":3,"correct":"A","options":["La confirmation d'inscription","Un billet de spectacle","Un relevé bancaire","Un diplôme scolaire"],"passage":"La distribution de cahiers est ouverte aux familles inscrites. Apportez votre confirmation, imprimée ou sur téléphone.\n\nLe personnel retrouvera ensuite votre dossier sans demander une nouvelle inscription. Une famille rencontrant une difficulté peut contacter l'accueil avant le jour prévu.","question":"Quel document faut-il présenter ?","explanation":"Le passage indique : « La distribution de cahiers est ouverte aux familles inscrites. Apportez votre confirmation, imprimée ou sur téléphone. » Cela justifie la réponse : La confirmation d'inscription."},{"number":5,"points":9,"correct":"C","options":["Un service de transport privé","Une absence d'activité","Une tâche sans port de charges lourdes","Un changement de tous les horaires"],"passage":"Je peux aider à trier les dons samedi, mais pas porter les cartons lourds. Peux-tu me prévoir une tâche à table ?\n\nJe suis disponible toute la matinée et peux aussi aider à vérifier les étiquettes. Ainsi, l'équipe pourra répartir les autres tâches entre les bénévoles disponibles.","question":"Quelle adaptation est demandée ?","explanation":"Le passage indique : « Je peux aider à trier les dons samedi, mais pas porter les cartons lourds. Peux-tu me prévoir une tâche à table ? » Cela justifie la réponse : Une tâche sans port de charges lourdes."},{"number":6,"points":9,"correct":"B","options":["Uniquement un comédien professionnel","Une personne intéressée par la lecture partagée","Une personne refusant de lire à voix haute","Un vendeur de livres seulement"],"passage":"Notre association cherche des personnes pour lire des histoires. Il suffit d'aimer partager des textes ; aucune expérience de spectacle n'est exigée.\n\nUne séance d'accueil permettra de découvrir les livres et de préparer une première lecture.","question":"Quel profil convient ?","explanation":"Le passage indique : « Notre association cherche des personnes pour lire des histoires. Il suffit d'aimer partager des textes ; aucune expérience de spectacle n'est exigée. » Cela justifie la réponse : Une personne intéressée par la lecture partagée."},{"number":7,"points":9,"correct":"C","options":["Annuler toutes les inscriptions","Calculer le prix des repas","Organiser les équipes de deux","Modifier le lieu du festival"],"passage":"Merci de confirmer votre disponibilité avant mardi. Nous devons constituer les binômes d'accompagnement, pas simplement compter les inscrits.\n\nUne absence peut être signalée sans devoir fournir de détail personnel au groupe. Il faut surtout que le responsable puisse rechercher un remplaçant assez tôt.","question":"Pourquoi la confirmation est-elle importante ?","explanation":"Le passage indique : « Merci de confirmer votre disponibilité avant mardi. Nous devons constituer les binômes d'accompagnement, pas simplement compter les inscrits. » Cela justifie la réponse : Organiser les équipes de deux."},{"number":8,"points":9,"correct":"C","options":["Remplacer les dons par un impôt","Réserver tous les articles aux touristes","Soutenir le fonctionnement solidaire","Supprimer les tarifs adaptés"],"passage":"La boutique solidaire vend aussi au grand public. Ces achats contribuent à financer les tarifs adaptés proposés à certaines familles.\n\nLe prix annoncé au public correspond aussi au travail de tri, d'entretien et d'accueil nécessaire au fonctionnement du lieu.","question":"Quel rôle jouent les achats ordinaires ?","explanation":"Le passage indique : « La boutique solidaire vend aussi au grand public. Ces achats contribuent à financer les tarifs adaptés proposés à certaines familles. » Cela justifie la réponse : Soutenir le fonctionnement solidaire."},{"number":9,"points":9,"correct":"A","options":["Une disponibilité moins fréquente mais fiable","Une participation sans calendrier","Un arrêt de toute aide","Une présence quotidienne"],"passage":"Je préfère m'engager une fois par mois régulièrement plutôt que promettre chaque semaine et annuler souvent.\n\nNous pourrons revoir le calendrier si mes disponibilités changent, plutôt que laisser l'équipe découvrir une absence le jour même.","question":"Quelle forme d'engagement est choisie ?","explanation":"Le passage indique : « Je préfère m'engager une fois par mois régulièrement plutôt que promettre chaque semaine et annuler souvent. » Cela justifie la réponse : Une disponibilité moins fréquente mais fiable."},{"number":10,"points":9,"correct":"C","options":["Attribuer un diplôme professionnel","Présenter les dossiers personnels au public","Préparer l'entrée dans l'activité","Sélectionner les donateurs les plus riches"],"passage":"L'équipe propose une séance d'accueil avant la première mission. Les nouveaux bénévoles y découvriront les règles de confidentialité.\n\nLes volontaires pourront poser leurs questions avant de s'engager. Les responsables présenteront aussi les limites des tâches et les situations qui demandent de contacter une personne compétente.","question":"À quoi sert cette séance ?","explanation":"Le passage indique : « L'équipe propose une séance d'accueil avant la première mission. Les nouveaux bénévoles y découvriront les règles de confidentialité. » Cela justifie la réponse : Préparer l'entrée dans l'activité."},{"number":11,"points":15,"correct":"C","options":["Seuls les professionnels peuvent participer","Le revenu détermine le nombre d'heures","Une même durée a la même valeur","Les outils sont vendus aux voisins"],"passage":"Une association échange des services entre habitants. Une heure de jardinage donne droit à une heure d'aide, quelle que soit la valeur marchande habituelle du métier.\n\nLes participants indiquent les services qu'ils peuvent proposer et les moments où ils sont disponibles. Un coordinateur facilite les premières rencontres sans promettre une réponse immédiate à chaque demande. Les échanges sont enregistrés dans un carnet commun pour que chacun sache ce qu'il a donné et reçu. Le groupe souhaite reconnaître des compétences diverses, y compris des gestes ordinaires parfois peu valorisés.","question":"Quel principe régit l'échange ?","explanation":"Le passage indique : « Une association échange des services entre habitants. Une heure de jardinage donne droit à une heure d'aide, quelle que soit la valeur marchande habituelle du métier. » Cela justifie la réponse : Une même durée a la même valeur."},{"number":12,"points":15,"correct":"D","options":["Remplacer les décisions des bénéficiaires","Éviter toute explication","Confisquer les documents personnels","Renforcer la compréhension des démarches"],"passage":"Le centre social aide à remplir des formulaires, mais demande aux personnes de rester présentes. Les animateurs expliquent les démarches plutôt que décider à leur place.\n\nLes animateurs montrent où trouver une information et demandent aux personnes de vérifier ce qui les concerne. L'aide peut prendre plus de temps qu'une saisie rapide effectuée sans explication. Le centre considère cependant que cette présence permet aussi de préparer une prochaine démarche.","question":"Quel objectif accompagne l'aide immédiate ?","explanation":"Le passage indique : « Le centre social aide à remplir des formulaires, mais demande aux personnes de rester présentes. Les animateurs expliquent les démarches plutôt que décider à leur place. » Cela justifie la réponse : Renforcer la compréhension des démarches."},{"number":13,"points":15,"correct":"D","options":["Supprimer les rencontres","Attirer des visiteurs payants","Empêcher toute coordination interne","Préserver la confidentialité"],"passage":"Une maraude adapte son parcours aux besoins signalés. Les bénévoles ne publient pas les lieux de rencontre pour protéger les personnes accompagnées.\n\nLes personnes choisissent ce qu'elles souhaitent dire et peuvent refuser une rencontre. L'équipe note seulement les informations nécessaires au suivi, dans un document non accessible au public. Les nouveaux volontaires reçoivent une présentation de ces règles avant leur première sortie. L'association souhaite favoriser un contact régulier sans transformer la situation d'une personne en contenu destiné à attirer de nouveaux donateurs. Les récits utilisés pour présenter le projet seront préparés séparément, avec un accord explicite des personnes concernées par la publication.","question":"Pourquoi limiter ces informations publiques ?","explanation":"Le passage indique : « Une maraude adapte son parcours aux besoins signalés. Les bénévoles ne publient pas les lieux de rencontre pour protéger les personnes accompagnées. » Cela justifie la réponse : Préserver la confidentialité."},{"number":14,"points":15,"correct":"A","options":["Une difficulté d'accès numérique","La durée des réparations","Le nombre de chaises","Le coût des outils professionnels"],"passage":"Un atelier de réparation réserve des places sans inscription en ligne. Les organisateurs veulent accueillir aussi ceux qui n'utilisent pas internet.\n\nUne partie des places reste réservée à un accueil sur place ou par téléphone. Les bénévoles expliquent ensuite comment préparer l'objet et quels renseignements apporter. Le service souhaite que la méthode d'inscription ne sélectionne pas à elle seule les participants. Les demandes seront suivies pour vérifier si ce choix touche réellement de nouvelles personnes. Il ne s'agit pas d'abandonner un outil pratique pour les habitués, mais de garder plusieurs voies possibles vers la même activité, dans des conditions clairement annoncées au public.","question":"Quelle barrière cherchent-ils à réduire ?","explanation":"Le passage indique : « Un atelier de réparation réserve des places sans inscription en ligne. Les organisateurs veulent accueillir aussi ceux qui n'utilisent pas internet. » Cela justifie la réponse : Une difficulté d'accès numérique."},{"number":15,"points":15,"correct":"B","options":["La publicité des dossiers","Le respect de la dignité","La sélection par la prise de parole","Le classement des difficultés"],"passage":"Une association fournit des repas sans demander aux personnes de raconter publiquement leur situation. L'accueil ne doit pas devenir une épreuve de justification devant les autres.\n\nLes bénéficiaires peuvent s'adresser discrètement à un responsable s'ils ont une demande particulière. Les bénévoles suivent une procédure commune pour éviter des pratiques très différentes selon la personne présente. L'association souhaite que la simplicité de l'accueil ne dépende pas d'une relation personnelle ou de la capacité à raconter une histoire convaincante. Elle vérifiera aussi les temps d'attente et l'organisation de la file.","question":"Quel principe est défendu ?","explanation":"Le passage indique : « Une association fournit des repas sans demander aux personnes de raconter publiquement leur situation. L'accueil ne doit pas devenir une épreuve de justification devant les autres. » Cela justifie la réponse : Le respect de la dignité."},{"number":16,"points":15,"correct":"A","options":["Clarifier les responsabilités lors du prêt","Garantir que rien ne s'abîmera jamais","Remplacer tous les échanges humains","Fixer un prix de vente obligatoire"],"passage":"Des voisins prêtent des objets grâce à un catalogue commun. Une fiche indique leur état au départ et au retour pour éviter les malentendus.\n\nL'emprunteur peut poser des questions avant de confirmer le prêt. Les organisateurs souhaitent préserver la confiance entre voisins sans attendre qu'un problème se transforme en accusation. Les règles précisent aussi ce qui se passe lorsqu'un objet s'abîme malgré une utilisation normale, afin de ne pas confondre tout incident avec une faute ou de promettre qu'un objet partagé restera toujours intact.","question":"À quoi sert cette fiche ?","explanation":"Le passage indique : « Des voisins prêtent des objets grâce à un catalogue commun. Une fiche indique leur état au départ et au retour pour éviter les malentendus. » Cela justifie la réponse : Clarifier les responsabilités lors du prêt."},{"number":17,"points":15,"correct":"D","options":["Les conversations sont interdites","Les visiteurs prescrivent des traitements","Les bénéficiaires doivent rester seuls","Les visites ne remplacent pas des soins"],"passage":"Une équipe organise des visites amicales. Les visiteurs ne réalisent pas de soins ; ils signalent les besoins particuliers au responsable compétent.\n\nLe programme prévoit surtout du temps pour discuter, lire ou faire une petite promenade lorsque cela convient. Les personnes accompagnées choisissent les activités et peuvent demander de reporter un rendez-vous. Le responsable distingue cette présence amicale des interventions nécessitant une formation ou une autorisation particulière. L'association préfère un cadre clair à une promesse d'aide illimitée, qui pourrait mettre en difficulté les visiteurs comme les personnes qu'ils viennent rencontrer.","question":"Quelle limite est posée ?","explanation":"Le passage indique : « Une équipe organise des visites amicales. Les visiteurs ne réalisent pas de soins ; ils signalent les besoins particuliers au responsable compétent. » Cela justifie la réponse : Les visites ne remplacent pas des soins."},{"number":18,"points":15,"correct":"A","options":["Élargir la participation aux échanges","Rendre les documents plus techniques","Réserver les décisions aux traducteurs","Supprimer les débats"],"passage":"Un collectif propose des réunions avec traduction dans plusieurs langues. Les comptes rendus restent courts pour que les informations circulent facilement.\n\nLes participants reçoivent les principaux documents avant la réunion et peuvent demander une précision pendant les échanges. Le comité souhaite que les personnes moins à l'aise dans une langue ne soient pas réduites à écouter sans intervenir. Les traducteurs ne prennent pas les décisions à leur place. Ils facilitent la compréhension de ce qui est proposé et des choix à effectuer.","question":"Quel objectif guide ces choix ?","explanation":"Le passage indique : « Un collectif propose des réunions avec traduction dans plusieurs langues. Les comptes rendus restent courts pour que les informations circulent facilement. » Cela justifie la réponse : Élargir la participation aux échanges."},{"number":19,"points":15,"correct":"B","options":["Éviter tout tri","Assurer la qualité des dons distribués","Réserver les jeux aux organisateurs","Augmenter leur prix de revente"],"passage":"Une collecte de jouets demande des jeux complets. Les pièces manquantes seront recherchées avant la distribution, afin d'offrir des objets réellement utilisables.\n\nLes bénévoles essaient les mécanismes et indiquent les limites lorsqu'un jeu ne peut pas être complété. Certains objets seront réparés avant d'être proposés, d'autres orientés vers une autre filière. Elle expliquera les critères de tri aux personnes qui apportent des jouets, afin de réduire les déplacements inutiles et de préparer les prochaines collectes dans de meilleures conditions.","question":"Pourquoi vérifier les jeux ?","explanation":"Le passage indique : « Une collecte de jouets demande des jeux complets. Les pièces manquantes seront recherchées avant la distribution, afin d'offrir des objets réellement utilisables. » Cela justifie la réponse : Assurer la qualité des dons distribués."},{"number":20,"points":21,"correct":"B","options":["Supprimer toute disponibilité bénévole","Prendre en compte des contraintes différentes","Fixer les horaires au hasard","Éviter de rencontrer les bénéficiaires"],"passage":"Une association consulte les bénéficiaires avant de choisir les horaires d'ouverture. Les créneaux pratiques pour les bénévoles ne sont pas toujours ceux qui conviennent aux personnes accueillies. Les personnes interrogées indiquent notamment les moments où elles peuvent se déplacer et les contraintes liées aux transports. L'association compare ces réponses avec les disponibilités de l'équipe avant de proposer un calendrier. Elle veut éviter qu'une permanence apparemment ouverte reste inaccessible à ceux qu'elle vise. Les horaires seront réexaminés après quelques semaines, en regardant les demandes non satisfaites autant que les présences effectivement enregistrées à l'accueil.","question":"Pourquoi cette consultation est-elle nécessaire ?","explanation":"Le passage indique : « Une association consulte les bénéficiaires avant de choisir les horaires d'ouverture. Les créneaux pratiques pour les bénévoles ne sont pas toujours ceux qui conviennent aux personnes accueillies. » Cela justifie la réponse : Prendre en compte des contraintes différentes."},{"number":21,"points":21,"correct":"D","options":["Les frais réels sont toujours nuls","Tous les déplacements sont des emplois","Les conducteurs paient les passagers","Rembourser une dépense n'est pas rémunérer un service"],"passage":"Un réseau de covoiturage solidaire rembourse les frais réels des conducteurs. Il ne cherche pas à leur procurer un revenu complémentaire. Les trajets et les dépenses doivent être notés selon les règles annoncées à l'inscription. L'association souhaite que les conducteurs n'avancent pas durablement des frais qu'ils ne peuvent pas supporter. Elle précise cependant que le dispositif reste différent d'une activité commerciale de transport. Les responsables vérifieront les documents sans demander aux bénéficiaires de négocier directement un prix à chaque sortie, afin de préserver un cadre compréhensible pour les deux parties.","question":"Quelle distinction est faite ?","explanation":"Le passage indique : « Un réseau de covoiturage solidaire rembourse les frais réels des conducteurs. Il ne cherche pas à leur procurer un revenu complémentaire. » Cela justifie la réponse : Rembourser une dépense n'est pas rémunérer un service."},{"number":22,"points":21,"correct":"B","options":["L'abandon du projet initial sans explication","La transparence envers les donateurs","Le refus de tout suivi","La recherche de nouveaux frais cachés"],"passage":"Une collecte financière réussit au-delà des prévisions. L'association publie l'utilisation du surplus au lieu de modifier discrètement l'objectif annoncé. Les responsables présentent les dépenses supplémentaires envisagées et expliquent leur lien avec le projet initial. Le comité souhaite que la réussite de la collecte ne rende pas son fonctionnement moins lisible. Une somme reçue au-delà de l'objectif reste une ressource à utiliser avec soin, selon des décisions identifiables, et non un montant dont l'emploi pourrait être laissé sans explication publique.","question":"Quel souci manifeste cette démarche ?","explanation":"Le passage indique : « Une collecte financière réussit au-delà des prévisions. L'association publie l'utilisation du surplus au lieu de modifier discrètement l'objectif annoncé. » Cela justifie la réponse : La transparence envers les donateurs."},{"number":23,"points":21,"correct":"C","options":["Éviter les intérêts personnels","Réserver le lieu aux nouveaux arrivants","Créer des relations qui dépassent le seul besoin d'aide","Transformer toutes les rencontres en démarches"],"passage":"Un café accueille des rencontres entre personnes arrivées récemment et habitants installés. Les échanges portent sur des centres d'intérêt partagés, pas uniquement sur les difficultés administratives. Des ateliers de musique, des promenades et des échanges de recettes servent de premiers points de rencontre. Les personnes peuvent venir sans devoir exposer immédiatement leur parcours. L'équipe veut que chacun puisse être reconnu pour ses intérêts et ses contributions, pas uniquement pour une difficulté. Les informations pratiques restent disponibles dans un autre cadre.","question":"Quel effet est recherché ?","explanation":"Le passage indique : « Un café accueille des rencontres entre personnes arrivées récemment et habitants installés. Les échanges portent sur des centres d'intérêt partagés, pas uniquement sur les difficultés administratives. » Cela justifie la réponse : Créer des relations qui dépassent le seul besoin d'aide."},{"number":24,"points":21,"correct":"A","options":["De l'aide pour intégrer les bénévoles","Une rémunération automatique de tous les volontaires","Un remplacement de leur activité par des annonces","Une suppression des missions"],"passage":"Une plateforme met en relation des bénévoles et des associations. Les petites structures souhaitent aussi un accompagnement, car publier une mission ne suffit pas à organiser l'accueil des volontaires. Les coordinateurs doivent présenter la mission, expliquer les limites et prévoir un interlocuteur pour le premier jour. Les structures peu nombreuses n'ont pas toujours le temps de préparer seules ces éléments. Elles demandent donc un soutien qui dépasse la simple visibilité de leur annonce.","question":"Quel besoin complémentaire expriment-elles ?","explanation":"Le passage indique : « Une plateforme met en relation des bénévoles et des associations. Les petites structures souhaitent aussi un accompagnement, car publier une mission ne suffit pas à organiser l'accueil des volontaires. » Cela justifie la réponse : De l'aide pour intégrer les bénévoles."},{"number":25,"points":21,"correct":"C","options":["Les missions d'accueil devraient surtout compter pour les bénévoles qui ne peuvent participer aux travaux agricoles réguliers.","L'expérience botanique peut devenir la mesure principale lorsque l'organisation administrative des parcelles est assurée.","La seule contribution physique, au détriment de la coordination et de l'accueil, au sein du jardin.","La contribution doit être rapportée au temps de travail visible, les tâches de planning restant un soutien complémentaire."],"passage":"Un jardin collectif attribue des tâches adaptées aux capacités de chacun. L'association reconnaît aussi l'organisation et l'accueil comme des contributions, pas seulement le travail physique. Les membres discutent des tâches avant chaque période importante, puis peuvent changer de rôle. Certaines personnes connaissent les plantes, d'autres savent accueillir un nouveau voisin ou tenir le planning. L'association souhaite éviter qu'une même forme de contribution devienne la mesure unique de l'engagement. Un membre ne peut pas bêcher mais coordonne les plannings et aide à résoudre les conflits d'horaires; sans lui, les plantations seraient retardées. Les responsables comptabilisent aussi cette contribution quand ils répartissent les responsabilités.","question":"Quel critère d'engagement le jardin refuse-t-il de privilégier exclusivement ?","explanation":"C identifie le critère purement physique que le jardin refuse d'imposer seul. A réserve la reconnaissance de l'accueil à certains bénévoles; B privilégie la botanique; D fait du travail visible la référence alors que la coordination des plannings est essentielle."},{"number":26,"points":21,"correct":"B","options":["Elle confie aux personnes accueillies le choix du stock à commander pour la semaine selon leurs besoins exprimés.","Elle ouvre des choix informés dans la limite des stocks disponibles, avec des explications adaptées aux familles.","Elle étend la gamme de produits distribués sans modifier la manière dont les bénévoles orientent les décisions.","Elle facilite surtout les choix des personnes qui maîtrisent déjà la préparation des produits disponibles."],"passage":"Une banque alimentaire forme ses équipes à expliquer les choix disponibles. Les personnes accompagnées peuvent exprimer leurs préférences dans les limites du stock. Les bénévoles présentent les aliments et les conditions de conservation sans supposer que toutes les familles les utilisent de la même manière. L'équipe ne promet pas un choix sans limite, mais veut que les possibilités réelles soient expliquées et que les personnes ne soient pas simplement destinataires d'une décision prise sans elles. Le stock contient deux céréales que certaines familles ne savent pas préparer de la même façon. Une bénévole explique les usages et laisse la personne choisir, sans garantir que chaque produit sera toujours disponible.","question":"Que modifie cette pratique dans la relation d'aide ?","explanation":"B associe information et choix possible dans les limites du stock. A attribue aux bénéficiaires des commandes non prévues; C déplace le changement vers l'assortiment; D laisse les novices exclus contrairement à l'exemple."},{"number":27,"points":21,"correct":"D","options":["Elle permet aux fondateurs d'assurer seuls une continuité stable en confiant aux autres des tâches moins importantes.","Elle transforme les permanences en engagements spontanés, sans prévoir de relais lors des absences.","Elle rend les nouveaux bénévoles indépendants de toute formation supplémentaire après lecture des fiches.","Elle réduit la dépendance à quelques membres détenant les informations essentielles, lors des absences imprévues."],"passage":"Un groupe souhaite pérenniser ses actions après une urgence locale. Il organise un calendrier et répartit les responsabilités pour éviter que tout repose sur deux fondateurs. Les fondateurs préparent des fiches simples et accompagnent les nouveaux responsables lors des premières permanences. Ils souhaitent que l'information circule au lieu de rester dans quelques téléphones personnels. Les membres pourront signaler les tâches trop lourdes avant de se décourager. Lorsque l'un des fondateurs tombe malade, les nouvelles fiches permettent de maintenir les permanences avec une autre équipe. Les documents servent d'appui à une transmission effective, non de remplacement à tout accompagnement.","question":"Pourquoi la transmission des tâches est-elle centrale pour la pérennité du groupe ?","explanation":"D limite la dépendance à quelques membres. A conserve cette concentration; B supprime les remplacements nécessaires; C confond documentation et absence de tout accompagnement."},{"number":28,"points":21,"correct":"D","options":["Un récit détaillé permet d'estimer l'impact moyen des interventions qui appartiennent à la même catégorie.","Les témoignages devraient remplacer les tableaux lorsque les interventions administratives semblent équivalentes.","Le témoignage le plus significatif peut illustrer le résultat typique du programme dès lors que la publication est autorisée.","Éclairer des effets particuliers sans généraliser à tous les bénéficiaires, dans les bilans des interventions réalisées."],"passage":"L'association ajoute des témoignages à son bilan chiffré. Une aide ponctuelle peut avoir un effet important que le seul nombre d'interventions ne décrit pas. Les récits sont recueillis avec l'accord des personnes et relus avant une éventuelle publication. Ils ne remplacent pas les données de suivi, mais aident à comprendre des effets que les tableaux résument mal. Le centre veut éviter de présenter chaque histoire comme représentative de toutes les situations. Le bilan compte dix interventions identiques, mais un témoignage décrit comment l'une d'elles a permis une reprise de démarches après des mois d'arrêt. L'association conserve le total et la description, sans généraliser ce résultat particulier à tous les cas.","question":"Que permet l'ajout de témoignages sans remplacer les chiffres ?","explanation":"D met en lumière un effet particulier sans le généraliser à toutes les interventions. A et C prêtent à un récit une représentativité non établie; B remplacerait les totaux que l'association veut justement conserver."},{"number":29,"points":21,"correct":"B","options":["La participation régulière aux activités constitue une condition pour bénéficier d'aides complémentaires plutôt que de l'accueil initial.","Recevoir une aide relève d'un droit d'accueil indépendant d'une éventuelle contribution volontaire, dans toutes les circonstances.","Les bénéficiaires proposant d'aider à l'accueil peuvent être prioritaires lorsque les services manquent de places.","Une personne devenue bénévole cesse d'être éligible aux aides puisque ses besoins sont supposés avoir diminué."],"passage":"Un centre propose de participer à l'organisation aux personnes qui viennent y chercher une aide. Cette possibilité est facultative et n'est pas une condition pour être accueilli. Les bénéficiaires peuvent proposer une activité, aider à un rangement ou participer à une réunion lorsqu'ils le souhaitent. Ils veulent préserver un droit à l'accueil tout en reconnaissant que les personnes reçues peuvent aussi contribuer à la vie du lieu. Une personne ne souhaite pas participer aux réunions mais a besoin d'un colis alimentaire. Le centre confirme que son accès ne changera pas; une autre personne choisit d'aider ponctuellement à l'accueil.","question":"Quelle distinction protège la liberté des personnes accompagnées ?","explanation":"B affirme l'indépendance de l'aide et du bénévolat. A/C réintroduisent des conditions d'accès, D invente une perte de droits liée à la participation."},{"number":30,"points":26,"correct":"C","options":["Prolonger la période de mobilisation renforcée afin de profiter de l'expérience des bénévoles déjà très investis.","Confier durablement aux fondateurs les tâches les plus exigeantes et proposer les autres missions au reste du groupe.","Prévoir relais et limites pour maintenir l'engagement sans épuiser les bénévoles, tout au long de l'année.","Privilégier des engagements très courts décidés au dernier moment pour respecter la liberté individuelle des bénévoles."],"passage":"L'engagement bénévole est parfois présenté comme un temps libre sans contraintes. Or une association doit aussi définir les limites des missions et reconnaître les indisponibilités. Une disponibilité généreuse mais sans cadre peut conduire à l'épuisement et compromettre la continuité de l'action. Les responsables prévoient des pauses, des relais et un interlocuteur en cas de difficulté. Ces règles ne diminuent pas la générosité du projet ; elles lui permettent de rester possible quand les premières semaines d'enthousiasme sont passées. Une bénévole assure trois permanences supplémentaires en période d'urgence puis demande un relais. L'association organise une rotation, car maintenir cette disponibilité exceptionnelle pendant toute l'année l'épuiserait.","question":"Quel principe soutient la continuité du bénévolat après la phase d'urgence ?","explanation":"C formalise des relais et des limites. A/B prolongent la surcharge sur quelques personnes, D supprime une prévisibilité nécessaire à la continuité."},{"number":31,"points":26,"correct":"A","options":["Les distributions répondent aux besoins actuels, tandis qu'une action plus lente vise des causes structurelles, à terme.","L'aide d'urgence fournit des observations mais ne peut pas être utilisée pour discuter des causes de logement.","L'amélioration du logement constitue une étape préalable à toute distribution, afin d'éviter la répétition des besoins.","La quantité de colis distribués donne directement la mesure des progrès accomplis dans les conditions d'habitat."],"passage":"Une aide rapide répond à une urgence. Elle ne modifie pas nécessairement les causes qui rendent cette aide indispensable. Un collectif maintient ses distributions tout en participant à un travail sur l'accès au logement. Les deux démarches répondent à des temporalités différentes. Ils souhaitent continuer à répondre aux besoins présents, tout en utilisant ce qu'ils observent pour participer à des changements qui pourraient réduire la nécessité de ces interventions à l'avenir. Les distributions de nourriture répondent aux besoins de cette semaine, tandis que les données recueillies sur les difficultés de logement sont transmises à un groupe de travail. Les organisateurs refusent de présenter l'une des démarches comme substitut de l'autre.","question":"Quel lien le collectif établit-il entre distribution et action sur le logement ?","explanation":"A articule aide immédiate et action plus lente sur les causes. B nie la possibilité de transmission d'information; C reporte l'urgence, D confond activité et changement structurel."},{"number":32,"points":26,"correct":"D","options":["Le comparer aux confirmations de créneau pour mesurer l'écart entre intérêt initial et disponibilité probable.","Le rapprocher des présences effectives pour distinguer les intentions initiales des engagements réellement tenus pendant la première semaine.","L'utiliser comme liste de contacts à solliciter pour confirmer les disponibilités avant d'établir le calendrier des permanences.","Le présenter comme un effectif disponible garanti pour couvrir les missions prévues, sans vérification préalable."],"passage":"Le nombre de volontaires inscrits sur une plateforme augmente. Les associations observent pourtant des présences irrégulières. Pour apprécier les ressources réelles, elles distinguent une intention d'engagement et une participation effectivement organisée. Les responsables proposent un accueil et une confirmation concrète des créneaux. Le passage d'une candidature à une présence régulière demande une organisation, même lorsque les personnes déclarent sincèrement vouloir aider et disposent de compétences utiles à l'association. Cent profils sont créés en ligne, mais seuls trente volontaires confirment un créneau et dix se présentent la première semaine. L'association cherche à comprendre cette conversion sans supposer que les soixante-dix autres sont insincères.","question":"Quel usage du nombre d'inscriptions serait trompeur ?","explanation":"D ferait des cent profils inscrits un effectif disponible garanti, malgré seulement trente confirmations et dix présences. A, B et C proposent au contraire de distinguer profils, engagements effectifs et contacts à relancer."},{"number":33,"points":26,"correct":"D","options":["Recueillir un accord général puis choisir les propositions que le budget rend effectivement applicables.","Présenter les contraintes financières après le vote et considérer les décisions finales comme automatiquement approuvées.","Mettre en avant les citations les plus fréquentes sans expliquer la manière dont les idées ont été examinées.","Expliquer comment les propositions ont influencé les décisions et pourquoi, avec un retour sur les arbitrages."],"passage":"Une organisation souhaite « donner la parole » à ses bénéficiaires. Elle doit aussi leur laisser un effet sur les décisions. Recueillir des avis sans expliquer ce qui en sera fait peut transformer la consultation en simple illustration d'un projet déjà arrêté. Cette réponse permet aux participants d'apprécier la portée de leur contribution et de comprendre les contraintes, au lieu de disparaître après la réunion. Après une réunion, les habitants proposent deux changements. L'organisation explique qu'elle adopte le premier et reporte le second pour des raisons de sécurité documentées. Cette réponse permet de comprendre la portée de la consultation.","question":"Quelle pratique rend la consultation plus qu'une collecte symbolique d'opinions ?","explanation":"D documente les suites données aux suggestions et les motifs. A/B n'expliquent pas le lien entre avis et arbitrages; C valorise des citations sans décision."},{"number":34,"points":26,"correct":"B","options":["Parce qu'un accueil soigné peut réduire l'importance des contraintes budgétaires des personnes aidées.","Une présentation soignée peut respecter les clients et contribuer à la mission sociale, sans demander de justification personnelle.","Parce qu'une boutique agréable rend moins nécessaire l'accompagnement des clients dans leurs choix.","Parce que l'organisation ressemble davantage à un commerce ordinaire et peut donc adopter les mêmes objectifs de profit."],"passage":"Une boutique solidaire améliore sa présentation pour que les clients puissent choisir dans un lieu accueillant. Certains s'inquiètent qu'une belle vitrine fasse oublier la mission sociale. L'équipe répond que le respect des personnes peut aussi passer par la qualité ordinaire du service. Les clients peuvent consulter les prix et demander des informations sur les objets comme dans un autre commerce. La boutique présente les objets avec des prix lisibles et propose un conseil sans exiger que les clients expliquent leur situation. Les responsables estiment qu'une qualité d'accueil comparable à un commerce ordinaire peut faire partie du respect.","question":"Pourquoi une présentation soignée n'est-elle pas incompatible avec la mission sociale ?","explanation":"B considère la dignité de l'accueil comme compatible avec la mission sociale. A/C minimisent les besoins, D assimile apparence commerciale et finalité lucrative."},{"number":35,"points":26,"correct":"B","options":["À limiter les échanges informels aux membres les plus anciens afin de stabiliser les procédures communes.","À rendre l'organisation accessible aux nouveaux arrivants tout en conservant les relations d'entraide, malgré certaines absences.","À maintenir la transmission dans les messages personnels tout en ajoutant un guide pour les nouveaux.","À fixer les consignes initiales de manière durable sans prévoir de nouvelles discussions sur leur évolution."],"passage":"Le développement d'un réseau d'entraide augmente les demandes adressées aux coordinateurs. Pour durer, le groupe formalise certaines règles sans supprimer les échanges informels. Il cherche à préserver la confiance tout en rendant l'organisation moins dépendante de relations personnelles fragiles. Les nouveaux membres sauront où chercher une information et à qui poser une question, même lorsque les personnes qui les ont accueillis sont absentes. Une nouvelle coordinatrice trouve les consignes écrites même lorsque son mentor est absent, mais continue d'échanger librement avec l'équipe. Le réseau souhaite réduire la fragilité de la transmission sans formaliser chaque conversation.","question":"À quoi sert la formalisation partielle des règles ?","explanation":"B combine une documentation accessible aux nouveaux avec les relations informelles. A restreint les échanges, C maintient la dépendance aux personnes, D exclut l'ajustement pourtant recherché."},{"number":36,"points":33,"correct":"A","options":["Parce que les effets sociaux et la capacité de participation constituent aussi des résultats pertinents.","Parce que l'absence d'emploi pendant le trimestre doit être compensée par des résultats de formation immédiats.","Parce que la fréquentation régulière d'un atelier établit à elle seule son effet sur l'autonomie économique.","Parce que des changements relationnels permettent de prévoir avec fiabilité de futurs contrats de travail."],"passage":"Un projet associe des personnes précaires à des ateliers culturels. Les organisateurs refusent de mesurer le résultat uniquement par un retour à l'emploi. Les relations, la confiance et la possibilité de participer à une vie commune ont une valeur propre. L'utilité sociale ne se réduit pas toujours à un indicateur économique immédiat. Les participants peuvent parler d'un changement dans leurs relations ou de la possibilité de sortir plus facilement de chez eux. Certains envisagent ensuite une formation ou un emploi, d'autres recherchent surtout un espace où ils se sentent reconnus. Le centre souhaite décrire ces trajectoires sans les classer selon une seule issue. Il discutera donc des critères avec les personnes concernées avant de rédiger son bilan. Le projet peut avoir plusieurs effets utiles, dont certains apparaissent lentement et restent difficiles à résumer dans un chiffre unique présenté à la fin de l'année. Un atelier n'aboutit à aucun contrat de travail pendant le trimestre, mais plusieurs personnes auparavant isolées participent désormais à des rencontres et prennent part à des décisions du quartier. Le centre veut rendre ce changement visible dans son bilan.","question":"Pourquoi l'absence de contrat de travail ne suffit-elle pas à qualifier cet atelier d'échec ?","explanation":"A reconnaît la participation sociale et la confiance comme résultats utiles en eux-mêmes. B/D réintroduisent une lecture essentiellement professionnelle; C prête à la seule fréquentation une portée causale non démontrée."},{"number":37,"points":33,"correct":"A","options":["L'exigence d'une activité durable se heurte à une visibilité des ressources trop courte pour l'organiser.","Une formation longue donne aux financeurs la possibilité de suspendre les ressources au moment des évaluations.","Un financement annuel réduit les coûts administratifs mais rend plus difficile l'examen régulier des résultats.","L'incertitude financière vient surtout d'un manque de planification interne que les responsables peuvent corriger seuls."],"passage":"Une association dépend d'un financement annuel renouvelable. Elle peut annoncer beaucoup d'activités, mais hésite à former durablement son équipe sans visibilité. Les financeurs demandent de la stabilité aux actions qu'ils soutiennent. Cette stabilité devient difficile lorsque les ressources permettant de la construire restent elles-mêmes incertaines. Les responsables cherchent un calendrier de financement qui permette d'anticiper les embauches et la formation. Ils expliquent que le temps passé à reconstruire sans cesse des dossiers réduit aussi celui disponible pour l'accueil. Les financeurs souhaitent garder la possibilité d'évaluer les actions et de réorienter les soutiens. Le débat porte donc sur des engagements assez stables pour rendre l'activité possible, sans supprimer l'examen de ses résultats. Les associations veulent que cette incertitude soit visible dans le bilan, plutôt que les interruptions soient interprétées uniquement comme un défaut d'organisation interne. Le financeur souhaite des équipes formées et régulières, mais annonce le renouvellement de sa subvention seulement quelques semaines avant chaque échéance. L'association hésite alors à embaucher pour les missions qui demandent un an de préparation.","question":"Quel problème de cohérence le calendrier de financement crée-t-il ?","explanation":"A décrit la contradiction entre demande de stabilité et ressources trop incertaines pour la préparer. B/C ne correspondent pas au problème exposé; D attribue à l'association seule un défaut lié au calendrier du financeur."},{"number":38,"points":33,"correct":"B","options":["Un nouveau support de communication exige d'informer les témoins, mais l'accord initial couvre toutes les campagnes similaires.","L'accord porte sur un usage précis, non sur toutes les diffusions futures, dans une campagne nouvelle.","La première diffusion autorise les campagnes suivantes dès lors que les propos cités ne sont pas modifiés.","Le consentement donné pendant l'accompagnement vaut aussi pour des usages institutionnels ultérieurs, sous réserve d'anonymat."],"passage":"Un collectif publie les récits de personnes accompagnées pour sensibiliser le public. Il leur propose de relire les textes et de retirer leur accord avant diffusion. Le fait qu'un témoignage serve une cause utile ne supprime pas les droits de la personne dont il raconte l'expérience. L'objectif collectif ne dispense pas de respecter une décision individuelle de ne pas s'exposer. L'association présente plusieurs moyens de contribuer à la sensibilisation, dont certains ne montrent aucun visage ni détail personnel. Elle accepte qu'une personne préfère ne pas participer, sans changer l'aide qu'elle reçoit. Les responsables souhaitent éviter qu'un accord donné dans une situation fragile devienne une obligation ressentie. Avant chaque nouvelle utilisation, le cadre sera expliqué dans une langue compréhensible. La communication pourra ainsi servir le projet tout en conservant une place à la décision de chacun, y compris lorsqu'une histoire particulièrement émouvante semblerait très efficace pour mobiliser de futurs soutiens. Une histoire publiée avec accord initial est ensuite demandée par une autre campagne. L'association sollicite une nouvelle autorisation, car la première personne n'avait accepté qu'une utilisation délimitée.","question":"Que signifie ici le respect du consentement lors d'une nouvelle campagne ?","explanation":"B limite l'accord à l'usage consenti et reconnaît la possibilité d'une nouvelle décision. A/C supposent une autorisation plus étendue que celle donnée; D lie à tort l'aide à des utilisations futures."},{"number":39,"points":33,"correct":"A","options":["Des moyens de départ comparables ne suffisent pas: la capacité des partenaires à assurer l'accueil doit être reconstruite selon chaque territoire.","Des activités initiales de même nombre prouvent que les deux territoires appliquent le modèle avec une efficacité comparable dans la durée.","La différence observée démontre que les partenaires expliquent seuls la réussite, à l'exclusion d'autres conditions territoriales.","La communication locale peut assurer la continuité d'un lieu si les permanences initiales ont suscité un intérêt suffisant."],"passage":"Une initiative locale attire l'attention nationale. Ses responsables sont invités à reproduire partout le même modèle. Ils présentent les principes, mais soulignent les relations de confiance et les ressources particulières qui ont permis leur réussite. Transmettre une expérience ne signifie pas promettre qu'elle produira les mêmes effets sans adaptation. Ils proposent aux nouveaux groupes d'examiner les besoins, les partenaires et les disponibilités avant de reprendre les mêmes activités. Certaines règles pourront être conservées, tandis que d'autres devront changer selon les personnes accueillies. L'équipe souhaite rester utile sans transformer un succès local en formule universelle. Les échanges porteront aussi sur les difficultés rencontrées, pas seulement sur les résultats faciles à montrer. Cette démarche demande plus de temps qu'une copie rapide, mais permet de distinguer les principes transférables et les conditions particulières qui doivent être reconstruites dans le nouveau territoire. Dans une autre ville, l'association trouve des locaux comparables mais aucun partenaire capable d'assurer les permanences. Elle conserve le principe d'accueil libre et modifie le calendrier et les responsabilités au lieu de copier la formule initiale. Deux communes reprennent ensuite l'initiative en annonçant le même budget et des locaux semblables. Dans la première, une maison de quartier dispose déjà d'une équipe de médiateurs et d'accords avec les services sociaux; dans la seconde, les locaux restent souvent fermés faute de personnes pour recevoir les visiteurs. Les deux communes affichent pourtant un nombre d'activités comparable durant le premier mois, grâce à des bénévoles mobilisés exceptionnellement. Six mois plus tard, seule la première maintient des permanences régulières. L'équipe d'origine refuse de conclure que la seconde commune devrait simplement augmenter les dépenses de communication: elle propose d'identifier quels partenaires peuvent réellement assurer l'accueil et de modifier le calendrier en conséquence. Le rapport précise que la différence de continuité ne démontre pas, à elle seule, que chaque autre différence entre territoires est sans effet.","question":"Quelle leçon les deux implantations apportent-elles sur la transposition d'un modèle, sans généralisation abusive ?","explanation":"A distingue les moyens matériels comparables du réseau de partenaires nécessaire à des permanences durables. B infère trop du premier mois; C fait des partenaires l'unique cause sans preuve; D suppose que la communication peut remplacer l'organisation de l'accueil."}]}$bank_11$::jsonb),
('tcf-reading-12','tcf-reading-2026-11-close-reading-v4',$bank_12${"id":"tcf-reading-12","title":"TCF Reading · Test 12","seconds":3600,"version":"tcf-reading-2026-11-close-reading-v4","maxPoints":699,"questions":[{"number":1,"points":3,"correct":"D","options":["Tous les champs privés","Le sentier des vergers","La cour de la ferme","Le chemin communal"],"passage":"Le sentier des vergers est fermé pendant la récolte. La promenade reste possible par le chemin communal.\n\nLes promeneurs sont invités à suivre les panneaux temporaires. La fermeture doit permettre le passage des équipes et du matériel sans gêne.","question":"Quel chemin reste accessible ?","explanation":"Le passage indique : « Le sentier des vergers est fermé pendant la récolte. La promenade reste possible par le chemin communal. » Cela justifie la réponse : Le chemin communal."},{"number":2,"points":3,"correct":"C","options":["Dormir dans l'étable","Visiter l'élevage","Acheter à la boutique","Participer aux naissances"],"passage":"La ferme ouvre sa boutique vendredi, mais les visites d'élevage reprendront seulement au printemps.\n\nL'équipe peut toutefois répondre aux questions sur les produits pendant les horaires de vente.","question":"Que peut-on faire vendredi ?","explanation":"Le passage indique : « La ferme ouvre sa boutique vendredi, mais les visites d'élevage reprendront seulement au printemps. » Cela justifie la réponse : Acheter à la boutique."},{"number":3,"points":3,"correct":"C","options":["Accompagner obligatoirement chaque visiteur","Courir librement dans les cultures","Rester attachés sur le chemin","Entrer dans tous les bâtiments"],"passage":"Les chiens sont acceptés sur le chemin s'ils restent en laisse. Ils ne doivent pas entrer dans les parcelles.\n\nCette consigne permet de maintenir l'accès public sans perturber le travail dans les champs voisins.","question":"Quelle règle concerne les chiens ?","explanation":"Le passage indique : « Les chiens sont acceptés sur le chemin s'ils restent en laisse. Ils ne doivent pas entrer dans les parcelles. » Cela justifie la réponse : Rester attachés sur le chemin."},{"number":4,"points":3,"correct":"A","options":["Dimanche pendant les horaires indiqués","Après seize heures dimanche","Tous les soirs","Uniquement en hiver"],"passage":"Le moulin reçoit les groupes sur réservation. Les visiteurs individuels peuvent venir dimanche entre dix et seize heures.\n\nLes groupes recevront une confirmation avec les conditions d'accueil. Les visites individuelles suivront le parcours ouvert et respecteront les espaces non accessibles au public.","question":"Quand une personne seule peut-elle venir sans réservation ?","explanation":"Le passage indique : « Le moulin reçoit les groupes sur réservation. Les visiteurs individuels peuvent venir dimanche entre dix et seize heures. » Cela justifie la réponse : Dimanche pendant les horaires indiqués."},{"number":5,"points":9,"correct":"A","options":["Protéger les jeunes plants du gel","Les laisser sans lumière pendant un mois","Les arroser avec de l'eau glacée","Les planter immédiatement dehors"],"passage":"Je te garderai les plants jusqu'à samedi. Mets-les à l'abri si le gel revient ; ils ne sont pas encore prêts pour la pleine terre.\n\nJe te préciserai quelles variétés supportent mieux le froid. Prévois quelques pots pour les garder temporairement près d'une fenêtre plutôt que les installer trop vite au jardin.","question":"Quelle précaution est conseillée ?","explanation":"Le passage indique : « Je te garderai les plants jusqu'à samedi. Mets-les à l'abri si le gel revient ; ils ne sont pas encore prêts pour la pleine terre. » Cela justifie la réponse : Protéger les jeunes plants du gel."},{"number":6,"points":9,"correct":"C","options":["Ils resteront obligatoirement au musée","Ils seront vendus aux visiteurs","Ils seront restitués après copie","Ils seront détruits après exposition"],"passage":"L'association recherche des photos anciennes du village. Les originaux seront numérisés puis rendus ; aucun don définitif n'est demandé.\n\nUne fiche permettra d'identifier les lieux et les personnes représentés lorsque ces informations sont connues. Les propriétaires pourront vérifier les légendes avant l'exposition.","question":"Que deviendront les documents prêtés ?","explanation":"Le passage indique : « L'association recherche des photos anciennes du village. Les originaux seront numérisés puis rendus ; aucun don définitif n'est demandé. » Cela justifie la réponse : Ils seront restitués après copie."},{"number":7,"points":9,"correct":"D","options":["Approcher seules les ruches","Renoncer à toute activité rurale","Apporter leur propre miel","Prévenir l'organisateur à l'avance"],"passage":"Nous visiterons les ruches avec un apiculteur. Les personnes sensibles aux piqûres doivent le signaler avant la sortie.\n\nUn équipement de protection sera présenté au groupe avant l'approche. Le responsable pourra proposer une autre manière de suivre l'activité si une situation demande davantage de précautions.","question":"Quelle démarche est demandée à certaines personnes ?","explanation":"Le passage indique : « Nous visiterons les ruches avec un apiculteur. Les personnes sensibles aux piqûres doivent le signaler avant la sortie. » Cela justifie la réponse : Prévenir l'organisateur à l'avance."},{"number":8,"points":9,"correct":"A","options":["Une récolte a subi un aléa météo","Tous les fruits ont été vendus à l'étranger","Les clients ont demandé uniquement des légumes","Le point de retrait est fermé"],"passage":"Le panier de cette semaine contient moins de fruits, mais davantage de légumes. La grêle a touché une partie du verger.\n\nLes quantités seront expliquées au point de retrait. Les producteurs vous remercient pour votre compréhension.","question":"Pourquoi le contenu change-t-il ?","explanation":"Le passage indique : « Le panier de cette semaine contient moins de fruits, mais davantage de légumes. La grêle a touché une partie du verger. » Cela justifie la réponse : Une récolte a subi un aléa météo."},{"number":9,"points":9,"correct":"B","options":["Des sandales de ville","Des chaussures adaptées à la boue","Des patins","Un masque de plongée"],"passage":"Apportez des bottes pour la visite : le chemin près des pâtures est boueux, même lorsque la cour semble sèche.\n\nNous marcherons aussi sur une partie du terrain pour découvrir les activités du jour.","question":"Quel équipement est recommandé ?","explanation":"Le passage indique : « Apportez des bottes pour la visite : le chemin près des pâtures est boueux, même lorsque la cour semble sèche. » Cela justifie la réponse : Des chaussures adaptées à la boue."},{"number":10,"points":9,"correct":"B","options":["Éviter toute rencontre","Limiter la fatigue liée à la chaleur","Terminer une livraison nocturne","Profiter d'une température plus élevée"],"passage":"Je préfère venir aider au désherbage tôt le matin. Ensuite, la chaleur rend le travail plus fatigant.\n\nJe pourrai ensuite aider à ranger le matériel avant de repartir. Cette organisation me permettra de travailler tranquillement sans devoir interrompre longtemps l'activité aux heures les plus difficiles.","question":"Pourquoi choisir cet horaire ?","explanation":"Le passage indique : « Je préfère venir aider au désherbage tôt le matin. Ensuite, la chaleur rend le travail plus fatigant. » Cela justifie la réponse : Limiter la fatigue liée à la chaleur."},{"number":11,"points":15,"correct":"B","options":["La suppression des plantes aquatiques","La préservation d'habitats particuliers","L'uniformité esthétique","La création d'un parking"],"passage":"Une commune conserve de petites mares malgré leur aspect parfois désordonné. Elles accueillent des espèces qui ne vivent pas dans les bassins décoratifs.\n\nLes agents ont prévu un entretien différent des abords, afin de ne pas retirer toute la végétation pendant une période sensible. Des panneaux expliqueront ce choix aux passants. La commune souhaite éviter que la présence de plantes irrégulières ou d'eau trouble soit automatiquement interprétée comme un abandon. Les habitants pourront alors découvrir les fonctions de ces lieux modestes, dont l'intérêt ne se voit pas toujours dans un paysage aménagé uniquement pour paraître propre sur une photographie.","question":"Quel intérêt est souligné ?","explanation":"Le passage indique : « Une commune conserve de petites mares malgré leur aspect parfois désordonné. Elles accueillent des espèces qui ne vivent pas dans les bassins décoratifs. » Cela justifie la réponse : La préservation d'habitats particuliers."},{"number":12,"points":15,"correct":"C","options":["Transformer les prairies en routes","Récolter le lait sans déplacement","Laisser les prairies se renouveler","Éviter toute alimentation des animaux"],"passage":"Un éleveur déplace ses animaux entre plusieurs parcelles. Les périodes de repos permettent à l'herbe de repousser.\n\nIl observe la végétation et les traces de passage avant de décider du prochain déplacement. L'exploitant ne présente pas la rotation comme un calendrier indépendant de la météo : elle demande un suivi, afin que l'organisation protège les ressources dont les animaux auront besoin pendant le reste de la saison.","question":"À quoi sert la rotation ?","explanation":"Le passage indique : « Un éleveur déplace ses animaux entre plusieurs parcelles. Les périodes de repos permettent à l'herbe de repousser. » Cela justifie la réponse : Laisser les prairies se renouveler."},{"number":13,"points":15,"correct":"B","options":["Le prix des clôtures","La présence de fleurs","La couleur des maisons","Le nombre de voitures"],"passage":"Des habitants relèvent la présence d'insectes sur une haie. Ils observent aussi les fleurs disponibles pour relier les visites aux ressources du lieu.\n\nLes bénévoles utilisent une fiche commune et choisissent plusieurs moments d'observation pour ne pas retenir seulement une visite exceptionnelle. Les espèces difficiles à identifier seront examinées avec une association. Le groupe souhaite apprendre à relier les présences aux conditions du lieu, sans conclure à partir d'une photographie isolée. Les habitants pourront ainsi comprendre pourquoi deux observations différentes ne signifient pas automatiquement qu'une plante attire toujours davantage d'insectes qu'une autre dans toutes les situations.","question":"Quelle information complète le comptage ?","explanation":"Le passage indique : « Des habitants relèvent la présence d'insectes sur une haie. Ils observent aussi les fleurs disponibles pour relier les visites aux ressources du lieu. » Cela justifie la réponse : La présence de fleurs."},{"number":14,"points":15,"correct":"D","options":["Supprimer toutes les ventes fraîches","Travailler uniquement un mois par an","Acheter exclusivement des produits importés","Réduire les variations saisonnières de revenus"],"passage":"Une ferme vend des produits transformés sur place pour mieux répartir ses revenus dans l'année. Les ateliers occupent notamment les périodes où les ventes fraîches diminuent.\n\nLes préparations sont choisies selon les produits disponibles et les équipements que la ferme peut utiliser correctement. Les clients peuvent acheter sur place ou lors de quelques marchés. L'exploitant suit le temps consacré à cette activité, car transformer demande aussi de nouvelles compétences et une organisation précise. Il ne suffit pas de conserver un produit pour garantir sa vente.","question":"Quel objectif économique est poursuivi ?","explanation":"Le passage indique : « Une ferme vend des produits transformés sur place pour mieux répartir ses revenus dans l'année. Les ateliers occupent notamment les périodes où les ventes fraîches diminuent. » Cela justifie la réponse : Réduire les variations saisonnières de revenus."},{"number":15,"points":15,"correct":"C","options":["Éviter toute observation","Appliquer une règle identique à toutes les graines","Distinguer les conditions de culture","Mesurer seulement le prix des sachets"],"passage":"Une classe découvre les semences avant le potager. Les élèves comparent leur taille et leurs besoins plutôt que planter tout au même moment.\n\nLes groupes peuvent comparer leurs observations avant d'intervenir. Les animateurs souhaitent éviter que l'activité soit réduite à enfouir des graines puis attendre un résultat identique. Certaines demandes d'eau, de lumière ou de température doivent être anticipées. À la fin de la saison, les élèves raconteront aussi les essais qui n'ont pas fonctionné, afin de comprendre ce qu'ils ont appris sans mesurer la réussite uniquement au nombre de légumes récoltés dans leur petite parcelle.","question":"Quel apprentissage est visé ?","explanation":"Le passage indique : « Une classe découvre les semences avant le potager. Les élèves comparent leur taille et leurs besoins plutôt que planter tout au même moment. » Cela justifie la réponse : Distinguer les conditions de culture."},{"number":16,"points":15,"correct":"C","options":["Remplacer les pierres par du plastique","Empêcher tous les passages d'eau","Conserver plusieurs fonctions du muret","Rendre le sol totalement étanche"],"passage":"Des bénévoles restaurent un muret sans ciment. Ils apprennent une technique locale qui permet l'écoulement de l'eau et offre des refuges à de petits animaux.\n\nLes participants observent les pierres disponibles avant de commencer et choisissent leur position avec l'aide d'un artisan. Ils ne cherchent pas à reproduire un décor sans comprendre sa construction. Le chantier permettra aussi de discuter des réparations anciennes et des gestes d'entretien. Le village souhaite conserver un savoir utile en donnant aux bénévoles l'occasion de pratiquer, plutôt qu'en montrant seulement un mur terminé.","question":"Quel avantage est indiqué ?","explanation":"Le passage indique : « Des bénévoles restaurent un muret sans ciment. Ils apprennent une technique locale qui permet l'écoulement de l'eau et offre des refuges à de petits animaux. » Cela justifie la réponse : Conserver plusieurs fonctions du muret."},{"number":17,"points":15,"correct":"B","options":["Récolter dans toutes les parcelles","Préserver les cultures pendant la récolte","Choisir gratuitement tout le stock","Entrer sans consigne"],"passage":"Un producteur ouvre une journée d'autocueillette. Les visiteurs paient les fruits récoltés et doivent respecter les rangs indiqués pour ne pas abîmer les plants.\n\nLes rangs ouverts sont marqués et les quantités pesées à la sortie. L'équipe explique quels fruits peuvent être cueillis et comment éviter de casser les branches. Les visiteurs sont invités à demander conseil plutôt qu'à déplacer les repères eux-mêmes. La ferme souhaite proposer une rencontre agréable avec la production, sans oublier que les plantes doivent continuer à donner après leur passage.","question":"Quelle responsabilité accompagne l'activité ?","explanation":"Le passage indique : « Un producteur ouvre une journée d'autocueillette. Les visiteurs paient les fruits récoltés et doivent respecter les rangs indiqués pour ne pas abîmer les plants. » Cela justifie la réponse : Préserver les cultures pendant la récolte."},{"number":18,"points":15,"correct":"D","options":["Une fermeture des commerces","Une hausse obligatoire des achats","Une suppression des relations de voisinage","Un accès plus autonome au marché"],"passage":"Un marché rural ajoute un arrêt de navette. Les personnes sans voiture peuvent désormais y venir, sans dépendre d'un voisin disponible.\n\nLes horaires ont été construits autour des jours de marché, avec un temps suffisant pour faire les achats sans courir. Une information sera distribuée aux habitants qui ne consultent pas les annonces en ligne. Les responsables regarderont si les correspondances et l'emplacement de l'arrêt conviennent réellement. Ils ne souhaitent pas présenter la création de la ligne comme une réponse achevée avant de connaître l'expérience des premiers usagers.","question":"Quel effet est attendu ?","explanation":"Le passage indique : « Un marché rural ajoute un arrêt de navette. Les personnes sans voiture peuvent désormais y venir, sans dépendre d'un voisin disponible. » Cela justifie la réponse : Un accès plus autonome au marché."},{"number":19,"points":15,"correct":"C","options":["Refuser toute comparaison annuelle","Ignorer les dates de floraison","Croiser les observations avant de conclure","Considérer un seul événement comme suffisant"],"passage":"Une association surveille les floraisons chaque année. Une floraison plus précoce sera interprétée avec d'autres observations, pas comme la preuve isolée d'une tendance générale.\n\nLe groupe utilise plusieurs points fixes et conserve les relevés même lorsqu'aucun changement remarquable n'est visible. Les participants peuvent noter les conditions du moment et demander une vérification de leur identification. L'association souhaite construire une série utile, pas seulement recueillir des annonces de phénomènes inhabituels. Les visiteurs découvriront les résultats avec ces limites.","question":"Quelle prudence est exprimée ?","explanation":"Le passage indique : « Une association surveille les floraisons chaque année. Une floraison plus précoce sera interprétée avec d'autres observations, pas comme la preuve isolée d'une tendance générale. » Cela justifie la réponse : Croiser les observations avant de conclure."},{"number":20,"points":21,"correct":"A","options":["Donner de la stabilité avec un suivi","Exiger des résultats immédiats identiques","Réserver les terres aux exploitants déjà installés","Offrir un accès sans aucune règle"],"passage":"Une commune loue des terres à de nouveaux agriculteurs. Le bail laisse du temps pour développer une activité, mais prévoit un suivi des pratiques et des engagements pris. Les candidats présentent leur projet et les moyens dont ils disposent pour le mettre en place. Le service souhaite leur donner le temps d'apprendre le terrain et de préparer leurs débouchés. Les rencontres de suivi permettront d'identifier les difficultés, sans modifier les règles à chaque imprévu. La commune veut une activité viable et cohérente avec les objectifs annoncés, plutôt qu'une installation rapide qui disparaîtrait après une première saison difficile.","question":"Quel équilibre est recherché ?","explanation":"Le passage indique : « Une commune loue des terres à de nouveaux agriculteurs. Le bail laisse du temps pour développer une activité, mais prévoit un suivi des pratiques et des engagements pris. » Cela justifie la réponse : Donner de la stabilité avec un suivi."},{"number":21,"points":21,"correct":"A","options":["Plusieurs changements ont eu lieu simultanément","Les habitants ignorent le lieu de la ferme","Les mesures n'ont jamais été réalisées","Aucun oiseau n'a été observé"],"passage":"Le retour de certains oiseaux près d'une ferme encourage ses habitants. Ils ne l'attribuent pas à une seule mesure : haies, mares et changements de pratiques ont été mis en place ensemble. Les habitants ont participé à plusieurs actions et les changements ne peuvent pas être isolés facilement dans leurs souvenirs. Une association propose de garder des repères communs pour les prochaines années. Les observations resteront utiles, même sans permettre d'affirmer qu'un geste unique explique tout.","question":"Pourquoi rester prudent sur la cause ?","explanation":"Le passage indique : « Le retour de certains oiseaux près d'une ferme encourage ses habitants. Ils ne l'attribuent pas à une seule mesure : haies, mares et changements de pratiques ont été mis en place ensemble. » Cela justifie la réponse : Plusieurs changements ont eu lieu simultanément."},{"number":22,"points":21,"correct":"A","options":["Préserver tout en adaptant à un nouvel usage","Conserver uniquement le nom de la ferme","Reconstruire une copie sans utiliser le bâtiment","Interdire toute activité nouvelle"],"passage":"Un village transforme un ancien bâtiment agricole en atelier partagé. Il conserve la charpente, mais adapte l'accès aux normes actuelles. La conservation ne signifie pas l'absence de modification. Les futurs utilisateurs ont expliqué les espaces nécessaires au rangement, aux machines et à la circulation. Certains éléments seront protégés ou déplacés pour permettre ces activités. Le comité souhaite que les visiteurs puissent encore comprendre l'histoire du bâtiment. Il refuse cependant de confondre respect du lieu et impossibilité d'y travailler autrement.","question":"Quelle démarche est décrite ?","explanation":"Le passage indique : « Un village transforme un ancien bâtiment agricole en atelier partagé. Il conserve la charpente, mais adapte l'accès aux normes actuelles. La conservation ne signifie pas l'absence de modification. » Cela justifie la réponse : Préserver tout en adaptant à un nouvel usage."},{"number":23,"points":21,"correct":"B","options":["Une disparition des responsabilités","Une coordination entre producteurs","L'arrêt de toute production","L'obligation de vendre les mêmes produits"],"passage":"Des agriculteurs proposent une vente collective. Chacun gagne du temps de commercialisation, mais doit accepter des règles communes de présence et de présentation des produits. Les produits de chacun sont identifiés et les ventes suivies dans un document partagé. Les décisions importantes seront discutées avant d'être appliquées. Les agriculteurs veulent que la boutique reste compatible avec leurs périodes de travail sur les terres. Ils devront parfois échanger une permanence ou réduire une présence annoncée.","question":"Quelle contrepartie accompagne le gain de temps ?","explanation":"Le passage indique : « Des agriculteurs proposent une vente collective. Chacun gagne du temps de commercialisation, mais doit accepter des règles communes de présence et de présentation des produits. » Cela justifie la réponse : Une coordination entre producteurs."},{"number":24,"points":21,"correct":"D","options":["Remplacer les fermes par des cartes postales","Ignorer toute intervention humaine","Évaluer uniquement les couleurs","Comprendre les activités qui le façonnent"],"passage":"Un parcours explique les paysages avec les témoignages de travailleurs agricoles. Les champs sont présentés comme des espaces de production et de décisions, pas seulement comme un décor. Les témoins racontent les rythmes de l'année et les raisons de certaines transformations visibles depuis le chemin. Les visiteurs pourront comparer ces récits avec des cartes. Les organisateurs ne demandent pas aux habitants de présenter une campagne idéale ni de justifier chaque choix devant le public.","question":"Quelle lecture du paysage est proposée ?","explanation":"Le passage indique : « Un parcours explique les paysages avec les témoignages de travailleurs agricoles. Les champs sont présentés comme des espaces de production et de décisions, pas seulement comme un décor. » Cela justifie la réponse : Comprendre les activités qui le façonnent."},{"number":25,"points":21,"correct":"D","options":["La moyenne de places libres permet de comparer les capacités lorsque les périodes de pointe concernent les mêmes cultures.","Les semaines où l'entrepôt est presque vide permettent de renoncer à l'agrandissement sans examiner les récoltes.","Des pointes simultanées rendent le partage impossible même si certains volumes peuvent être décalés entre les sites.","Parce qu'une capacité inutilisée sur l'année peut masquer des pointes simultanées où aucun espace n'est disponible."],"passage":"Une coopérative hésite entre agrandir son entrepôt et mieux partager les capacités existantes. Elle réalise d'abord un état des lieux des périodes d'utilisation avant d'investir. Le groupe relève les volumes, les moments de pointe et les marges disponibles dans les bâtiments voisins. Certains espaces semblent vides une partie de l'année, mais leur usage reste important pendant une courte période. La coopérative veut donc regarder l'ensemble du calendrier avant de conclure à une capacité inutile ou insuffisante. Le relevé montre que deux entrepôts ont chacun 30 % de places libres en moyenne, mais qu'ils atteignent leur capacité maximale pendant les mêmes trois semaines de récolte. La coopérative examine si les volumes peuvent être décalés avant de conclure que ces places suffisent.","question":"Pourquoi un taux moyen d'occupation ne permet-il pas à lui seul de décider l'investissement ?","explanation":"D est appuyé par les deux entrepôts simultanément saturés durant trois semaines malgré une moyenne de places libres de 30 %. A attribue aux moyennes une comparabilité suffisante; B ignore la saison des récoltes; C conclut trop vite à l'impossibilité de tout décalage."},{"number":26,"points":21,"correct":"A","options":["Une organisation des soins et des relais doit prolonger l'enthousiasme et les gestes initiaux.","Les tâches d'entretien peuvent être fixées sans tenir compte des absences prévues.","La présence d'un premier jardinier suffira dès lors que les plants ont survécu à leur première saison.","Le nombre de fruits récoltés l'année de plantation permet d'éviter toute répartition ultérieure des tâches."],"passage":"Des habitants veulent planter des arbres fruitiers communs. L'association prévoit aussi qui taillera, arrosera et récoltera. La plantation n'est que le début de l'engagement. Les habitants préparent un calendrier et identifient les personnes pouvant transmettre les gestes nécessaires aux nouveaux participants. Des périodes d'absence doivent aussi être prévues. Le projet ne veut pas dépendre d'un seul jardinier enthousiaste qui s'occuperait de tout sans relais. Les décisions porteront donc sur les plantations et sur les conditions qui permettront de les garder en bon état. Les premières plantations ont bien repris, mais les arbres taillés par une seule personne ont été négligés durant ses vacances. Le groupe répartit désormais les savoir-faire et les remplacements dans un calendrier accessible.","question":"Quelle condition distingue la réussite initiale d'une plantation de sa pérennité ?","explanation":"La plantation n'est qu'un début; les relais et l'entretien assurent la durée. A. Les autres ignorent les absences et soins."},{"number":27,"points":21,"correct":"D","options":["La sécheresse d'août indique le fonctionnement ordinaire du site puisque les épisodes de rétention printaniers sont temporaires.","Le nombre d'espèces recensées en août reflète le fonctionnement annuel, à condition de tenir compte des pluies antérieures.","Une zone sans eau visible ne peut avoir un rôle de rétention que si les mêmes plantes restent en surface.","Elle donne un état ponctuel qui ne permet pas de juger les fonctions saisonnières de la zone."],"passage":"Une zone humide est parfois vide d'eau en été. Des visiteurs la jugent inutile, mais les gestionnaires expliquent que ses cycles saisonniers font partie de son fonctionnement. Les gestionnaires montreront des photographies prises à différents moments et expliqueront les espèces qui utilisent le lieu. Certaines fonctions sont moins faciles à observer pendant une visite courte. Le programme souhaite donner ces repères sans prétendre qu'un état unique serait le bon toute l'année. En été sec, certaines plantes ont disparu en surface; les observations de printemps montrent pourtant que la zone retient temporairement l'eau et accueille d'autres espèces. Le guide demande d'interpréter le lieu sur plusieurs saisons.","question":"Pourquoi l'observation d'une parcelle sèche en août serait-elle insuffisante ?","explanation":"D rappelle qu'un état sec en août ne représente pas les fonctions saisonnières observées au printemps. A et B étendent abusivement la visite estivale à toute l'année; C conditionne la fonction de rétention aux seules plantes visibles."},{"number":28,"points":21,"correct":"B","options":["Écarter toute production rentable pour éliminer définitivement les incertitudes de vente.","Répartir l'exposition économique entre plusieurs activités malgré un coût initial d'adaptation.","Maximiser le rendement immédiat des nouvelles cultures avant d'évaluer leurs débouchés.","Remplacer une dépendance à un acheteur par une dépendance encore plus forte à un seul marché."],"passage":"Un agriculteur réduit une culture très rentable pour diversifier ses productions. Il accepte un gain immédiat moins élevé afin de moins dépendre d'un seul débouché. Il étudie d'autres ventes possibles et réserve du temps pour apprendre les nouvelles cultures. Cette évolution comporte elle aussi des difficultés, qu'il ne veut pas cacher dans son bilan. L'exploitant cherche une organisation moins fragile lorsqu'un prix baisse ou qu'un acheteur se retire. Le prix de sa culture principale avait fortement chuté alors que les deux autres débouchés restaient stables. L'agriculteur accepte les coûts d'apprentissage de nouvelles cultures pour diminuer la part de revenu liée à ce seul marché.","question":"Quel raisonnement justifie l'abandon d'une part de rentabilité à court terme ?","explanation":"La diversification sert à réduire le risque de concentration. B. C/D/A contredisent la logique ou promettent une sécurité absolue."},{"number":29,"points":21,"correct":"D","options":["Une succession d'activités nouvelles indépendantes des traditions déjà pratiquées dans le village.","Un calendrier nouveau qui efface les activités héritées pour faciliter l'arrivée de bénévoles.","Une fête réservée aux personnes connaissant les usages, avec une consultation organisée après l'événement.","Une tradition conservée tout en accueillant des contributions venues de nouveaux habitants du village."],"passage":"Une fête de village donne une place aux nouveaux habitants dans son organisation. Les traditions restent présentes, mais des activités supplémentaires sont proposées après discussion. Les nouveaux bénévoles peuvent participer aux réunions et proposer un rôle correspondant à leurs disponibilités. Les organisateurs souhaitent transmettre les habitudes sans demander de les connaître toutes avant de venir. Le programme final garde des repères familiers et introduit quelques essais. Une activité ancienne est maintenue, mais le parcours de la fête est modifié à la suggestion de nouveaux arrivants pour inclure des habitants jusque-là peu présents. Les anciens bénévoles expliquent les repères historiques sans imposer de les connaître.","question":"Quelle forme de continuité le nouveau programme cherche-t-il à construire ?","explanation":"Le projet maintient des éléments et accepte des modifications discutées. D. B/C/A suppriment cette articulation."},{"number":30,"points":26,"correct":"C","options":["Parce que toutes les campagnes sont désormais définies principalement par leur distance à la ville.","Parce que le monde rural ne subit plus aucun changement depuis l'arrivée des nouveaux métiers.","Parce que services et relations urbaines créent des besoins différents selon les villages.","Parce que la présence d'agriculture empêche d'analyser les autres formes d'activité."],"passage":"L'image d'une campagne immobile masque les transformations des métiers, des techniques et des relations entre habitants. Un chercheur observe ces changements sans en déduire que tous les villages suivent la même trajectoire. La ruralité ne décrit pas une situation unique. Il compare notamment l'accès aux services, les activités et les relations avec les villes proches. Ces éléments aident à comprendre pourquoi une mesure utile dans un village ne produit pas automatiquement le même effet dans tous les autres. Deux villages voisins connaissent des trajectoires opposées: l'un accueille des télétravailleurs grâce au train, l'autre perd une ligne de bus et des services. Une aide identique ne leur donnerait pas les mêmes possibilités.","question":"Pourquoi le chercheur refuse-t-il une mesure rurale universelle ?","explanation":"Les territoires connaissent des changements non uniformes. C; B/A/D simplifient précisément ce que l'enquête distingue."},{"number":31,"points":26,"correct":"C","options":["Elle pénalise les sites qui photographient davantage les opérations de plantation.","Elle tient trop compte du besoin d'arrosage et pas assez du nombre de personnes présentes.","Elle confond l'action initiale financée avec la persistance réelle de ses résultats au fil des saisons.","Elle suppose que des pertes constatées deux ans plus tard prouvent la mauvaise qualité de chaque plant."],"passage":"Une aide agricole dépend du nombre d'arbres plantés. Certains bénéficiaires demandent qu'un suivi de leur survie soit également financé. Compter les plantations sans regarder leur avenir risque de récompenser un geste ponctuel plutôt qu'un effet durable sur le paysage. Elles demandent des moyens pour agir après la photographie du jour de plantation, lorsque la réussite dépend encore de gestes moins visibles mais réguliers. Sur cent jeunes arbres photographiés le jour de la plantation, soixante restent vivants deux ans après dans une commune et quatre-vingt-dix dans l'autre. Le nombre initial identique ne mesure pas l'effet durable recherché.","question":"Quelle limite présente une aide indexée seulement sur le nombre d'arbres mis en terre ?","explanation":"La survie diffère malgré des plantations identiques. C distingue activité et effet; les autres attribuent des causes non établies."},{"number":32,"points":26,"correct":"A","options":["L'origine effective des produits et l'organisation de leur acheminement, indépendamment du nombre d'intermédiaires.","La durée de la relation commerciale, qui garantit l'absence de transports entre régions.","Le nombre de clients de chaque producteur, qui permet de calculer automatiquement la distance des livraisons.","La proportion de ventes faites sans intermédiaire, qui prouve à elle seule la proximité géographique."],"passage":"Un circuit court réduit le nombre d'intermédiaires, mais ne dit pas à lui seul quelle distance parcourt le produit. Un achat direct très éloigné peut demander davantage de transport qu'un produit distribué localement par plusieurs acteurs. Les consommateurs peuvent donc demander où le produit a été fabriqué et comment il est acheminé. Une information claire permettra de comparer les offres sans attribuer à un seul terme des garanties qu'il ne donne pas forcément. Un producteur livre directement ses paniers à 300 kilomètres, tandis qu'un grossiste distribue des pommes provenant de fermes à 20 kilomètres. Le nombre d'acteurs et la distance évoluent donc séparément.","question":"Quel indicateur faudrait-il ajouter à la mention « circuit court » pour comparer les deux offres ?","explanation":"Le circuit court décrit les intermédiaires, non le kilométrage. A demande les données pertinentes; D/C/B produisent des équivalences fausses."},{"number":33,"points":26,"correct":"B","options":["Ils conservent toujours la mesure numérique, les signes du terrain étant purement subjectifs.","Ils confrontent les données du capteur aux observations locales avant de choisir l'arrosage.","Ils suivent l'observation traditionnelle sans examiner la profondeur à laquelle la sonde mesure.","Ils additionnent mécaniquement les deux indications, même si elles concernent des lieux distincts."],"passage":"Des pratiques agricoles se transmettent par l'observation de signes locaux : état du sol, végétation, humidité. Un nouvel outil apporte d'autres données. Les utilisateurs les plus expérimentés ne choisissent pas forcément entre les deux ; ils cherchent comment les confronter utilement. Les producteurs discutent les cas où les deux sources se complètent et ceux où elles semblent se contredire. Une sonde indique un sol encore humide, mais un agriculteur observe une croûte superficielle sur une parcelle voisine. Le groupe vérifie la profondeur et la localisation des mesures avant de choisir l'arrosage.","question":"Comment les producteurs traitent-ils des indications apparemment divergentes ?","explanation":"Le croisement exige de comprendre contexte et limites des sources. B; les autres privilégient ou combinent les indications sans contrôle."},{"number":34,"points":26,"correct":"B","options":["Un déplacement de toutes les exploitations pour garantir aux promeneurs des voies sans véhicules.","Une cohabitation organisée selon les périodes et les contraintes des usages déjà présents.","Une promenade accessible en toutes circonstances, même lorsqu'elle empêche les travaux agricoles nécessaires.","Une priorité systématique aux engins quel que soit l'horaire, sans information donnée aux visiteurs."],"passage":"Une commune aménage des chemins pour les visiteurs, mais les engins agricoles doivent continuer à circuler. Les règles élaborées avec les usagers tiennent compte des périodes de travail. Ouvrir un espace ne signifie pas effacer les activités qui y existaient déjà. Le projet veut rendre les rencontres possibles tout en expliquant pourquoi certaines contraintes ne peuvent pas être décidées uniquement selon le confort des visiteurs. La promenade est très fréquentée en juillet, période où les engins ont aussi besoin d'un passage large pour la récolte. Le comité propose des horaires de circulation affichés plutôt qu'un accès permanent privilégiant une seule activité.","question":"Quel arbitrage les règles d'accès cherchent-elles à rendre possible ?","explanation":"Le partage doit tenir compte des périodes agricoles et des visiteurs. B. C/D/A excluent une partie des usages."},{"number":35,"points":26,"correct":"A","options":["Elle relie les gestes observés aux décisions et aux contraintes qui expliquent la production réelle.","Elle permet aux élèves de comparer les méthodes de travail sans examiner leurs effets sur la production.","Elle rend les visites plus authentiques en montrant exclusivement les imprévus au lieu des pratiques ordinaires.","Elle confirme que les gestes observés ont des conséquences constantes indépendamment des conditions de travail."],"passage":"Des fermes accueillent des classes pour montrer la production alimentaire. Les visites les plus riches ne se limitent pas à une démonstration agréable : elles expliquent aussi les choix difficiles et les incertitudes du métier. Comprendre une activité demande parfois de dépasser son image rassurante. Les responsables souhaitent qu'ils comprennent les liens entre une décision et ses conséquences, au lieu de repartir avec une image agréable mais incomplète d'une journée de travail. Une classe assiste à la traite puis découvre pourquoi la ferme adapte ses pratiques en période de sécheresse. Les élèves posent des questions sur les choix et leurs conséquences au lieu de ne retenir que la démonstration.","question":"Pourquoi la présentation des difficultés professionnelles approfondit-elle la visite ?","explanation":"A relie gestes, choix et contraintes. B sépare artificiellement décisions et conséquences; C remplace une présentation partielle par une autre; D efface les aléas que l'équipe veut faire comprendre."},{"number":36,"points":33,"correct":"A","options":["Préserver des qualités paysagères tout en adaptant certains usages du territoire, pour les besoins actuels des habitants.","La conservation des formes bâties est prioritaire lorsque les usages anciens restent économiquement viables.","Les adaptations contemporaines doivent être déterminées surtout par les besoins immédiats sans relever les traces du passé.","Une rénovation préserve l'aspect d'un lieu seulement si son usage actuel demeure identique à l'ancien."],"passage":"Un projet propose de protéger un paysage en interdisant toute transformation. Les habitants rappellent que ce paysage résulte lui-même de pratiques successives. Ils souhaitent préserver des qualités sans figer les conditions de vie. La conservation d'un territoire habité doit composer avec les besoins de ceux qui continuent à le faire vivre. Certains bâtiments nécessitent de nouvelles fonctions pour rester entretenus, et les exploitants doivent parfois changer leur organisation. Les habitants souhaitent distinguer ces besoins de transformations qui effaceraient sans raison les qualités du lieu. La discussion devra donc examiner des cas concrets et leurs effets. Une règle générale apparemment protectrice peut devenir difficile à vivre si elle traite toute modification comme une dégradation. Les responsables du projet proposent des visites communes pour comprendre les usages présents, les héritages à maintenir et les possibilités d'adaptation compatibles avec la vie du village. Une ancienne grange, remarquable dans le paysage, risque de tomber en ruine sans nouvelle utilisation. Les habitants proposent de conserver son volume extérieur tout en y installant une activité compatible avec les besoins actuels.","question":"Quelle conception de la protection patrimoniale sous-tend cette proposition ?","explanation":"A propose de conserver des qualités tout en adaptant certains usages. B subordonne la préservation à la rentabilité, ce que le cas n'énonce pas; C néglige le patrimoine; D impose un maintien des fonctions refusé par le projet."},{"number":37,"points":33,"correct":"D","options":["Il remplacerait une mesure de production par une mesure de surface, sans inclure les services rendus au territoire.","Il donnerait une image des revenus agricoles mais laisserait inconnues les quantités réellement commercialisées.","Il montrerait une différence de rendement que la contribution des haies suffirait à annuler.","Il négligerait des contributions environnementales et collectives qui ne se reflètent pas directement dans le rendement."],"passage":"Une exploitation est souvent évaluée par son rendement sur une seule culture. Pourtant, elle entretient aussi des haies, partage du matériel et contribue à l'emploi local. Ces fonctions ne justifient pas d'ignorer le rendement, mais elles élargissent les questions à poser. Une performance devient différente selon les dimensions que l'on accepte de compter. Les responsables souhaitent notamment rendre visibles des tâches qui n'apparaissent pas directement dans les volumes vendus. Les comparaisons devront donc préciser ce qu'elles retiennent et les limites du résultat. Une ferme peut présenter des forces et des difficultés différentes selon le domaine observé. Le bilan devient plus utile lorsqu'il aide à discuter ces écarts, plutôt que lorsqu'il transforme un seul chiffre en classement complet de toutes les activités et de leurs effets sur le territoire. Une ferme vend moins de tonnes que sa voisine mais entretient des haies et partage des équipements avec plusieurs exploitations. Le bilan sépare donc production, contribution environnementale et services au territoire.","question":"Pourquoi un classement fondé sur le seul volume vendu serait-il incomplet ?","explanation":"D indique les fonctions écologiques et collectives absentes du seul volume vendu. A reste un indicateur partiel; B confond tonnes et revenus; C suppose une compensation non chiffrée."},{"number":38,"points":33,"correct":"D","options":["Les tâches de distribution deviennent secondaires lorsque les clients passent directement leurs commandes au producteur.","Le lien direct devient plus rentable quand les fonctions commerciales sont confiées exclusivement à chaque exploitation.","Le nombre d'intermédiaires révèle mieux la charge de travail que le temps consacré aux commandes et aux retraits.","Les fonctions demeurent et doivent être assumées ou réparties, même si le circuit commercial change."],"passage":"La vente directe est parfois présentée comme une relation spontanée entre producteur et consommateur. Elle demande pourtant du temps pour accueillir, expliquer et organiser les commandes. Un producteur peut bien cultiver sans souhaiter assurer seul cette activité supplémentaire. Réduire les intermédiaires ne fait pas disparaître les fonctions qu'ils prenaient en charge. Les clients doivent pouvoir connaître les horaires, réserver, obtenir une réponse et récupérer leur commande dans de bonnes conditions. Ces tâches peuvent être partagées ou confiées à un partenaire sans effacer le lien recherché avec les producteurs. Le débat ne porte donc pas seulement sur le nombre d'acteurs entre le champ et le panier. Il concerne aussi la manière dont le travail est réparti et reconnu. Les exploitants souhaitent comparer les solutions avec leur charge réelle, afin qu'une formule présentée comme plus simple pour l'acheteur ne rende pas leur propre activité plus difficile à maintenir. Un producteur augmente ses ventes directes mais passe chaque semaine davantage d'heures à répondre aux messages et à coordonner les retraits. Une solution collective lui permettrait de déléguer ces tâches sans ajouter un intermédiaire inutile au sens du projet.","question":"Que signifie la réduction du nombre d'intermédiaires pour l'organisation du travail ?","explanation":"D rappelle que la suppression d'intermédiaires n'efface pas les fonctions commerciales. A minimise les tâches, B impose leur prise en charge individuelle, C confond structure du circuit et charge effective."},{"number":39,"points":33,"correct":"B","options":["La progression du nombre total de ménages atteste que l'objectif de maintien est atteint, même si les parcours résidentiels individuels ne sont pas suivis.","Le léger gain global doit être rapproché des départs de familles installées et des difficultés de logement, sans prétendre attribuer chaque départ au programme.","Les commerces mieux fréquentés suffisent à apprécier indirectement si les anciens habitants peuvent financer leur logement.","La hausse des déplacements professionnels permet d'attribuer tous les départs des familles aux loyers plus élevés."],"passage":"Un village développe son attractivité pour retenir des habitants. Des services nouveaux apparaissent, mais le prix des logements augmente. Les familles que le projet voulait initialement maintenir peuvent alors rencontrer davantage de difficultés. L'attractivité n'est pas automatiquement synonyme d'accessibilité pour les habitants déjà présents. Les élus doivent donc suivre les coûts du logement en même temps que les arrivées et les recettes nouvelles. Les habitants demandent des possibilités de rester près de leur travail et de leurs proches. Plusieurs solutions seront étudiées, dont des logements accessibles et un maintien de certains services ordinaires. Le programme ne sera pas jugé uniquement à partir d'une image plus attractive ou d'une hausse des visites. Il faudra aussi regarder qui peut encore vivre sur place et dans quelles conditions, afin de comprendre à qui profite réellement le changement annoncé pour l'ensemble du village. Le nouveau café attire des visiteurs et des ménages aisés, mais une famille du village doit quitter son logement après une forte hausse de loyer. Le conseil suit désormais les prix et les départs autant que l'ouverture de services. Pour dresser son bilan, le conseil distingue désormais les nouvelles inscriptions à l'école, les départs de familles déjà installées et les changements de propriétaires. Sur deux ans, le nombre total de ménages augmente légèrement, mais six familles présentes avant le programme sont parties après une hausse de loyer. Trois logements quittés sont occupés par de nouveaux ménages. Le café et les commerces ont gagné des clients, tandis que les salariés aux revenus modestes parcourent en moyenne davantage de kilomètres pour rejoindre leur emploi dans le village. Les élus notent que les dossiers de départ ne permettent pas tous de prouver que le loyer est l'unique motif; certains mentionnent aussi des mutations professionnelles. Le tableau présenté au public sépare donc le solde global de population, la stabilité des habitants antérieurs et les conditions de logement. Les promoteurs du projet souhaitent publier seulement la progression du nombre de ménages, que les associations locales jugent insuffisante.","question":"Quel bilan permet d'apprécier le maintien des habitants sans confondre hausse globale et stabilité des résidents antérieurs ?","explanation":"B distingue une légère hausse du nombre total de ménages du départ de familles déjà présentes et garde une réserve sur les causes. A assimile remplacement et maintien; C infère la capacité résidentielle des recettes commerciales; D attribue tous les départs aux loyers malgré des motifs multiples."}]}$bank_12$::jsonb),
('tcf-reading-13','tcf-reading-2026-11-close-reading-v4',$bank_13${"id":"tcf-reading-13","title":"TCF Reading · Test 13","seconds":3600,"version":"tcf-reading-2026-11-close-reading-v4","maxPoints":699,"questions":[{"number":1,"points":3,"correct":"A","options":["L'impression à l'accueil","L'accès à tous les ordinateurs","Le cours dans la salle fermée","Le prêt d'une imprimante personnelle"],"passage":"La salle informatique sera fermée pour mise à jour mardi matin. L'accueil pourra toujours imprimer vos documents.\n\nLes agents retrouveront le service habituel après les vérifications. Merci de ne pas essayer d'entrer dans la salle pendant l'intervention.","question":"Quel service sera maintenu ?","explanation":"Le passage indique : « La salle informatique sera fermée pour mise à jour mardi matin. L'accueil pourra toujours imprimer vos documents. » Cela justifie la réponse : L'impression à l'accueil."},{"number":2,"points":3,"correct":"B","options":["Publier ses identifiants","Joindre l'assistance par son canal connu","Donner son mot de passe","Rappeler le numéro fourni sans vérification"],"passage":"Votre mot de passe ne vous sera jamais demandé par téléphone. En cas d'appel suspect, contactez directement l'assistance habituelle.\n\nLe numéro figure sur vos documents de service.","question":"Que faut-il faire après un appel suspect ?","explanation":"Le passage indique : « Votre mot de passe ne vous sera jamais demandé par téléphone. En cas d'appel suspect, contactez directement l'assistance habituelle. » Cela justifie la réponse : Joindre l'assistance par son canal connu."},{"number":3,"points":3,"correct":"C","options":["Supprimer la batterie","Acheter un nouveau téléphone","Recharger l'appareil","Imprimer toutes les photos"],"passage":"L'atelier photo accepte les téléphones anciens. Chargez votre batterie avant de venir ; les prises disponibles sont limitées.\n\nLes participants pourront venir avec un modèle qu'ils utilisent déjà au quotidien, sans devoir en acheter un autre.","question":"Quelle préparation est demandée ?","explanation":"Le passage indique : « L'atelier photo accepte les téléphones anciens. Chargez votre batterie avant de venir ; les prises disponibles sont limitées. » Cela justifie la réponse : Recharger l'appareil."},{"number":4,"points":3,"correct":"A","options":["Envoyer","Enregistrer provisoirement","Agrandir le texte","Fermer la fenêtre"],"passage":"Le formulaire peut être enregistré puis repris plus tard. Le bouton « Envoyer » termine la démarche.\n\nUn message confirme ensuite la réception. Avant cette dernière étape, vous pouvez encore relire et corriger les informations saisies dans votre dossier personnel.","question":"Quel bouton finalise le dossier ?","explanation":"Le passage indique : « Le formulaire peut être enregistré puis repris plus tard. Le bouton « Envoyer » termine la démarche. » Cela justifie la réponse : Envoyer."},{"number":5,"points":9,"correct":"D","options":["Empêcher toute modification","Réduire le nombre de participants","Remplacer les fichiers par des appels","Limiter la confusion entre les versions"],"passage":"Je t'enverrai les fichiers par le dossier partagé. Évite les pièces jointes : nous risquerions de travailler sur des versions différentes.\n\nJ'ai préparé des noms de documents simples pour retrouver rapidement le travail de chacun. Nous pourrons discuter des modifications dans la note commune sans multiplier les copies.","question":"Pourquoi utiliser un dossier commun ?","explanation":"Le passage indique : « Je t'enverrai les fichiers par le dossier partagé. Évite les pièces jointes : nous risquerions de travailler sur des versions différentes. » Cela justifie la réponse : Limiter la confusion entre les versions."},{"number":6,"points":9,"correct":"B","options":["Le partage de tous les mots de passe","La non-conservation des codes par l'accompagnateur","L'envoi des codes aux autres participants","La publication des comptes créés"],"passage":"La permanence numérique accompagne les démarches, mais ne conserve pas vos codes. Vous devrez les saisir vous-même.\n\nLe bénévole peut expliquer où trouver une information, mais les données restent sous votre responsabilité. Merci de fermer votre session après la démarche.","question":"Quelle règle protège l'utilisateur ?","explanation":"Le passage indique : « La permanence numérique accompagne les démarches, mais ne conserve pas vos codes. Vous devrez les saisir vous-même. » Cela justifie la réponse : La non-conservation des codes par l'accompagnateur."},{"number":7,"points":9,"correct":"B","options":["Abandonner tout appel","Prolonger l'usage du téléphone","Vendre la batterie neuve","Acheter immédiatement un modèle récent"],"passage":"Mon téléphone fonctionne encore. Je préfère changer sa batterie plutôt que remplacer tout l'appareil.\n\nLe réparateur a vérifié que cette intervention est possible sur mon modèle. Je conserverai aussi mes photos avant de lui laisser l'appareil, par précaution. Je demanderai aussi combien de temps cela prendra.","question":"Quelle décision est prise ?","explanation":"Le passage indique : « Mon téléphone fonctionne encore. Je préfère changer sa batterie plutôt que remplacer tout l'appareil. » Cela justifie la réponse : Prolonger l'usage du téléphone."},{"number":8,"points":9,"correct":"D","options":["Un nouvel ordinateur gratuit","Un examen en salle obligatoire","Une vidéo sans son uniquement","Un texte de la séance"],"passage":"Pour suivre le cours à distance, un casque est conseillé, pas obligatoire. Une transcription écrite sera disponible après la séance.\n\nLes personnes souhaitant revoir un passage pourront le retrouver après la rencontre.","question":"Quel autre support est prévu ?","explanation":"Le passage indique : « Pour suivre le cours à distance, un casque est conseillé, pas obligatoire. Une transcription écrite sera disponible après la séance. » Cela justifie la réponse : Un texte de la séance."},{"number":9,"points":9,"correct":"B","options":["Travailler uniquement la nuit","Mieux maîtriser les interruptions","Supprimer définitivement sa messagerie","Empêcher tous ses proches d'écrire"],"passage":"J'ai désactivé les notifications pendant mes révisions. Je regarderai les messages à des moments choisis.\n\nJe répondrai aux demandes importantes après ma séance de travail. Si une urgence se présente, mes proches savent comment me joindre autrement que par une succession de notifications.","question":"Quel objectif poursuit cette personne ?","explanation":"Le passage indique : « J'ai désactivé les notifications pendant mes révisions. Je regarderai les messages à des moments choisis. » Cela justifie la réponse : Mieux maîtriser les interruptions."},{"number":10,"points":9,"correct":"B","options":["Un appareil acheté neuf","La tablette et son chargeur","Uniquement la housse","Un abonnement téléphonique"],"passage":"Le club prête des tablettes pour le week-end. Elles doivent être rapportées lundi avec leur chargeur.\n\nUne fiche indiquera les précautions et les accessoires remis au départ. Les emprunteurs devront signaler un problème avant de repartir avec le matériel pour un nouveau prêt.","question":"Que faut-il restituer ?","explanation":"Le passage indique : « Le club prête des tablettes pour le week-end. Elles doivent être rapportées lundi avec leur chargeur. » Cela justifie la réponse : La tablette et son chargeur."},{"number":11,"points":15,"correct":"D","options":["Acheter du stockage supplémentaire","Effacer tous les dossiers","Créer des programmes complexes","Acquérir un repère de base"],"passage":"Une association propose une initiation au rangement des fichiers. Les participants apprennent d'abord à retrouver un document avant d'utiliser des fonctions plus avancées.\n\nLe formateur utilise des exemples courants et laisse les personnes choisir un classement qu'elles comprennent. Il montre aussi comment éviter des noms trop semblables et comment reconnaître plusieurs versions d'un même fichier. Les participants essaient ensuite de retrouver un document après avoir fermé le dossier. L'objectif est de vérifier qu'ils possèdent un repère utilisable seuls, pas seulement qu'ils réussissent à suivre une démonstration. Les questions permettront de préparer les séances suivantes selon les usages réellement rencontrés dans leur quotidien personnel ou professionnel.","question":"Quelle priorité est donnée ?","explanation":"Le passage indique : « Une association propose une initiation au rangement des fichiers. Les participants apprennent d'abord à retrouver un document avant d'utiliser des fonctions plus avancées. » Cela justifie la réponse : Acquérir un repère de base."},{"number":12,"points":15,"correct":"A","options":["Si l'accès demandé correspond au service","Si tous les contacts utilisent l'application","Si le logo est suffisamment coloré","Si le téléphone est assez grand"],"passage":"Une application demande l'accès aux contacts pour afficher la météo. Une animatrice explique que cette autorisation n'est pas nécessaire à la fonction annoncée.\n\nLes participants comparent plusieurs exemples pour éviter de penser qu'une application doit toujours recevoir tous les accès proposés. Le but n'est pas de refuser automatiquement chaque service, mais de comprendre la relation entre une fonction et les informations demandées.","question":"Quelle question faut-il se poser ?","explanation":"Le passage indique : « Une application demande l'accès aux contacts pour afficher la météo. Une animatrice explique que cette autorisation n'est pas nécessaire à la fonction annoncée. » Cela justifie la réponse : Si l'accès demandé correspond au service."},{"number":13,"points":15,"correct":"A","options":["Maintenir plusieurs voies d'accès au service","Supprimer les formulaires","Réserver les appels aux informaticiens","Obliger chacun à acheter un ordinateur"],"passage":"Un service municipal conserve un accueil téléphonique en parallèle du portail en ligne. Il ne souhaite pas que l'absence d'équipement empêche une démarche.\n\nLes usagers peuvent consulter les mêmes informations essentielles quel que soit le canal choisi. Le personnel est formé pour expliquer les différences de procédure sans renvoyer systématiquement les personnes vers un ordinateur. Le service souhaite conserver la simplicité du portail pour ceux qui l'utilisent, tout en regardant ce qui reste possible pour les autres. Les responsables suivront les temps d'attente, car une alternative annoncée mais difficile à joindre ne constitue pas nécessairement un accès réel.","question":"Quel objectif est poursuivi ?","explanation":"Le passage indique : « Un service municipal conserve un accueil téléphonique en parallèle du portail en ligne. Il ne souhaite pas que l'absence d'équipement empêche une démarche. » Cela justifie la réponse : Maintenir plusieurs voies d'accès au service."},{"number":14,"points":15,"correct":"D","options":["Rendre les photos publiques","Augmenter automatiquement la qualité des images","Supprimer le besoin de classement","Limiter les conséquences de la perte de l'appareil"],"passage":"Un atelier montre comment sauvegarder ses photos sur un second support. Une copie située seulement sur le téléphone disparaîtrait avec lui en cas de perte.\n\nLes animateurs distinguent une sauvegarde et une simple copie restée dans le même appareil. Les participants apprennent aussi à vérifier qu'ils peuvent ouvrir les documents sur le second support. Le cours ne promet pas qu'une opération unique protégera définitivement tous les fichiers. Il propose une organisation régulière, adaptée au volume et à l'importance des données. Chacun prépare un premier essai avec des images fictives avant de choisir ses propres documents.","question":"À quoi sert la seconde copie ?","explanation":"Le passage indique : « Un atelier montre comment sauvegarder ses photos sur un second support. Une copie située seulement sur le téléphone disparaîtrait avec lui en cas de perte. » Cela justifie la réponse : Limiter les conséquences de la perte de l'appareil."},{"number":15,"points":15,"correct":"C","options":["Le nombre de fenêtres de la salle","Le prix du papier","Le rythme de l'interaction","La couleur du bâtiment"],"passage":"Des habitants testent une nouvelle borne. Ils signalent que les boutons sont lisibles mais que le temps laissé pour répondre est trop court.\n\nCertains habitants ont besoin de relire une consigne ou d'obtenir une explication avant d'appuyer. Les concepteurs avaient surtout testé la borne avec des personnes connaissant déjà les démarches. Ils vont donc revoir le délai et permettre de demander plus de temps. Les essais suivants comprendront des profils différents. L'équipe souhaite distinguer une difficulté liée au contenu et une difficulté produite par le rythme imposé à l'écran.","question":"Quel aspect doit être amélioré ?","explanation":"Le passage indique : « Des habitants testent une nouvelle borne. Ils signalent que les boutons sont lisibles mais que le temps laissé pour répondre est trop court. » Cela justifie la réponse : Le rythme de l'interaction."},{"number":16,"points":15,"correct":"C","options":["Le livre reste acquis pour toujours","L'emprunteur doit imprimer chaque page","Le droit de lecture est temporaire","Le prêt n'a aucune durée"],"passage":"Une bibliothèque prête des livres numériques. Le prêt s'arrête automatiquement à la date prévue ; le document ne devient pas un achat définitif.\n\nLa bibliothèque explique les possibilités de renouvellement et les conditions de téléchargement. Les lecteurs peuvent demander une démonstration s'ils découvrent le service. Les fichiers empruntés ne doivent pas être confondus avec ceux qu'ils ont achetés ailleurs. Les responsables souhaitent que chacun comprenne les droits annoncés avant de commencer un livre, notamment pendant un voyage.","question":"Quelle distinction est précisée ?","explanation":"Le passage indique : « Une bibliothèque prête des livres numériques. Le prêt s'arrête automatiquement à la date prévue ; le document ne devient pas un achat définitif. » Cela justifie la réponse : Le droit de lecture est temporaire."},{"number":17,"points":15,"correct":"C","options":["La couleur du câble","Le nombre de publicités","La possibilité de changer d'outil plus tard","La taille du logo"],"passage":"Une équipe choisit un outil de messagerie après un essai commun. Elle évalue aussi la facilité de quitter le service et d'exporter les données.\n\nLes salariés comparent les formats obtenus et regardent si les conversations utiles restent compréhensibles hors de l'outil. Ils souhaitent éviter une dépendance découverte uniquement au moment du départ. Cette vérification ne signifie pas que le groupe prévoit déjà d'abandonner le service. Elle sert à conserver une marge de décision si les besoins, les tarifs ou les règles changent.","question":"Quel critère dépasse l'usage immédiat ?","explanation":"Le passage indique : « Une équipe choisit un outil de messagerie après un essai commun. Elle évalue aussi la facilité de quitter le service et d'exporter les données. » Cela justifie la réponse : La possibilité de changer d'outil plus tard."},{"number":18,"points":15,"correct":"C","options":["Faire confiance à toute copie visuelle","Télécharger tous les fichiers proposés","Vérifier l'adresse plutôt que le seul aspect","Ignorer les informations du navigateur"],"passage":"Un atelier apprend à repérer l'adresse exacte d'un site. Une page qui ressemble à un service connu peut être hébergée ailleurs.\n\nLes participants observent des exemples fictifs où un détail du nom change alors que le logo paraît familier. Ils apprennent à retrouver le service par un moyen connu plutôt qu'à suivre immédiatement un lien reçu. Le formateur souhaite ralentir le geste lorsque la demande semble inhabituelle. Il ne promet pas une méthode qui remplacerait toute vérification future.","question":"Quelle précaution est enseignée ?","explanation":"Le passage indique : « Un atelier apprend à repérer l'adresse exacte d'un site. Une page qui ressemble à un service connu peut être hébergée ailleurs. » Cela justifie la réponse : Vérifier l'adresse plutôt que le seul aspect."},{"number":19,"points":15,"correct":"D","options":["La publication est obligatoire après réception","Les familles ne peuvent jamais regarder les photos","Toute image de groupe doit être vendue","Recevoir une image ne suffit pas à autoriser sa diffusion"],"passage":"Une école demande aux familles de ne pas diffuser les images de groupe sans vérifier les autorisations. Une photo reçue ne donne pas automatiquement le droit de la publier.\n\nLes organisateurs recueilleront les choix avant le prochain événement et indiqueront quelles images peuvent être utilisées sur les supports du groupe. Les familles pourront poser une question sans devoir se justifier devant tout le monde. L'école veut éviter qu'une habitude de partage transforme un souvenir reçu en autorisation supposée générale.","question":"Quelle limite est rappelée ?","explanation":"Le passage indique : « Une école demande aux familles de ne pas diffuser les images de groupe sans vérifier les autorisations. Une photo reçue ne donne pas automatiquement le droit de la publier. » Cela justifie la réponse : Recevoir une image ne suffit pas à autoriser sa diffusion."},{"number":20,"points":21,"correct":"A","options":["Pour améliorer la conception du service","Pour supprimer automatiquement les dossiers","Pour éviter toute correction","Pour classer publiquement les usagers"],"passage":"Une administration simplifie ses formulaires numériques avec les usagers. Les erreurs fréquentes servent à identifier des consignes peu claires, et pas seulement à constater l'inattention des personnes. Les agents relisent les demandes avec des personnes connaissant peu la procédure. Ils observent où les utilisateurs hésitent et quels mots produisent des interprétations différentes. Le service souhaite garder les informations nécessaires, mais les présenter au moment où elles sont utiles. Les modifications seront testées sur de nouveaux exemples avant d'être généralisées. Un formulaire plus court ne sera pas automatiquement meilleur si les étapes supprimées empêchent encore de comprendre ce qui est demandé.","question":"Comment les erreurs sont-elles utilisées ?","explanation":"Le passage indique : « Une administration simplifie ses formulaires numériques avec les usagers. Les erreurs fréquentes servent à identifier des consignes peu claires, et pas seulement à constater l'inattention des personnes. » Cela justifie la réponse : Pour améliorer la conception du service."},{"number":21,"points":21,"correct":"D","options":["L'impossibilité d'écrire sans internet","Le manque de papier","La disparition obligatoire du fichier","La réunion de modifications concurrentes"],"passage":"Un logiciel permet de travailler sans connexion puis de synchroniser les documents. L'équipe vérifie les conflits de versions lorsque deux personnes ont modifié le même fichier hors ligne. Les documents gardent une trace des changements et les auteurs peuvent expliquer ce qu'ils souhaitaient modifier. Elle veut savoir comment réagir lorsque la réunion automatique des modifications produit un résultat ambigu. Les personnes ne seront pas invitées à considérer tout fichier final comme correct simplement parce qu'une synchronisation s'est terminée sans afficher de message d'erreur.","question":"Quel problème doit être géré ?","explanation":"Le passage indique : « Un logiciel permet de travailler sans connexion puis de synchroniser les documents. L'équipe vérifie les conflits de versions lorsque deux personnes ont modifié le même fichier hors ligne. » Cela justifie la réponse : La réunion de modifications concurrentes."},{"number":22,"points":21,"correct":"B","options":["Le classement chronologique des dates","La concentration de l'attention sur quelques avis","L'apparition de nouveaux commentaires","La possibilité de lire les avis récents"],"passage":"Une plateforme affiche les avis dans l'ordre de publication plutôt que selon leur popularité. Elle souhaite éviter que les premiers avis très appréciés occupent durablement toute la visibilité. Les lecteurs pourront toujours rechercher un ancien avis ou examiner les réponses reçues. Le changement ne garantit pas que toutes les contributions seront lues autant, mais modifie ce qui apparaît en premier. La plateforme souhaite expliquer cette règle pour que le classement ne soit pas interprété comme une mesure neutre de qualité.","question":"Quel effet cherche-t-elle à limiter ?","explanation":"Le passage indique : « Une plateforme affiche les avis dans l'ordre de publication plutôt que selon leur popularité. Elle souhaite éviter que les premiers avis très appréciés occupent durablement toute la visibilité. » Cela justifie la réponse : La concentration de l'attention sur quelques avis."},{"number":23,"points":21,"correct":"A","options":["Conserver ses documents avant de partir","Transférer les fichiers sans accord à la publicité","Interdire la suppression du compte","Rester abonné sans le savoir"],"passage":"Un service propose de supprimer un compte tout en permettant de récupérer ses documents auparavant. Cette étape évite de confondre départ du service et perte souhaitée de tous les fichiers. La procédure indique les formats disponibles et demande de vérifier les copies avant la fermeture définitive. Les utilisateurs disposent d'un délai pour poser une question. Le service souhaite que le départ reste compréhensible, sans confondre fidélisation et difficulté à récupérer son travail.","question":"Quelle possibilité est offerte ?","explanation":"Le passage indique : « Un service propose de supprimer un compte tout en permettant de récupérer ses documents auparavant. Cette étape évite de confondre départ du service et perte souhaitée de tous les fichiers. » Cela justifie la réponse : Conserver ses documents avant de partir."},{"number":24,"points":21,"correct":"B","options":["Remplacer tous les échanges par le silence","Choisir le moyen de communication selon l'usage","Éviter toute trace écrite","Imposer une caméra permanente"],"passage":"Une entreprise réduit le nombre de réunions vidéo, mais conserve des échanges audio et des notes partagées. Le but est d'adapter le support au besoin, pas d'interdire la communication à distance. Les équipes précisent ce qui demande un échange immédiat et ce qui peut être lu plus tard. Elles souhaitent éviter qu'un changement d'outil augmente simplement le nombre de messages ou d'interruptions. Le bilan regardera donc l'organisation complète du travail.","question":"Quel principe guide le changement ?","explanation":"Le passage indique : « Une entreprise réduit le nombre de réunions vidéo, mais conserve des échanges audio et des notes partagées. Le but est d'adapter le support au besoin, pas d'interdire la communication à distance. » Cela justifie la réponse : Choisir le moyen de communication selon l'usage."},{"number":25,"points":21,"correct":"B","options":["Elle établit que les comptes personnels sont inutiles pour chaque exercice avancé.","Elle permet de comprendre l'usage avant de décider quelles données transmettre.","Elle supprime définitivement le besoin d'expliquer la collecte de données du service.","Elle garantit qu'aucune information n'est recueillie lors d'une utilisation ultérieure."],"passage":"Des formateurs utilisent des exercices sans compte personnel pour les premières séances. Les apprenants peuvent découvrir les fonctions avant de transmettre des informations les concernant. Les personnes peuvent décider à partir d'une expérience concrète, plutôt que remplir immédiatement une longue série de champs. Le centre veut que la découverte d'un outil ne soit pas conditionnée à une transmission de données dont l'utilité reste encore difficile à comprendre pour un débutant. À la troisième séance, certains choisissent d'ouvrir un compte après avoir essayé l'outil; d'autres préfèrent encore un exercice anonyme. Le formateur explique quelles fonctionnalités exigent réellement des informations personnelles.","question":"Pourquoi l'inscription différée renforce-t-elle la qualité du choix de l'apprenant ?","explanation":"L'apprenant comprend avant de décider d'inscrire ses données. B. D/C/A généralisent au-delà du choix progressif."},{"number":26,"points":21,"correct":"D","options":["La présentation des critères interdit à l'utilisateur de choisir un trajet plus lent.","La destination est choisie automatiquement dès que la durée de trajet est calculée.","Le trajet recommandé devient adapté à tous les usagers lorsqu'ils connaissent les critères.","Un trajet optimisé pour la rapidité peut ignorer les contraintes de certains utilisateurs."],"passage":"Une application propose une recommandation automatique de trajet. Elle affiche aussi les critères retenus pour que l'utilisateur comprenne pourquoi un parcours est privilégié. L'utilisateur peut alors décider si le gain de temps annoncé correspond à sa situation. Il peut choisir un trajet différent lorsqu'un critère non retenu lui paraît plus important. Des retours permettront d'améliorer les informations et d'identifier les contraintes fréquentes que le service n'avait pas encore correctement prises en compte dans ses premières propositions. Le trajet le plus rapide proposé comporte des escaliers, alors que l'usager transporte une poussette. En lisant les critères, il comprend pourquoi cette option a été proposée et privilégie une autre route.","question":"Quelle limite l'explication des critères permet-elle de gérer ?","explanation":"Un trajet rapide peut ne pas convenir aux contraintes non intégrées. D. B/C/A décrivent des comportements absents."},{"number":27,"points":21,"correct":"D","options":["Demander aux jeunes d'abandonner toutes les pratiques en ligne avant d'apprendre à les vérifier.","Les récits des adolescents sont utiles surtout pour indiquer aux familles les pratiques auxquelles elles devront mettre fin.","Chaque exemple doit conduire à identifier une responsabilité individuelle avant la discussion sur les moyens de vérification.","Permettre une analyse collective des risques et des ressources d'aide à partir de situations effectivement rencontrées."],"passage":"Une médiathèque accueille des adolescents pour discuter de leurs pratiques en ligne. Les animateurs partent de situations concrètes plutôt que d'un discours présentant tous les usages comme dangereux. Les participants parlent de leurs habitudes, mais aussi des moments où ils ont besoin d'aide ou de recul. Les questions seront reprises lors d'une séance suivante avec les familles intéressées, dans un cadre respectant les choix de chacun. Un jeune explique avoir partagé une image sans vérifier son origine; les autres discutent de moyens de contrôle sans réduire la séance à la recherche d'un coupable. Les familles reçoivent ensuite des pistes adaptées.","question":"Quel bénéfice l'approche fondée sur des exemples vécus cherche-t-elle à produire ?","explanation":"D utilise des cas vécus pour analyser collectivement les risques et les ressources d'aide. A en fait d'abord une liste de pratiques à interdire; B transforme les récits en consignes aux familles; C impose une désignation individuelle de responsabilité que les animateurs évitent."},{"number":28,"points":21,"correct":"C","options":["Les essais menés avec un lecteur d'écran rendent inutiles les vérifications auprès des autres visiteurs.","Une amélioration de l'accessibilité profite nécessairement à tous dans exactement les mêmes proportions.","Certaines modifications facilitent plusieurs parcours, sans prouver qu'elles résolvent toutes les situations d'accès.","Les difficultés spécifiques disparaissent dès que les menus sont plus explicites."],"passage":"Un site simplifie ses menus après des tests avec des lecteurs d'écran. Les améliorations facilitent aussi la navigation de nombreux autres visiteurs. Les menus deviennent plus prévisibles et les formulaires plus explicites. Certains visiteurs sans outil particulier disent aussi trouver plus rapidement la bonne page. Elle observe leurs effets sur des parcours variés, tout en continuant à vérifier les besoins spécifiques qui ne seraient pas résolus par une modification générale de la présentation. Des essais montrent que les intitulés de boutons devenus plus explicites aident un utilisateur de lecteur d'écran et une personne sans handicap qui découvre le site. Les besoins plus spécifiques font toutefois l'objet de tests distincts.","question":"Quelle conclusion est justifiée par ces deux observations ?","explanation":"Les bénéfices sont transversaux mais non exhaustifs. C conserve les deux nuances; B/D sur-généralisent, A écarte le suivi."},{"number":29,"points":21,"correct":"C","options":["La limitation du nombre de fonctions rend impossible une approche autonome du numérique.","La découverte de fonctions secondaires n'a d'intérêt que si les participants maîtrisent déjà toute l'interface.","Une tâche concrète rend les gestes compréhensibles et révèle les difficultés rencontrées, en pratique.","Une démarche réelle prouve que les participants n'auront plus besoin d'aide lors des tâches suivantes."],"passage":"Une association organise des ateliers en petits groupes. Les questions techniques y sont liées à une tâche réelle, comme retrouver un justificatif, afin d'éviter des manipulations sans objectif compréhensible. Les participants peuvent expliquer les étapes qu'ils comprennent et celles où ils ont besoin d'un soutien. Les formateurs évitent de multiplier les fonctions avant que la première démarche soit maîtrisée. Pour apprendre à joindre un justificatif, les participants accomplissent leur propre démarche guidée. Le formateur note où chacun se bloque, puis introduit la fonction suivante lorsqu'elle devient nécessaire.","question":"Pourquoi le formateur ne commence-t-il pas par présenter toutes les fonctionnalités ?","explanation":"Le contexte réel donne sens aux gestes et ordonne les apprentissages. C; les autres imposent des conditions ou des conclusions absolues."},{"number":30,"points":26,"correct":"A","options":["Un partage trop large peut résulter de paramètres initiaux laissés inchangés par l'utilisateur.","La possibilité pour des utilisateurs de choisir volontairement un partage plus large.","La confusion entre les données nécessaires au service et l'ensemble des informations du compte.","L'absence de tout contrôle ultérieur lorsque le réglage a été sélectionné à l'inscription."],"passage":"Les réglages par défaut influencent les pratiques, car de nombreux utilisateurs ne les modifient pas. Un service choisit donc un partage limité au départ. La possibilité d'élargir ensuite l'accès demeure, mais elle résulte d'une décision explicite. Les explications montrent comment élargir l'accès si une personne le souhaite. Le service veut que cette décision soit compréhensible et réversible, plutôt qu'un changement que l'utilisateur découvrirait après la diffusion de ses informations à un public inattendu. Lors d'un essai, peu d'utilisateurs changent le réglage initial. Ceux qui souhaitent rendre un dossier public disposent néanmoins d'une option clairement expliquée qu'ils peuvent annuler ensuite.","question":"Quel risque le réglage de confidentialité limité par défaut cherche-t-il à réduire ?","explanation":"Les valeurs par défaut influencent les choix réels; limiter l'exposition protège les inattentifs sans supprimer le choix. A."},{"number":31,"points":26,"correct":"C","options":["Elle retire des fonctions peu fréquentes pour accélérer les opérations ordinaires.","Elle place toutes les fonctions sur la page principale afin d'éviter tout apprentissage des menus.","Mettre en avant les tâches courantes tout en gardant l'accès aux fonctions avancées.","Elle limite le service aux utilisateurs novices en supprimant les besoins spécialisés."],"passage":"Une interface peut afficher beaucoup de fonctions et paraître complète. Si les actions courantes sont difficiles à trouver, cette richesse devient un obstacle. Les concepteurs retirent des éléments de l'écran principal sans supprimer les fonctions avancées accessibles ailleurs. Ils souhaitent réduire le temps de recherche, sans décider que les fonctions moins fréquentes ne servent plus à personne ou doivent disparaître du service. Un bouton fréquemment utilisé passe sur l'écran d'accueil, tandis qu'une option experte rejoint un sous-menu clairement identifié. Le nombre total d'actions disponibles reste identique.","question":"Comment l'équipe distingue-t-elle simplification de l'écran et appauvrissement du service ?","explanation":"L'architecture change, non les capacités. C. A/B/D confondent visibilité et disponibilité."},{"number":32,"points":26,"correct":"B","options":["Un format récent élimine le besoin de conserver des informations sur l'origine.","Deux fichiers intacts peuvent devenir illisibles ou perdre leur contexte à long terme.","La numérisation initiale suffit à rendre tout document pérenne sans suivi technique.","Le nombre de copies garantit la possibilité de comprendre la provenance des documents."],"passage":"Une organisation numérise ses archives. Elle doit aussi conserver des descriptions, des formats lisibles et des copies fiables. Transformer un document en fichier ne suffit pas à garantir qu'il pourra être retrouvé et compris dix ans plus tard. Les archivistes contrôlent donc régulièrement les supports et les informations associées. Ils prévoient aussi les changements de format, afin qu'un fichier conservé matériellement ne devienne pas un document impossible à lire ou à interpréter plus tard. Deux fichiers ont des copies intactes dix ans après numérisation. L'un conserve la description de son origine et se lit avec un format maintenu; l'autre a perdu ces informations et ne s'ouvre plus avec les logiciels récents.","question":"Quelle distinction illustrent les deux fichiers conservés ?","explanation":"Un fichier intact peut être illisible ou sans contexte. B. D/C/A attribuent trop au stockage ou au format."},{"number":33,"points":26,"correct":"D","options":["Parce que l'étude de sous-groupes supprime la nécessité d'examiner les exemples initiaux.","Une différence répétée entre groupes prouve une intention de discrimination lors du choix des données de départ.","Un taux global élevé garantit une performance proche pour les sous-groupes si le volume total est important.","Parce qu'un niveau moyen élevé peut masquer des erreurs concentrées sur certains profils de demandes."],"passage":"Un outil automatisé classe les demandes selon les exemples utilisés pour le préparer. Si ces exemples représentent mal certaines situations, l'efficacité moyenne peut masquer des erreurs répétées pour un groupe. Une évaluation doit donc regarder la répartition des erreurs, pas seulement leur total. Ils pourront alors préparer des tests complémentaires, plutôt que publier seulement un taux global encourageant qui laisserait certains problèmes durablement invisibles. Le système affiche 92 % de réponses correctes au total, mais seulement 60 % pour des demandes rédigées dans un format minoritaire. L'équipe vérifie désormais les résultats pour chaque type de cas.","question":"Pourquoi le taux global ne suffit-il pas à juger le dispositif ?","explanation":"D tient compte des 92 % globaux mais aussi du taux de 60 % pour certains formats de demandes. A néglige les exemples de préparation, B suppose une intention discriminatoire non établie et C infère à tort que la moyenne protège tous les sous-groupes."},{"number":34,"points":26,"correct":"A","options":["Elles distinguent l'envoi d'un message d'une attente de disponibilité immédiate, afin de protéger les limites personnelles.","Elles font dépendre la qualité du travail du nombre de réponses envoyées en dehors des heures habituelles.","Elles garantissent que les mêmes horaires de connexion soient imposés à tous les salariés.","Elles permettent de supprimer les messages écrits au profit des seuls échanges en direct."],"passage":"Le travail à distance permet une présence géographique plus souple, mais peut rendre les limites horaires moins visibles. Une équipe définit des temps sans attente de réponse. La souplesse ne signifie pas une disponibilité permanente ; elle demande aussi des règles partagées de déconnexion. Les salariés peuvent ainsi organiser leur journée sans devoir interpréter chaque silence comme un refus de travailler ou chaque message tardif comme une demande immédiate. Un salarié envoie un document tard le soir sans attendre de réponse; un collègue, ignorant cette convention, se croit tenu de répondre. L'équipe inscrit les règles d'urgence et les plages sans réponse attendue.","question":"Pourquoi les règles partagées sont-elles nécessaires malgré la souplesse du télétravail ?","explanation":"Les conventions explicites évitent l'obligation implicite de répondre. A. C/D/B suppriment la flexibilité."},{"number":35,"points":26,"correct":"C","options":["Reproduire les étapes de l'ancienne interface puis rechercher les boutons déplacés sans consulter les consignes.","Attendre les consignes du formateur avant toute navigation pour éviter les erreurs liées aux mises à jour.","Savoir chercher une information pertinente, tester une procédure et contrôler sa validité, après une mise à jour.","Connaître plusieurs emplacements possibles pour chaque fonction sans vérifier leur fonctionnement après le changement."],"passage":"Une formation numérique promet l'autonomie après quelques séances. Les outils changent pourtant rapidement. Les formateurs privilégient donc des repères pour chercher de l'aide, comprendre une consigne et vérifier une information, plutôt qu'une liste de gestes liée à un seul écran. Les personnes pourront réutiliser ces repères lorsqu'une fonction change de place. Le centre veut transmettre une manière de chercher et de vérifier, sans promettre qu'un seul cours rendrait toutes les interfaces futures immédiatement familières et faciles. Une application change l'ordre de ses menus après une mise à jour. Un ancien apprenant retrouve pourtant la procédure en lisant l'aide, en vérifiant les étapes et en contrôlant le résultat.","question":"Quel apprentissage permet de continuer après ce changement ?","explanation":"C correspond à des repères transférables pour rechercher, tester et contrôler. A/D restent centrées sur la mémorisation d'emplacements; B crée une dépendance à l'accompagnateur."},{"number":36,"points":33,"correct":"C","options":["Parce qu'un objectif de consultation longue produit un classement comparable à celui qui privilégie la diversité.","Parce que les données initiales doivent être modifiées dès que la plateforme choisit une autre priorité de classement.","Parce que les priorités du classement influencent les résultats affichés, selon des objectifs de calcul distincts.","Parce que la neutralité dépend principalement du nombre de recommandations affichées et non de leur ordre."],"passage":"Une plateforme présente ses recommandations comme neutres parce qu'elles sont calculées. Pourtant, elle doit choisir ce qu'elle optimise : durée de consultation, diversité ou satisfaction déclarée. Ces objectifs peuvent conduire à des sélections différentes. Un calcul n'efface pas les choix inscrits dans les critères qui le guident. Une recommandation peut être très efficace pour garder un utilisateur longtemps sur un site, sans lui faire découvrir des sources différentes. Une autre peut lui proposer plus de variété, mais demander davantage d'effort au début. Le service doit donc expliquer ses priorités et observer leurs conséquences. Les responsables souhaitent que le public puisse discuter ces choix, plutôt que considérer la formule comme une simple description du monde. La technique apporte des moyens de calcul, mais elle ne décide pas seule de la valeur que l'on attribue à chacun des résultats recherchés. Lors d'un essai, privilégier la durée de consultation fait monter les recommandations de contenus polarisants; privilégier la variété modifie le classement sans changer les données de départ. L'équipe publie les critères de chaque version.","question":"Pourquoi le même jeu de données ne garantit-il pas un classement neutre ?","explanation":"C montre qu'une règle d'optimisation incorpore une priorité qui façonne le classement. A nie l'écart observé, B suppose une modification des données absente, D attribue la neutralité au volume affiché."},{"number":37,"points":33,"correct":"A","options":["Le travail d'assistance déplacé vers les partenaires et l'achèvement réel des démarches par les usagers.","Le nombre de dossiers commencés, même lorsque certaines personnes ne peuvent pas les terminer sans aide.","La réduction des dépenses administratives, indépendamment du temps de soutien requis par les associations.","L'économie de temps enregistrée au guichet, sans considérer les démarches déplacées vers les autres acteurs."],"passage":"Une administration remplace un guichet par une démarche en ligne. Le nombre de dossiers déposés augmente, mais les personnes en difficulté se déplacent désormais vers les associations pour obtenir de l'aide. Une simplification pour le service peut déplacer le travail d'accompagnement vers d'autres acteurs plutôt que le faire disparaître. Les bénévoles expliquent qu'ils doivent apprendre les nouvelles interfaces et accompagner des cas parfois complexes. Cette activité ne figure pas toujours dans les économies annoncées par le service public. Les responsables vont rencontrer les associations pour préciser les difficultés et garder une possibilité d'accueil direct. Ils souhaitent mesurer les démarches menées jusqu'au bout, pas seulement les formulaires commencés. Le bilan devra donc inclure les personnes qui n'ont pas réussi seules et les ressources nécessaires pour les aider, afin de comprendre si le nouveau fonctionnement simplifie réellement l'accès pour l'ensemble du public. Le service annonce un gain de dix minutes par dossier, mais une association consacre désormais vingt minutes à accompagner certaines personnes sur la nouvelle interface. Ces heures ne figurent pas dans le bilan administratif initial.","question":"Quelle information faut-il intégrer pour apprécier le gain de la dématérialisation ?","explanation":"A intègre les tâches transférées et les démarches réellement terminées. B confond commencement et aboutissement; C/D excluent le coût d'assistance observé."},{"number":38,"points":33,"correct":"D","options":["Une information détaillée permet d'accepter plus facilement, même si le refus reste accessible après plusieurs étapes.","Une option de refus demeure suffisamment claire lorsque son emplacement est décrit au bas du formulaire.","La rapidité du consentement révèle une préférence stable, sauf si l'utilisateur choisit de revenir sur sa décision.","Une option de refus présente à l'écran peut rester difficile à exercer selon sa présentation concrète."],"passage":"Un service demande le consentement avant d'utiliser des données, puis présente un formulaire très long dont le refus est difficile à trouver. Le choix existe juridiquement à l'écran, mais l'organisation de la page peut orienter fortement la décision. La présence d'une option ne suffit pas à garantir qu'elle soit aussi facile à comprendre et à exercer que les autres. Les utilisateurs peuvent accepter rapidement pour terminer une tâche urgente, même s'ils auraient préféré limiter l'utilisation de leurs informations. Une association propose donc des choix présentés avec la même lisibilité et un résumé des effets principaux. Les responsables souhaitent conserver les explications détaillées pour ceux qui en ont besoin, sans rendre le refus plus compliqué que l'accord. Les essais seront menés avec des personnes découvrant le service. Deux écrans offrent « Accepter » en gros bouton et « Refuser » derrière plusieurs liens. Lors d'un test, des participants qui souhaitaient limiter leurs données acceptent par impatience; le service rééquilibre la visibilité.","question":"Quelle faiblesse du recueil de consentement ce test met-il en évidence ?","explanation":"D souligne que l'asymétrie de présentation limite le choix réel malgré la présence juridique d'une option. A/B justifient une difficulté d'accès au refus; C attribue trop de sens aux acceptations précipitées."},{"number":39,"points":33,"correct":"A","options":["La reprise des opérations et le rapprochement des résultats après redémarrage, car une procédure de secours ne garantit pas à elle seule la fiabilité finale.","Le temps minimal d'interruption rapporté dans chaque service, puisque les deux équipes ont continué leur travail manuel sans attendre la remise en route du logiciel et ont donc assuré les opérations attendues.","La quantité de travail manuel permet d'évaluer la fiabilité des paramètres informatiques retrouvés après la panne.","La confirmation finale d'un client peut se substituer à la vérification interne des calculs pendant le redémarrage."],"passage":"Un logiciel rend une tâche plus rapide. Les professionnels conservent néanmoins un moyen de travailler en cas de panne et des connaissances pour contrôler les résultats. Ils ne rejettent pas l'automatisation ; ils évitent qu'une commodité se transforme en dépendance sans recours. La maîtrise d'un outil comprend aussi la possibilité de vérifier et de s'en passer temporairement. Des exercices permettent de repérer un résultat inhabituel et de reprendre une tâche avec un autre moyen. Les nouveaux collègues reçoivent ces repères lors de leur arrivée, pour éviter qu'ils disparaissent avec les personnes les plus expérimentées. L'organisation souhaite profiter du gain de temps sans perdre la compréhension de ce qui est réalisé. Le bilan portera donc sur la vitesse, mais aussi sur la capacité à expliquer les décisions et à continuer lors d'un incident. Lors d'une panne, l'équipe exécute une procédure manuelle déjà exercée. À la reprise du logiciel, elle compare les résultats et détecte une anomalie issue d'un paramètre mal réglé. Un audit compare ensuite deux incidents. Lors du premier, l'équipe applique une procédure manuelle et continue le service, mais conserve un ancien paramètre dans le logiciel lors de sa remise en route. Un contrôle croisé découvre l'erreur avant l'envoi des résultats aux clients. Lors du second, la procédure de secours permet également de poursuivre les opérations, mais aucun rapprochement n'est effectué à la reprise; une anomalie de calcul n'est identifiée que par un client plusieurs jours plus tard. Les deux équipes disposent donc d'une capacité minimale de continuité en cas de panne, sans posséder le même niveau de vérification après le redémarrage. Le responsable estime qu'un tableau indiquant seulement les minutes d'interruption masquerait cette différence. Il veut suivre séparément la capacité à terminer les tâches, à expliciter les résultats produits et à détecter les anomalies après rétablissement du système.","question":"Quel indicateur distingue le mieux une simple continuité de service d'une maîtrise vérifiable du processus automatisé ?","explanation":"A associe la capacité de continuer à travailler et la vérification des calculs à la reprise du logiciel. B se limite à l'interruption; C confond volume de travail manuel et bon paramétrage; D remplace à tort le contrôle interne par une détection éventuelle du client."}]}$bank_13$::jsonb),
('tcf-reading-14','tcf-reading-2026-11-close-reading-v4',$bank_14${"id":"tcf-reading-14","title":"TCF Reading · Test 14","seconds":3600,"version":"tcf-reading-2026-11-close-reading-v4","maxPoints":699,"questions":[{"number":1,"points":3,"correct":"B","options":["Vendredi soir obligatoirement","Le mois suivant","Jamais","Avant son envoi"],"passage":"Le journal du quartier recevra vos annonces jusqu'au vendredi midi. Les textes arrivés ensuite paraîtront le mois suivant.\n\nUn message confirmera la réception des annonces retenues. Merci d'indiquer une date et un contact pour permettre aux lecteurs de demander des renseignements.","question":"Quand une annonce tardive sera-t-elle publiée ?","explanation":"Le passage indique : « Le journal du quartier recevra vos annonces jusqu'au vendredi midi. Les textes arrivés ensuite paraîtront le mois suivant. » Cela justifie la réponse : Le mois suivant."},{"number":2,"points":3,"correct":"D","options":["L'accès est réservé aux journalistes","Les lecteurs doivent apporter un article","La réunion est payante","La capacité est limitée"],"passage":"La conférence de rédaction est ouverte aux lecteurs mercredi. Merci de réserver une place ; la salle est petite.\n\nLes personnes inscrites recevront les horaires et le lieu d'accueil.","question":"Pourquoi faut-il réserver ?","explanation":"Le passage indique : « La conférence de rédaction est ouverte aux lecteurs mercredi. Merci de réserver une place ; la salle est petite. » Cela justifie la réponse : La capacité est limitée."},{"number":3,"points":3,"correct":"D","options":["Une attribution à un autre photographe","Toute publicité commerciale","Une vente sans accord","Un travail scolaire"],"passage":"Les photos de l'exposition peuvent être utilisées pour un travail scolaire en citant leur auteur. L'usage commercial nécessite un accord séparé.\n\nLes conditions sont indiquées sur le site avec les noms des photographes.","question":"Quel usage est autorisé sous condition de citation ?","explanation":"Le passage indique : « Les photos de l'exposition peuvent être utilisées pour un travail scolaire en citant leur auteur. L'usage commercial nécessite un accord séparé. » Cela justifie la réponse : Un travail scolaire."},{"number":4,"points":3,"correct":"A","options":["À la mairie","Au guichet de la piscine seulement","Dans chaque train","Uniquement dans les boîtes aux lettres"],"passage":"Le bulletin ne sera pas distribué dans les boîtes aux lettres cette semaine. Il reste disponible à la mairie.\n\nLa rédaction publiera aussi une version numérique pour les lecteurs qui ne peuvent pas se déplacer.","question":"Où peut-on le consulter ?","explanation":"Le passage indique : « Le bulletin ne sera pas distribué dans les boîtes aux lettres cette semaine. Il reste disponible à la mairie. » Cela justifie la réponse : À la mairie."},{"number":5,"points":9,"correct":"C","options":["La taille du fichier uniquement","Le nombre de photos du pont","La date de l'information","Le nom de tous les lecteurs"],"passage":"Je t'ai transmis un article ancien par erreur. Vérifie la date avant de partager l'annonce de fermeture du pont.\n\nLe nouveau texte de la mairie indique que la circulation a déjà repris. Je préfère te prévenir avant que tu organises un autre trajet à partir de mon premier envoi.","question":"Quelle vérification est demandée ?","explanation":"Le passage indique : « Je t'ai transmis un article ancien par erreur. Vérifie la date avant de partager l'annonce de fermeture du pont. » Cela justifie la réponse : La date de l'information."},{"number":6,"points":9,"correct":"D","options":["Une publication automatique intégrale","Un vote sur son identité","Une diffusion sans contact préalable","Une confirmation avec le témoin"],"passage":"Notre podcast accueille des témoignages courts. Nous vous rappellerons avant diffusion pour confirmer les passages retenus.\n\nLes enregistrements seront montés pour rendre les échanges plus faciles à suivre. Vous pourrez poser vos questions sur ce fonctionnement avant de confirmer votre participation au programme.","question":"Quelle étape est prévue ?","explanation":"Le passage indique : « Notre podcast accueille des témoignages courts. Nous vous rappellerons avant diffusion pour confirmer les passages retenus. » Cela justifie la réponse : Une confirmation avec le témoin."},{"number":7,"points":9,"correct":"B","options":["Une annonce uniquement promotionnelle","Un portrait comportant des questions critiques","Un catalogue de prix sans entretien","Un texte rédigé par tous les clients"],"passage":"J'aimerais interviewer un artisan, pas réaliser une publicité. Je lui demanderai aussi quelles difficultés il rencontre.\n\nJe préparerai des questions sur ses choix, ses outils et l'organisation de ses journées. Le lecteur doit pouvoir comprendre son activité, pas seulement connaître les produits qu'il souhaite vendre.","question":"Quel type de contenu est recherché ?","explanation":"Le passage indique : « J'aimerais interviewer un artisan, pas réaliser une publicité. Je lui demanderai aussi quelles difficultés il rencontre. » Cela justifie la réponse : Un portrait comportant des questions critiques."},{"number":8,"points":9,"correct":"B","options":["Supprimer les annonces de service","Rendre les informations urgentes plus visibles","Augmenter le nombre d'alertes sans distinction","Interdire toute discussion"],"passage":"Le groupe de discussion réserve les messages urgents aux informations de service. Les débats généraux se tiennent dans un autre espace.\n\nLes membres pourront continuer à discuter sans rendre difficile la recherche d'une annonce importante au milieu des réactions.","question":"Pourquoi séparer les espaces ?","explanation":"Le passage indique : « Le groupe de discussion réserve les messages urgents aux informations de service. Les débats généraux se tiennent dans un autre espace. » Cela justifie la réponse : Rendre les informations urgentes plus visibles."},{"number":9,"points":9,"correct":"A","options":["Le nom de l'association","Le sujet complet de l'article","Toutes les citations","La date de l'entretien"],"passage":"Merci de corriger le nom de mon association dans l'article. Les propos cités sont exacts ; seule cette mention pose problème.\n\nUne note courte permettra aux lecteurs de retrouver le bon organisme sans modifier le sens de l'entretien.","question":"Quelle correction est demandée ?","explanation":"Le passage indique : « Merci de corriger le nom de mon association dans l'article. Les propos cités sont exacts ; seule cette mention pose problème. » Cela justifie la réponse : Le nom de l'association."},{"number":10,"points":9,"correct":"B","options":["Seuls les élus peuvent témoigner","Un témoignage représente d'abord une expérience individuelle","Chaque récit décrit nécessairement toute la population","Les souvenirs doivent tous être identiques"],"passage":"Nous préparons une émission sur les souvenirs du quartier. Les participants peuvent raconter une expérience personnelle sans prétendre parler pour tous les habitants.\n\nLes personnes pourront aussi préférer un texte ou une photographie à un enregistrement de leur voix pendant la rencontre.","question":"Quelle limite est reconnue ?","explanation":"Le passage indique : « Nous préparons une émission sur les souvenirs du quartier. Les participants peuvent raconter une expérience personnelle sans prétendre parler pour tous les habitants. » Cela justifie la réponse : Un témoignage représente d'abord une expérience individuelle."},{"number":11,"points":15,"correct":"C","options":["Éviter toute lecture critique","Prouver que toute analyse est impossible","Permettre de vérifier le point de départ","Remplacer l'enquête par un titre"],"passage":"Un journaliste publie le document à l'origine de son enquête. Les lecteurs peuvent ainsi distinguer la source et l'analyse qu'il en propose.\n\nLe document est accompagné de sa date et d'une indication sur la manière dont il a été obtenu. Les journalistes expliquent les passages qui leur paraissent importants et les limites de ce qu'ils peuvent en déduire. Les lecteurs peuvent ainsi examiner le raisonnement sans devoir accepter une conclusion sur la seule réputation du média. La rédaction souhaite rendre le travail plus lisible, pas prétendre qu'une source brute supprimerait tout besoin d'analyse ou donnerait automatiquement une interprétation identique à toutes les personnes qui la consultent.","question":"Quel intérêt présente cette publication ?","explanation":"Le passage indique : « Un journaliste publie le document à l'origine de son enquête. Les lecteurs peuvent ainsi distinguer la source et l'analyse qu'il en propose. » Cela justifie la réponse : Permettre de vérifier le point de départ."},{"number":12,"points":15,"correct":"B","options":["Le nom du fabricant du papier","Le moment de la prise de vue","Le prix de l'appareil","La largeur du cadre"],"passage":"Une photographie montre une rue vide à l'aube. Utilisée pour illustrer l'activité de toute la journée, elle peut donner une impression trompeuse.\n\nLa légende devrait préciser les conditions et éviter de présenter ce moment comme représentatif de toutes les heures. Des observations complémentaires pourraient montrer les variations de fréquentation. Les élèves de l'atelier comparent plusieurs usages de la même image et discutent des impressions produites.","question":"Quelle information manque pour l'interpréter ?","explanation":"Le passage indique : « Une photographie montre une rue vide à l'aube. Utilisée pour illustrer l'activité de toute la journée, elle peut donner une impression trompeuse. » Cela justifie la réponse : Le moment de la prise de vue."},{"number":13,"points":15,"correct":"A","options":["Éviter une confusion temporelle","Augmenter le volume sonore","Interdire la rediffusion","Cacher l'origine du programme"],"passage":"Une radio locale rediffuse une émission en signalant clairement sa date initiale. Les informations pratiques anciennes ne doivent pas être prises pour des annonces actuelles.\n\nLe présentateur rappelle également le contexte avant les passages consacrés aux services du quotidien. Certaines questions restent intéressantes longtemps, mais des horaires ou des procédures peuvent avoir changé depuis l'entretien. Elle souhaite conserver la valeur des archives sans encourager des démarches à partir d'une information devenue ancienne. Les auditeurs pourront retrouver la version d'origine, avec les précisions permettant de la distinguer d'une annonce nouvelle destinée au public de cette semaine.","question":"Pourquoi afficher cette date ?","explanation":"Le passage indique : « Une radio locale rediffuse une émission en signalant clairement sa date initiale. Les informations pratiques anciennes ne doivent pas être prises pour des annonces actuelles. » Cela justifie la réponse : Éviter une confusion temporelle."},{"number":14,"points":15,"correct":"D","options":["Désigner un titre sans lire","Éviter toute comparaison","Mémoriser tous les titres","Identifier un choix de présentation"],"passage":"Un atelier compare deux titres portant sur le même rapport. Les participants repèrent les aspects sélectionnés et ceux qui ne sont pas mentionnés.\n\nLes groupes lisent ensuite les extraits correspondants pour voir ce que chaque titre permet réellement d'affirmer. Un titre peut être exact tout en donnant la priorité à un aspect particulier. Les animateurs souhaitent que les lecteurs apprennent à reconnaître ce travail de sélection, sans conclure que toutes les formulations sont nécessairement trompeuses. Les participants proposeront une autre version et expliqueront leur choix.","question":"Quelle compétence est travaillée ?","explanation":"Le passage indique : « Un atelier compare deux titres portant sur le même rapport. Les participants repèrent les aspects sélectionnés et ceux qui ne sont pas mentionnés. » Cela justifie la réponse : Identifier un choix de présentation."},{"number":15,"points":15,"correct":"C","options":["La taille des bureaux","Le poids du papier","La nature des textes publiés","La profession de tous les abonnés"],"passage":"Une rédaction distingue les tribunes d'opinion des enquêtes d'information. Les rubriques ne demandent pas au lecteur la même manière d'évaluer les arguments.\n\nLes tribunes peuvent défendre une position et doivent être lues comme des arguments signés. La rédaction précise cependant que la séparation des rubriques ne dispense pas de vérifier une affirmation lorsqu'elle apparaît dans un texte d'opinion. Le journal souhaite rendre sa présentation plus claire, sans créer une catégorie dans laquelle les auteurs pourraient affirmer n'importe quoi en se contentant de rappeler que le texte exprime leur point de vue personnel.","question":"Quelle distinction est rendue visible ?","explanation":"Le passage indique : « Une rédaction distingue les tribunes d'opinion des enquêtes d'information. Les rubriques ne demandent pas au lecteur la même manière d'évaluer les arguments. » Cela justifie la réponse : La nature des textes publiés."},{"number":16,"points":15,"correct":"A","options":["La transparence sur les rectifications","L'effacement de toute responsabilité","La suppression de toutes les archives","L'interdiction de signaler une erreur"],"passage":"Le journal rectifie un chiffre et explique l'erreur dans une note. Il conserve une trace de la correction au lieu de modifier silencieusement l'article.\n\nLa note indique ce qui a changé et pourquoi l'équipe a retenu la nouvelle valeur. Les lecteurs peuvent ainsi comprendre si la correction modifie ou non la conclusion générale. La rédaction ne souhaite pas garder une donnée fausse simplement pour ne pas attirer l'attention sur l'incident. Elle veut aussi éviter qu'une modification invisible empêche de suivre le parcours d'une information déjà citée ailleurs.","question":"Quel principe applique-t-il ?","explanation":"Le passage indique : « Le journal rectifie un chiffre et explique l'erreur dans une note. Il conserve une trace de la correction au lieu de modifier silencieusement l'article. » Cela justifie la réponse : La transparence sur les rectifications."},{"number":17,"points":15,"correct":"C","options":["Le refus de consulter les habitants","Le remplacement du projet par une rumeur","Le recueil de points de vue indépendants de l'annonce","La copie exacte de la publicité"],"passage":"Un communiqué annonce un projet municipal. Avant de le reprendre, une journaliste interroge aussi les personnes concernées par ses effets.\n\nLa journaliste recueille les réactions des riverains et consulte des documents sur des réalisations comparables. Elle veut distinguer les intentions et les effets encore à vérifier. Les responsables du projet pourront répondre aux questions, mais leur présentation ne sera pas traitée comme un bilan déjà établi. Le journal souhaite que les lecteurs comprennent ce qui est annoncé et ce qui reste incertain.","question":"Quelle démarche complète le communiqué ?","explanation":"Le passage indique : « Un communiqué annonce un projet municipal. Avant de le reprendre, une journaliste interroge aussi les personnes concernées par ses effets. » Cela justifie la réponse : Le recueil de points de vue indépendants de l'annonce."},{"number":18,"points":15,"correct":"D","options":["La longueur du titre","Le prix de l'abonnement","La couleur du graphique","La taille du groupe interrogé"],"passage":"Un média publie des statistiques accompagnées du nombre de répondants. Un résultat fondé sur un petit groupe demande davantage de prudence dans sa généralisation.\n\nLe média précise aussi comment les personnes ont été choisies et dans quelles conditions elles ont répondu. Les journalistes souhaitent éviter qu'un pourcentage donne une impression de précision supérieure à celle des données. Le chiffre peut rester utile pour décrire les répondants, sans représenter automatiquement une population plus vaste. Les lecteurs pourront consulter les limites annoncées et comparer avec d'autres travaux.","question":"Quelle information aide à juger la portée du résultat ?","explanation":"Le passage indique : « Un média publie des statistiques accompagnées du nombre de répondants. Un résultat fondé sur un petit groupe demande davantage de prudence dans sa généralisation. » Cela justifie la réponse : La taille du groupe interrogé."},{"number":19,"points":15,"correct":"C","options":["Une experte ne peut avoir aucune préférence","Le métier suffit à valider toute opinion","Toutes ses opinions n'ont pas le même fondement d'expertise","Les connaissances interdisent les questions"],"passage":"Une émission invite une experte sur son domaine de recherche. Le présentateur distingue ses connaissances professionnelles de ses préférences personnelles.\n\nL'invitée peut indiquer les résultats qu'elle connaît et préciser les questions qui dépassent son travail. Le présentateur souhaite éviter de transformer une qualité professionnelle réelle en autorité générale sur tous les sujets. Les auditeurs recevront des références pour approfondir les éléments scientifiques abordés. Les préférences exprimées seront présentées comme telles, afin que chacun puisse apprécier leur statut.","question":"Pourquoi cette distinction importe-t-elle ?","explanation":"Le passage indique : « Une émission invite une experte sur son domaine de recherche. Le présentateur distingue ses connaissances professionnelles de ses préférences personnelles. » Cela justifie la réponse : Toutes ses opinions n'ont pas le même fondement d'expertise."},{"number":20,"points":21,"correct":"D","options":["Réserver l'article aux spécialistes","Remplacer toutes les preuves par des slogans","Supprimer les informations importantes","Rendre le texte accessible sans effacer ses fondements"],"passage":"Un journal souhaite élargir son lectorat. Il réduit les termes techniques, mais conserve les sources et les explications nécessaires. Simplifier la langue ne signifie pas supprimer ce qui permet de comprendre le raisonnement. Des lecteurs ont participé à la relecture des premiers essais. Ils ont signalé les mots qui gênaient la compréhension et les endroits où une explication manquait. Les journalistes ont ensuite réorganisé certains passages sans retirer les éléments qui permettent de contrôler les affirmations. Le journal souhaite une lecture plus fluide, pas une conclusion qu'il faudrait accepter sans comprendre comment elle a été construite.","question":"Quel équilibre cherche-t-il ?","explanation":"Le passage indique : « Un journal souhaite élargir son lectorat. Il réduit les termes techniques, mais conserve les sources et les explications nécessaires. Simplifier la langue ne signifie pas supprimer ce qui permet de comprendre le raisonnement. » Cela justifie la réponse : Rendre le texte accessible sans effacer ses fondements."},{"number":21,"points":21,"correct":"C","options":["Éviter d'identifier les sujets","Remplacer les informations par des adhésions","Permettre au lecteur d'apprécier leur position","Garantir que toute critique sera supprimée"],"passage":"Des habitants lancent une lettre locale parce que certaines initiatives ne sont jamais couvertes. Ils prévoient toutefois de mentionner leurs liens avec les associations présentées. La lettre indiquera qui a proposé le sujet et si un membre de la rédaction participe à l'activité présentée. Les lecteurs pourront demander d'autres points de vue. Le groupe souhaite conserver sa connaissance du quartier, tout en rendant visibles les relations qui peuvent influencer ses choix. Il ne prétend pas remplacer cette proximité par une absence de position impossible à garantir.","question":"Pourquoi annoncer ces liens ?","explanation":"Le passage indique : « Des habitants lancent une lettre locale parce que certaines initiatives ne sont jamais couvertes. Ils prévoient toutefois de mentionner leurs liens avec les associations présentées. » Cela justifie la réponse : Permettre au lecteur d'apprécier leur position."},{"number":22,"points":21,"correct":"D","options":["Supprimer les vérifications","Remplacer tous les journalistes","Décider du résultat avant l'enquête","Contribuer aux questions à examiner"],"passage":"Une rédaction organise ses reportages selon les questions du public, mais garde la décision sur les vérifications et les sources. La participation des lecteurs nourrit l'enquête sans en fixer d'avance la conclusion. Les journalistes regroupent les propositions, vérifient ce qui peut être étudié et expliquent les sujets qu'ils ne pourront pas traiter immédiatement. Certains lecteurs apportent des documents ou des observations utiles. La rédaction conserve toutefois la responsabilité de confronter ces éléments à d'autres sources.","question":"Quelle place est donnée aux lecteurs ?","explanation":"Le passage indique : « Une rédaction organise ses reportages selon les questions du public, mais garde la décision sur les vérifications et les sources. La participation des lecteurs nourrit l'enquête sans en fixer d'avance la conclusion. » Cela justifie la réponse : Contribuer aux questions à examiner."},{"number":23,"points":21,"correct":"A","options":["Un contexte ajouté de manière erronée","Une image entièrement inventée nécessairement","Une absence de toute scène visible","Une qualité technique trop faible uniquement"],"passage":"Une vidéo très partagée montre une scène réelle, mais le commentaire affirme qu'elle se déroule dans une autre ville. La fausseté ne se trouve pas dans l'image elle-même, mais dans son attribution. Les participants apprennent donc à rechercher l'origine de la vidéo et les publications antérieures. Ils comparent les détails visibles avec les lieux annoncés. Un document réel peut être utilisé pour soutenir une affirmation fausse si le contexte ajouté ne correspond pas à ce qui a été filmé.","question":"Quel problème est identifié ?","explanation":"Le passage indique : « Une vidéo très partagée montre une scène réelle, mais le commentaire affirme qu'elle se déroule dans une autre ville. La fausseté ne se trouve pas dans l'image elle-même, mais dans son attribution. » Cela justifie la réponse : Un contexte ajouté de manière erronée."},{"number":24,"points":21,"correct":"D","options":["Une identité connue doit toujours être publiée","La protection d'une source interdit tout entretien","L'anonymat impose de ne rien vérifier","Anonymat public et absence de vérification ne se confondent pas"],"passage":"Un média refuse de citer une personne de manière anonyme sans en connaître l'identité. Il peut protéger son nom publiquement tout en vérifiant qui fournit l'information. La rédaction évalue les raisons de la protection et cherche des confirmations indépendantes. Elle explique aux lecteurs la portée de ce choix sans révéler les informations permettant d'identifier la personne. L'objectif est de rendre possible un témoignage utile, tout en gardant une exigence de fiabilité.","question":"Quelle différence est faite ?","explanation":"Le passage indique : « Un média refuse de citer une personne de manière anonyme sans en connaître l'identité. Il peut protéger son nom publiquement tout en vérifiant qui fournit l'information. » Cela justifie la réponse : Anonymat public et absence de vérification ne se confondent pas."},{"number":25,"points":21,"correct":"A","options":["Parce que le nombre de partages renseigne sur l'attention, non la fiabilité.","Parce que la fréquence des partages révèle directement la méthode employée par l'auteur.","Parce qu'un contenu largement partagé ne peut être fondé sur une étude consultable.","Parce qu'un message vérifiable circule nécessairement moins vite qu'une information sans source."],"passage":"Un atelier explique qu'un nombre de partages mesure une circulation, pas une exactitude. Une information fausse peut être très visible, et une enquête fiable peu connue. Les participants comparent la circulation de plusieurs messages et cherchent les documents sur lesquels ils s'appuient. Certains contenus attirent surtout parce qu'ils surprennent ou confirment une opinion. Le groupe souhaite distinguer ces raisons de partage du travail nécessaire pour établir un fait. Deux articles circulent largement. Le premier cite une étude dont la méthode peut être consultée; le second reprend une rumeur sans document vérifiable. Le nombre de partages est proche, mais les fondements diffèrent.","question":"Pourquoi l'égalité de diffusion des deux messages ne permet-elle pas de conclure à leur fiabilité comparable ?","explanation":"La circulation et la vérification sont deux critères distincts. A. D/C/B infèrent un lien non établi."},{"number":26,"points":21,"correct":"C","options":["Écarter toutes ses observations car il ne contient pas de données suffisantes pour une moyenne nationale.","Le traiter comme un échantillon représentatif puisque les journalistes ont détaillé les circonstances.","Le traiter comme un cas détaillé sans lui attribuer une portée statistique nationale.","En déduire la part nationale des familles rencontrant le même problème à partir de l'année suivie."],"passage":"Un reportage suit une seule famille pendant une année. Il rend son expérience précise, mais les auteurs ne prétendent pas que toutes les familles vivent la même situation. Les journalistes montrent les choix quotidiens, les hésitations et les changements observés pendant le suivi. Ils présentent aussi les circonstances de cette rencontre, afin de ne pas donner l'illusion d'une famille choisie comme résumé de toute la société. Le reportage peut ainsi rendre sensible une expérience précise. Le reportage montre comment cette famille a modifié son budget après un déménagement. Les journalistes précisent que le récit ne permet pas d'estimer combien de familles vivent une situation similaire.","question":"Quelle utilisation de ce reportage est défendable ?","explanation":"L'étude détaillée d'un cas n'est ni une statistique représentative ni inutile. C. D/B généralisent; A rejette à tort sa valeur descriptive."},{"number":27,"points":21,"correct":"B","options":["Ne retenir que les conclusions les plus populaires afin de représenter l'opinion du public.","Hiérarchiser les affirmations selon l'état des preuves, tout en expliquant les désaccords encore ouverts.","Deux hypothèses qui peuvent être testées doivent recevoir la même place même lorsque leurs preuves diffèrent.","Un temps de parole égal reste acceptable si le présentateur signale brièvement les écarts de documentation."],"passage":"Une émission débat d'un désaccord scientifique. Le producteur distingue une controverse entre spécialistes et une affirmation isolée sans preuve. Donner un temps égal à toute affirmation ne produirait pas forcément une représentation équilibrée des connaissances. Les organisateurs consultent donc des travaux de référence et demandent aux invités de préciser leurs arguments. Ils ne souhaitent pas éliminer le désaccord, mais rendre visible ce qui le soutient. L'un des invités défend une hypothèse appuyée par plusieurs études; un autre avance une objection récente encore peu examinée. Le producteur prévoit de présenter les deux sans laisser croire qu'elles ont le même degré de confirmation.","question":"Quel principe évite une fausse équivalence entre les positions ?","explanation":"B demande d'exposer les désaccords en proportion de leurs fondements scientifiques. A favorise la popularité; C donne le même poids à des hypothèses inégalement étayées; D considère l'égalité du temps suffisante malgré les écarts de preuve."},{"number":28,"points":21,"correct":"C","options":["Il permet à la rédaction de retirer les sources pour alléger la lecture des non-spécialistes.","Il distingue les lecteurs qui disposent de peu de temps de ceux qui sont autorisés à examiner les sources.","Il offre un premier niveau de compréhension tout en maintenant l'accès aux preuves et aux nuances.","Il donne un aperçu suffisant pour affirmer connaître les limites et tous les documents du dossier."],"passage":"Un journal ajoute un résumé au début de ses enquêtes longues. Les lecteurs pressés disposent d'un repère, tandis que les détails restent consultables. La rédaction veut permettre une entrée plus facile dans un sujet complexe. Elle observera aussi si les lecteurs retrouvent les explications dont ils ont besoin. Une lecture rapide reste possible, mais elle ne doit pas être présentée comme nécessairement équivalente à l'examen complet du dossier et de ses limites. Certains lecteurs utilisent le résumé pour décider d'ouvrir le dossier complet, tandis que d'autres ne lisent que l'essentiel. La rédaction indique les limites de l'enquête dans le dossier et évite d'effacer cette possibilité d'approfondissement.","question":"Quelle fonction le résumé remplit-il sans se substituer à l'enquête ?","explanation":"Le résumé facilite l'entrée tout en laissant les détails disponibles. C. D/A/B déforment les degrés de lecture."},{"number":29,"points":21,"correct":"A","options":["Pour expliquer les arbitrages et les options écartées dans la décision.","Pour remplacer le procès-verbal par une liste de désaccords sans résultats.","Pour montrer que les membres absents approuvaient nécessairement les options finalement retenues.","Pour prouver que toutes les propositions étaient équivalentes avant le vote."],"passage":"Une association explique ses décisions dans un bulletin. Elle mentionne aussi les propositions non retenues et leurs raisons, afin que le compte rendu ne paraisse pas présenter un accord unanime fictif. Les membres absents peuvent ainsi comprendre pourquoi une décision a été prise et quelles difficultés ont été discutées. Le bulletin distingue les points d'accord et ceux qui restent ouverts. Le bulletin explique qu'une proposition de financement a été écartée non parce qu'elle manquait de soutien, mais parce qu'une condition juridique empêchait son application. Les membres absents peuvent comprendre la décision malgré ce désaccord.","question":"Pourquoi rendre compte des propositions rejetées ?","explanation":"Les raisons des refus rendent la décision transparente, A. D/B/C effacent les justifications ou inventent un accord."},{"number":30,"points":26,"correct":"D","options":["Vérifier uniquement que la citation provient du même intervenant et de la même date.","Une citation plus courte peut rester fidèle si le propos complet est disponible ailleurs pour les lecteurs.","Le nombre de mots authentiques permet d'évaluer si les restrictions modifient réellement la conclusion citée.","Comparer la formulation complète et les conditions qui déterminent le sens de la conclusion."],"passage":"Une phrase exacte peut devenir trompeuse lorsqu'elle est séparée de la condition qui la limitait. Un atelier demande donc de retrouver le passage complet avant de discuter une citation très courte. Vérifier les mots ne suffit pas toujours à vérifier le sens attribué. Les animateurs proposent des citations dont les mots sont authentiques mais le sens incomplet. Les participants peuvent alors examiner ce qui change lorsque l'on retrouve la question posée et la suite de la réponse. Une chercheuse déclare: « Cette mesure ne réduit pas le risque dans tous les cas. » Le titre d'un message viral ne retient que « Cette mesure réduit le risque » et supprime la négation de portée et la condition.","question":"Quelle vérification manque au lecteur qui confirme seulement que certains mots figurent dans l'entretien ?","explanation":"D exige de confronter la citation à la négation et aux conditions omises dans le passage complet. A ne vérifie que l'origine; B confond disponibilité du contexte ailleurs et fidélité du message viral; C comptabilise des mots sans vérifier le sens."},{"number":31,"points":26,"correct":"A","options":["Diffuser les faits confirmés et différer les annonces encore insuffisamment vérifiées.","Elle retarde toutes les nouvelles, y compris celles déjà vérifiées, jusqu'au lendemain.","Elle publie l'annonce incertaine en laissant aux lecteurs le soin d'en vérifier la source.","Elle refuse de corriger une information publiée avant la vérification complète."],"passage":"La rapidité est devenue un argument des médias. Une rédaction choisit pourtant de retarder une annonce lorsqu'une vérification essentielle manque. Elle ne renonce pas à informer, mais considère que publier avant de savoir peut créer une erreur difficile à corriger ensuite. Elle souhaite conserver une information utile au public, sans transformer le délai de vérification en silence total ni l'urgence de publier en excuse pour affirmer sans preuve. Une information urgente semble plausible mais dépend d'un document que la rédaction n'a pas pu confirmer. Elle publie ce qu'elle a vérifié et réserve l'annonce contestée pour un point ultérieur.","question":"Comment la rédaction concilie-t-elle rapidité et responsabilité ?","explanation":"Elle informe dans la limite de ce qui est confirmé, A. B/C/D ne respectent pas le compromis décrit."},{"number":32,"points":26,"correct":"A","options":["Les valeurs ne changent pas avec l'échelle, mais l'impression de grandeur dépend de la représentation.","La différence numérique est déterminée par la hauteur visuelle des colonnes.","La seconde échelle prouve que la hausse observée est sans conséquence dans tous les contextes.","Le premier est nécessairement faux puisque les axes ne commencent pas tous à zéro."],"passage":"Un graphique commence son axe vertical au-dessus de zéro. Ce choix peut rendre une variation plus visible. Il n'est pas forcément illégitime, mais doit être compris : une impression de rupture spectaculaire peut venir en partie de l'échelle choisie. Les lecteurs peuvent comparer plusieurs échelles à partir des mêmes valeurs. Le cours veut rendre ces choix compréhensibles plutôt que demander de se fier uniquement à l'impression immédiate produite par la hauteur de deux colonnes. Les valeurs passent de 98 à 100. Sur un axe commençant à 97, les colonnes semblent différer énormément; sur un axe commençant à zéro, leur différence paraît modeste. Les nombres eux-mêmes restent identiques.","question":"Quelle distinction permet de lire correctement les deux graphiques ?","explanation":"L'échelle modifie le rendu sans changer les données. A. D/B/C surinterprètent l'aspect visuel."},{"number":33,"points":26,"correct":"C","options":["Elles prouvent qu'une relation ancienne avec un élu rend chaque article favorable à cet élu.","Elles obligent les journalistes à rompre toutes leurs relations locales pour préserver l'indépendance.","Elles permettent de contrôler les informations malgré la proximité des sources, dans chaque article.","Elles rendent inutile toute critique, puisque les informations ont été obtenues par un contact régulier."],"passage":"Un journal local entretient des relations régulières avec les acteurs qu'il couvre. Cette proximité facilite l'accès aux informations, mais peut rendre une critique délicate. L'équipe formalise ses règles pour préserver une indépendance qui ne dépend pas de l'absence totale de contacts. Le journal souhaite que la confiance se construise sur des pratiques visibles, pas seulement sur l'affirmation générale de son indépendance dans une présentation officielle. Une journaliste connaît depuis longtemps les responsables municipaux, ce qui facilite les entretiens. Pour examiner un contrat contesté, elle conserve les documents et les critères de vérification accessibles à ses collègues.","question":"Pourquoi les règles éditoriales explicites comptent-elles dans un contexte de proximité ?","explanation":"La proximité peut aider l'accès tout en créant un risque; des règles vérifiables protègent le jugement. C. B/A/D exagèrent ou nient ce risque."},{"number":34,"points":26,"correct":"B","options":["Une correction doit nécessairement remplacer toutes les archives, même lorsqu'elles documentent le changement.","La correction reste peu utile si les lecteurs initiaux ne la voient pas.","Le public n'accorde jamais d'attention à une information rectifiée dans le même média.","La correction devient moins vraie lorsqu'elle circule après l'article auquel elle répond."],"passage":"Une correction atteint souvent moins de lecteurs que le message initial. Des journalistes réfléchissent donc à la manière de la diffuser auprès du même public. Reconnaître l'erreur constitue une étape ; réparer son effet demande aussi de regarder sa circulation. Elle vérifiera la visibilité du correctif, plutôt que considérer le travail terminé dès qu'une note exacte a été placée dans une rubrique peu consultée. Un correctif discret est publié en fin de journée, mais l'article erroné continue de circuler sous forme de captures d'écran. La rédaction cherche à signaler la correction aux lecteurs exposés au message initial.","question":"Pourquoi publier une note exacte sur une page peu consultée ne règle-t-il pas entièrement l'erreur ?","explanation":"La réparation dépend de la diffusion auprès du public déjà exposé. B; A/D/C sont des affirmations non étayées."},{"number":35,"points":26,"correct":"C","options":["Le témoignage situe la tendance sur le terrain et permet d'en déduire combien de résidents vivent la même situation.","La carte établit le phénomène général tandis que le témoignage en confirme directement l'ampleur dans le quartier.","Les chiffres situent une tendance et le témoignage illustre un effet particulier, dans une expérience de vie singulière.","La carte et le récit donnent deux estimations quantitatives de la même tendance qui peuvent être additionnées."],"passage":"Une enquête associe cartes, témoignages et documents. Aucun support n'épuise le sujet : les chiffres situent une tendance, tandis qu'un récit montre ses conséquences dans une vie. Leur combinaison devient utile si le lecteur comprend ce que chaque élément permet réellement d'affirmer. Le lecteur peut ainsi comprendre comment les éléments se complètent, sans attribuer à une histoire singulière la représentativité d'une enquête ni aux nombres la précision d'un récit individuel. Une carte signale une hausse de fréquentation, tandis qu'un habitant raconte comment cette évolution affecte son trajet. Le journaliste précise qu'un seul témoignage ne mesure pas la proportion d'habitants touchés.","question":"Quelle lecture combine correctement les deux sources ?","explanation":"C distingue la portée de la carte et celle du témoignage individuel. A et B infèrent une représentativité non mesurée par le récit; D traite un récit qualitatif comme une seconde estimation numérique."},{"number":36,"points":33,"correct":"B","options":["L'obligation d'obtenir davantage de documents de référence avant d'inviter des personnes non représentées.","La confusion entre visibilité médiatique et pertinence des personnes touchées par la décision.","La tendance à sélectionner les groupes qui comptent le plus de membres, sans examiner leur rapport au problème.","La difficulté de comparer les expériences des participants lorsque chacun intervient dans un cadre médiatique différent."],"passage":"Une rédaction veut représenter équitablement un débat. Elle invite les acteurs les plus visibles, puis découvre que certains habitants directement concernés ne disposent d'aucun porte-parole organisé. La visibilité publique n'est pas une mesure suffisante de l'importance d'un point de vue dans une situation. Les journalistes vont rechercher ces personnes avec des relais locaux et proposer plusieurs façons de répondre. Certaines ne souhaitent pas intervenir sur un plateau mais peuvent expliquer leur expérience dans un autre cadre. La rédaction veut éviter que son calendrier et ses habitudes de contact ne déterminent seuls les voix entendues. Les acteurs déjà présents ne seront pas écartés pour autant. Le dossier sera construit à partir des intérêts en jeu et des personnes concernées, plutôt qu'à partir d'une liste de porte-parole faciles à joindre et habitués à parler dans les médias. Les invités habituels sont facilement joignables, mais les travailleurs concernés par le nouveau règlement n'ont pas d'organisation qui les représente. Le journal prévoit des entretiens hors studio pour entendre leurs expériences.","question":"Quel biais de sélection la rédaction tente-t-elle de corriger ?","explanation":"B désigne le biais de visibilité médiatique, qui écarte des personnes directement touchées. A confond vérification et sélection; C remplace visibilité par taille des groupes; D évoque une question de comparaison, non l'absence de voix."},{"number":37,"points":33,"correct":"B","options":["Une sélection de sujet ne peut être jugée rigoureuse que si la rédaction ne rend pas publics ses critères.","Discuter du choix des sujets tout en vérifiant les faits à partir de sources consultables.","La transparence des priorités éditoriales rend secondaires les preuves citées pour établir les faits.","L'existence de sources vérifiables garantit que la sélection des sujets ne reflète aucune priorité éditoriale."],"passage":"Un média explique ses choix de sujets. Certains lecteurs y voient un aveu de subjectivité qui invaliderait toute information. La rédaction répond que sélectionner est inévitable, mais que les critères peuvent être discutés et les faits vérifiés. Reconnaître un point de vue de travail ne revient pas à déclarer que toutes les affirmations se valent. Elle présente les critères qui l'ont conduite à suivre un événement et les moyens utilisés pour vérifier les informations. Les lecteurs peuvent contester ces choix ou proposer des sujets absents. La rédaction souhaite conserver cette discussion sans confondre critique des priorités et rejet de toute possibilité d'établir des faits. Certaines questions restent ouvertes, d'autres peuvent recevoir des réponses mieux appuyées que de simples impressions. Les sources restent consultables. Le média explique pourquoi il suit un conflit local et met à disposition les documents qu'il cite. Des lecteurs peuvent discuter du choix du sujet, tout en vérifiant séparément si un fait précis est étayé.","question":"Quel rapport la rédaction établit-elle entre sélection éditoriale et vérification ?","explanation":"B sépare la discussion des priorités et la vérification des faits. A et D attribuent à la sélection des propriétés infondées; C rend les preuves secondaires alors qu'elles sont maintenues."},{"number":38,"points":33,"correct":"A","options":["Présenter un accès local et conditionnel comme universel, sans préciser les communes ni les dates concernées.","Elle transformait une condition administrative secondaire en une restriction décisive dont le public ne pouvait comprendre l'origine.","Elle risquait de décourager les lecteurs en donnant trop de place à des critères géographiques clairement définis.","Elle présentait une offre trop limitée alors que les possibilités d'inscription étaient plus larges que prévu."],"passage":"Une campagne de communication cherche un message très simple. Les responsables retirent successivement les réserves jusqu'à produire une promesse plus forte que le projet réel. La clarté devient trompeuse lorsqu'elle efface précisément les conditions qui déterminent la validité de ce qu'elle annonce. L'équipe compare la formule finale aux engagements réellement possibles et réintroduit les limites importantes. Elle veut garder un message lisible, mais aussi permettre au destinataire de savoir si l'offre correspond à sa situation. Des exemples courts peuvent parfois être plus utiles qu'une promesse très large suivie d'une longue liste de réserves difficiles à trouver. Le projet sera donc présenté avec ses conditions principales au même endroit. La communication ne remplace pas la réalisation, mais elle influence les attentes à partir desquelles les personnes jugeront ensuite ce qui a effectivement été fait. Le message publicitaire initial annonce « disponible pour tous ». Le service est en réalité réservé aux résidents de trois communes à certaines dates. L'équipe réintroduit ces conditions à proximité de l'annonce.","question":"Quelle erreur la version initiale du message risquait-elle de produire ?","explanation":"A constate qu'une promesse générale omettait des critères d'accès essentiels. B minimise faussement ces critères, C suppose qu'ils étaient détaillés, D inverse l'écart entre annonce et offre réelle."},{"number":39,"points":33,"correct":"B","options":["Les réactions initiales sont un indicateur de valeur éditoriale fiable, mais elles doivent être ajustées au nombre de consultations différées.","L'intérêt durable peut échapper au classement initial, sans que ces observations prouvent l'effet qu'aurait eu un autre algorithme sur l'audience.","Les visites tardives montrent que le classement algorithmique avait empêché la seconde enquête de rejoindre son public.","L'exemple de deux enquêtes démontre que les lecteurs préfèrent généralement les analyses longues aux textes suscitant des réactions rapides."],"passage":"Les plateformes recommandent souvent des contenus suscitant une réaction rapide. Une enquête complexe demande au contraire du temps avant de produire une conclusion. Évaluer tous les contenus par la réaction immédiate risque de défavoriser des formes d'information dont l'intérêt apparaît au cours d'une lecture attentive. Le média expérimente des présentations qui aident à entrer dans ces sujets sans les réduire à une formule provocante. Il observe aussi les lectures achevées et les retours plus tardifs. Les responsables souhaitent éviter qu'un travail utile mais lent à produire une réaction soit systématiquement moins visible. Ils ne demandent pas d'ignorer l'intérêt du public. Ils cherchent d'autres manières de le comprendre, en tenant compte du temps nécessaire pour découvrir une question complexe. Les choix de recommandation doivent ainsi être discutés avec les effets qu'ils produisent sur les informations accessibles, pas seulement avec le nombre de clics obtenus dans les premières secondes. Une enquête soigneusement vérifiée reçoit peu de clics le premier jour mais est largement lue et discutée les semaines suivantes. Les responsables envisagent un indicateur de lecture achevée et des retours différés. Le média suit ensuite deux enquêtes comparables publiées à un mois d'intervalle. La première reçoit beaucoup de réactions dans les deux premières heures, puis presque aucune lecture menée jusqu'au bout. La seconde reçoit peu de réactions initiales, mais ses lectures achevées progressent pendant trois semaines et plusieurs associations la citent lors de réunions publiques. Les responsables observent aussi que certaines visites tardives proviennent de partages entre lecteurs et non des recommandations automatiques. Ils ne disposent pas d'une expérience où le même article aurait été recommandé selon deux règles différentes. Ils évitent donc de présenter la seconde enquête comme la preuve qu'un autre algorithme augmenterait nécessairement son audience. Ils veulent plutôt savoir si l'indicateur retenu pour classer les articles capture la forme d'attention qu'ils cherchent à favoriser, au lieu de confondre toute consultation tardive avec une réaction immédiate manquée.","question":"Que montre le rapprochement des deux enquêtes, et quelle conclusion serait excessive ?","explanation":"B constate que l'attention durable peut apparaître tard tout en refusant d'attribuer à un algorithme un effet non testé. A surestime la réaction immédiate; C en déduit un blocage algorithmique non prouvé; D généralise la préférence de tous les lecteurs à partir de deux articles."}]}$bank_14$::jsonb);
do $activate$ declare updated_rows integer; begin
 if (select count(*) from academy_tcf_reading.papers b join academy_tcf_reading.papers old on old.id=b.id and old.version='tcf-reading-2026-11-reference-v3'
 where b.id in ('tcf-reading-07','tcf-reading-08','tcf-reading-09','tcf-reading-10','tcf-reading-11','tcf-reading-12','tcf-reading-13','tcf-reading-14') and b.version='tcf-reading-2026-11-close-reading-v4'
 and (select jsonb_agg(value order by ord) from jsonb_array_elements(b.content->'questions') with ordinality t(value,ord) where ord<=24)
 = (select jsonb_agg(value order by ord) from jsonb_array_elements(old.content->'questions') with ordinality t(value,ord) where ord<=24)
 )<>8 then raise exception 'Early reading questions changed; release aborted'; end if;
 update academy_tcf_reading.published_papers set version='tcf-reading-2026-11-close-reading-v4' where test_id in ('tcf-reading-07','tcf-reading-08','tcf-reading-09','tcf-reading-10','tcf-reading-11','tcf-reading-12','tcf-reading-13','tcf-reading-14') and version='tcf-reading-2026-11-reference-v3';
 get diagnostics updated_rows=row_count;
 if updated_rows<>8 then raise exception 'Expected exactly eight updates, got %',updated_rows; end if;
end $activate$;
do $verify$ begin
 if (select count(*) from academy_tcf_reading.published_papers)<>20 then raise exception 'Catalog count changed'; end if;
 if (select count(*) from academy_tcf_reading.published_papers where test_id in ('tcf-reading-07','tcf-reading-08','tcf-reading-09','tcf-reading-10','tcf-reading-11','tcf-reading-12','tcf-reading-13','tcf-reading-14') and version='tcf-reading-2026-11-close-reading-v4')<>8 then raise exception 'Eight target publications not active'; end if;
 if (select count(*) from academy_tcf_reading.papers where id in ('tcf-reading-07','tcf-reading-08','tcf-reading-09','tcf-reading-10','tcf-reading-11','tcf-reading-12','tcf-reading-13','tcf-reading-14') and version='tcf-reading-2026-11-close-reading-v4' and jsonb_array_length(content->'questions')=39 and (content->>'seconds')::int=3600 and (content->>'maxPoints')::int=699)<>8 then raise exception 'Incorrect bank structure'; end if;
 if exists((select test_id,version from release_reading_07_14_other_pointers except select test_id,version from academy_tcf_reading.published_papers)
 union all (select test_id,version from academy_tcf_reading.published_papers where test_id not in ('tcf-reading-07','tcf-reading-08','tcf-reading-09','tcf-reading-10','tcf-reading-11','tcf-reading-12','tcf-reading-13','tcf-reading-14') except select test_id,version from release_reading_07_14_other_pointers)) then raise exception 'Other reading pointers modified'; end if;
 if (select count(*) from academy_tcf_reading.papers)<>(select old_bank_count+8 from release_reading_07_14_before) then raise exception 'Historical bank count mismatch'; end if;
 if (select md5(coalesce(string_agg(to_jsonb(p)::text,'' order by id,version),'')) from academy_tcf_reading.papers p where not (id in ('tcf-reading-07','tcf-reading-08','tcf-reading-09','tcf-reading-10','tcf-reading-11','tcf-reading-12','tcf-reading-13','tcf-reading-14') and version='tcf-reading-2026-11-close-reading-v4'))<>(select original_banks_digest from release_reading_07_14_before) then raise exception 'Historical bank contents altered'; end if;
 if (select count(*) from academy_tcf_reading.attempts)<>(select attempt_count from release_reading_07_14_before) or
 (select md5(coalesce(string_agg(to_jsonb(a)::text,'' order by id),'')) from academy_tcf_reading.attempts a)<>(select attempts_digest from release_reading_07_14_before) then raise exception 'Student attempts altered'; end if;
end $verify$;
commit;